window.EMBEDDED_DATA = {
  physics: [{"id": 1, "subject": "Physics", "chapter": "Kinematics", "question": "A body moving with uniform acceleration travels 40 m in the first 2 s and 60 m in the next 2 s. What is the initial velocity and acceleration of the body?", "options": {"A": "u = 15 m/s, a = 5 m/s²", "B": "u = 10 m/s, a = 5 m/s²", "C": "u = 15 m/s, a = 10 m/s²", "D": "u = 20 m/s, a = 5 m/s²"}, "correctAnswer": "A", "correctAnswerText": "u = 15 m/s, a = 5 m/s²", "explanation": "Using s = ut + ½at² for the first 2 s: 40 = 2u + 2a, i.e. u + a = 20. For the first 4 s total displacement is 40 + 60 = 100 m: 100 = 4u + 8a, i.e. u + 2a = 25. Subtracting the two equations gives a = 5 m/s², and substituting back gives u = 15 m/s. Hence option A is correct.", "hasImage": false, "image": null}, {"id": 2, "subject": "Physics", "chapter": "Kinematics", "question": "A ball thrown vertically upward returns to the thrower after 6 s. The initial velocity of the ball is (g = 10 m/s²)", "options": {"A": "20 m/s", "B": "25 m/s", "C": "30 m/s", "D": "35 m/s"}, "correctAnswer": "C", "correctAnswerText": "30 m/s", "explanation": "Total time of flight for vertical throw is T = 2u/g. Given T = 6 s and g = 10 m/s², we get u = gT/2 = (10 × 6)/2 = 30 m/s. The ball takes 3 s to rise and 3 s to fall back. Hence option C is correct.", "hasImage": false, "image": null}, {"id": 3, "subject": "Physics", "chapter": "Laws of Motion", "question": "A 5 kg block is placed on a frictionless table. A force of 20 N acts on it. The acceleration of the block is", "options": {"A": "2 m/s²", "B": "4 m/s²", "C": "5 m/s²", "D": "10 m/s²"}, "correctAnswer": "B", "correctAnswerText": "4 m/s²", "explanation": "Newton's second law states F = ma. Rearranging, a = F/m = 20/5 = 4 m/s². The acceleration is directly proportional to force and inversely proportional to mass. Hence option B is correct.", "hasImage": false, "image": null}, {"id": 4, "subject": "Physics", "chapter": "Laws of Motion", "question": "An object of mass 2 kg is moving with a speed of 3 m/s. The kinetic energy of the object is", "options": {"A": "3 J", "B": "6 J", "C": "9 J", "D": "18 J"}, "correctAnswer": "C", "correctAnswerText": "9 J", "explanation": "Kinetic energy is given by K = ½mv² = ½ × 2 × (3)² = 9 J. Kinetic energy is a scalar quantity and depends on the square of the speed, so doubling speed quadruples the energy. Hence option C is correct.", "hasImage": false, "image": null}, {"id": 5, "subject": "Physics", "chapter": "Work, Energy and Power", "question": "A force of 10 N acts on a body through a distance of 5 m in the direction of the force. The work done is", "options": {"A": "50 J", "B": "25 J", "C": "10 J", "D": "5 J"}, "correctAnswer": "A", "correctAnswerText": "50 J", "explanation": "Work done W = F × s × cosθ. Since force and displacement are in the same direction, θ = 0° and cos 0° = 1. Hence W = 10 × 5 = 50 J. Work is a scalar quantity measured in joules. Hence option A is correct.", "hasImage": false, "image": null}, {"id": 6, "subject": "Physics", "chapter": "Work, Energy and Power", "question": "The SI unit of power is", "options": {"A": "Joule", "B": "Watt", "C": "Newton", "D": "Horsepower"}, "correctAnswer": "B", "correctAnswerText": "Watt", "explanation": "Power is the rate of doing work, P = W/t. Its SI unit is the watt (W), equal to one joule per second. Horsepower is a practical unit, and Newton is the SI unit of force. Hence option B is correct.", "hasImage": false, "image": null}, {"id": 7, "subject": "Physics", "chapter": "Gravitation", "question": "The value of acceleration due to gravity at a height equal to the radius of the Earth (R) above the Earth's surface is (g₀ = acceleration at surface)", "options": {"A": "g₀", "B": "g₀/2", "C": "g₀/4", "D": "g₀/8"}, "correctAnswer": "C", "correctAnswerText": "g₀/4", "explanation": "Acceleration due to gravity varies as g = g₀ (R/(R+h))². At height h = R, we get g = g₀(R/2R)² = g₀/4. This follows from the inverse square law of gravitation. Hence option C is correct.", "hasImage": false, "image": null}, {"id": 8, "subject": "Physics", "chapter": "Gravitation", "question": "Kepler's second law of planetary motion is a consequence of conservation of", "options": {"A": "Energy", "B": "Linear momentum", "C": "Angular momentum", "D": "Mass"}, "correctAnswer": "C", "correctAnswerText": "Angular momentum", "explanation": "Kepler's second law (equal areas in equal times) implies that the areal velocity of a planet is constant. This happens because the gravitational force is central, exerting zero torque, so angular momentum is conserved. Hence option C is correct.", "hasImage": false, "image": null}, {"id": 9, "subject": "Physics", "chapter": "Properties of Matter", "question": "Young's modulus of a wire is defined as the ratio of", "options": {"A": "Longitudinal stress to longitudinal strain", "B": "Volume stress to volume strain", "C": "Shearing stress to shearing strain", "D": "Force to area"}, "correctAnswer": "A", "correctAnswerText": "Longitudinal stress to longitudinal strain", "explanation": "Young's modulus Y = (Longitudinal stress)/(Longitudinal strain) = (F/A)/(ΔL/L). It measures the stiffness of a material under axial loading. Bulk modulus relates volume stress and strain while shear modulus relates shearing quantities. Hence option A is correct.", "hasImage": false, "image": null}, {"id": 10, "subject": "Physics", "chapter": "Properties of Matter", "question": "Water rises in a capillary tube because of", "options": {"A": "Viscosity", "B": "Surface tension", "C": "Gravity", "D": "Elasticity"}, "correctAnswer": "B", "correctAnswerText": "Surface tension", "explanation": "Capillary rise is due to surface tension and the adhesive forces between water and the tube wall. The liquid is pulled up until the upward force of surface tension balances the weight of the liquid column. Hence option B is correct.", "hasImage": false, "image": null}, {"id": 11, "subject": "Physics", "chapter": "Thermodynamics", "question": "In an isothermal process, the change in internal energy of an ideal gas is", "options": {"A": "Positive", "B": "Negative", "C": "Zero", "D": "Maximum"}, "correctAnswer": "C", "correctAnswerText": "Zero", "explanation": "For an ideal gas, internal energy depends only on temperature. In an isothermal process temperature stays constant, so the change in internal energy ΔU = 0. According to the first law, Q = W in such a process. Hence option C is correct.", "hasImage": false, "image": null}, {"id": 12, "subject": "Physics", "chapter": "Thermodynamics", "question": "The first law of thermodynamics is a statement of conservation of", "options": {"A": "Angular momentum", "B": "Energy", "C": "Mass", "D": "Charge"}, "correctAnswer": "B", "correctAnswerText": "Energy", "explanation": "The first law of thermodynamics, ΔQ = ΔU + ΔW, states that heat supplied to a system goes into increasing internal energy and doing external work. It is a restatement of the law of conservation of energy. Hence option B is correct.", "hasImage": false, "image": null}, {"id": 13, "subject": "Physics", "chapter": "Electrostatics", "question": "The SI unit of electric charge is", "options": {"A": "Ampere", "B": "Volt", "C": "Coulomb", "D": "Farad"}, "correctAnswer": "C", "correctAnswerText": "Coulomb", "explanation": "Charge is measured in coulombs (C). One coulomb is the quantity of charge transported by a current of one ampere in one second. Ampere measures current, volt measures potential, and farad measures capacitance. Hence option C is correct.", "hasImage": false, "image": null}, {"id": 14, "subject": "Physics", "chapter": "Electrostatics", "question": "Two point charges 2 μC and 8 μC attract each other with a force F. If the distance between them is halved, the new force will be", "options": {"A": "F", "B": "2F", "C": "4F", "D": "8F"}, "correctAnswer": "C", "correctAnswerText": "4F", "explanation": "Coulomb's law: F ∝ 1/r². When distance is halved (r becomes r/2), the force becomes F × (r/(r/2))² = 4F. The electrostatic force follows the inverse square law. Hence option C is correct.", "hasImage": false, "image": null}, {"id": 15, "subject": "Physics", "chapter": "Modern Physics", "question": "The dual nature of matter was proposed by", "options": {"A": "Einstein", "B": "de Broglie", "C": "Bohr", "D": "Planck"}, "correctAnswer": "B", "correctAnswerText": "de Broglie", "explanation": "Louis de Broglie proposed that matter particles have a wave associated with them, given by λ = h/mv, known as the de Broglie wavelength. This wave–particle duality was experimentally confirmed by Davisson and Germer. Hence option B is correct.", "hasImage": false, "image": null}],
  chemistry: [{"id": 1, "subject": "Chemistry", "chapter": "Polymers", "question": "Which of the following set of polymers are used as fibre?\n(i) Teflon\n(ii) Starch\n(iii) Terylene\n(iv) Orlon", "options": {"A": "(i) and (ii)", "B": "(ii) and (iii)", "C": "(iii) and (iv)", "D": "(i) and (iv)"}, "correctAnswer": "C", "correctAnswerText": "(iii) and (iv)", "explanation": "Fibres are a class of polymers that are thin, thread-like, and possess high tensile strength and a highly ordered crystalline structure. They are used to make fabrics and ropes. Terylene (also called Dacron) is a polyester obtained by the condensation polymerisation of ethylene glycol and terephthalic acid. Orlon is a polyacrylonitrile (PAN) fibre obtained by the addition polymerisation of acrylonitrile. Both are typical synthetic fibres with strong intermolecular forces (hydrogen bonding or dipole interactions) that give them high tensile strength. Teflon is polytetrafluoroethylene (PTFE), which is a very non-stick, heat-resistant polymer used for non-stick cookware coatings and as a lubricant; it is classified as a thermosetting-like, tough plastic, not a fibre. Starch is a natural polysaccharide (a carbohydrate made of α-D-glucose units) used as a food reserve; it is a biodegradable polymer but is not used as a fibre. Therefore only Terylene and Orlon (iii and iv) are fibres. A common mistake students make is to classify Teflon as a fibre because it is a polymer; remember that Teflon is used for coatings and has a very high softening temperature, whereas fibres must be spinnable into long thin threads. Hence the correct option is C.", "hasImage": false, "image": null}, {"id": 2, "subject": "Chemistry", "chapter": "Polymers", "question": "The biodegradable polymer obtained by polymerisation of Glycine and Aminocaproic acid is", "options": {"A": "Nylon 6", "B": "PHBV", "C": "Nylon 2 – Nylon 6", "D": "Nylon 6, 10"}, "correctAnswer": "C", "correctAnswerText": "Nylon 2 – Nylon 6", "explanation": "Nylon 2 – Nylon 6 is a biodegradable polymer, also called a 'nylon' prepared by the copolymerisation of glycine (which contributes the 'Nylon 2' part, since glycine has two carbons) and aminocaproic acid (which contributes the 'Nylon 6' part, since aminocaproic acid has six carbons). Glycine is NH2–CH2–COOH and aminocaproic acid is NH2–(CH2)5–COOH. The amide bonds in this alternating copolymer are similar to the peptide bonds found in proteins, and because of this protein-like structure it can be broken down by enzymes in the environment, making it biodegradable. Nylon 6 is obtained by the polymerisation of caprolactam alone; it is a synthetic fibre that is not biodegradable. PHBV (poly-β-hydroxybutyrate-co-β-hydroxyvalerate) is indeed biodegradable, but it is obtained from β-hydroxybutyric acid and β-hydroxyvaleric acid, not from glycine and aminocaproic acid. Nylon 6, 10 is obtained from hexamethylenediamine and sebacic acid and is not biodegradable. The key point to remember is that the numbers in nylon names indicate the number of carbon atoms in the monomers; Nylon 2–Nylon 6 is special because it contains glycine and is biodegradable. Hence the correct option is C.", "hasImage": false, "image": null}, {"id": 3, "subject": "Chemistry", "chapter": "Chemistry in Everyday Life", "question": "Identify the compound whose structure contains a five-membered ring with an -SO2- group, two carbonyl-like structures fused to benzene (a benzoisothiazole ring system with a sulfonyl and an imide group).", "options": {"A": "Sucralose", "B": "Aspartame", "C": "Saccharin", "D": "Alitame"}, "correctAnswer": "C", "correctAnswerText": "Saccharin", "explanation": "Saccharin (C7H5NO3S) is the oldest artificial sweetener, discovered in 1879, and is about 550 times sweeter than sucrose. Its structure consists of a benzene ring fused to a five-membered ring containing a sulfonyl group (-SO2-) and an imide group (-CO-NH-CO-), i.e., a benzoisothiazole ring with N-H. This characteristic ring system is present in the structure given in the question. Sucralose is a chlorinated derivative of sucrose (a disaccharide) in which three hydroxyl groups are replaced by chlorine atoms; its structure is a modified sugar molecule, not a benzoisothiazole. Aspartame is a dipeptide methyl ester made of aspartic acid and phenylalanine (methyl ester), so it has peptide bonds and is about 100 times sweeter than sugar; it does not contain sulfur. Alitame is also a dipeptide-based sweetener containing aspartic acid and alanine, with a thio group in the amide portion, but it does not have the saccharin-type fused ring system. The presence of the SO2-NH-CO ring fused to benzene is the unique structural feature that identifies saccharin. A common mistake is confusing aspartame with saccharin; remember aspartame has two amino acid units (peptide) while saccharin is a sulfonimide heterocycle. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 4, "subject": "Chemistry", "chapter": "Chemistry in Everyday Life", "question": "Which one of the following is a cationic detergent?", "options": {"A": "Cetyltrimethylammonium bromide", "B": "Sodium dodecylbenzene sulphonate", "C": "Dodecylbenzene sulphonic acid", "D": "Dodecylbenzene"}, "correctAnswer": "A", "correctAnswerText": "Cetyltrimethylammonium bromide", "explanation": "Detergents are classified as cationic, anionic or non-ionic depending on the charge on the large hydrocarbon part (the surfactant ion). A cationic detergent has a positively charged head group (usually a quaternary ammonium ion). Cetyltrimethylammonium bromide, whose cation is C16H33N+(CH3)3, carries a permanent positive charge on nitrogen, so it is a cationic detergent. It is used in hair conditioners and fabric softeners because the positive charge helps it attach to negatively charged surfaces. Sodium dodecylbenzene sulphonate is an anionic detergent because the sulphonate group (-SO3-) carries a negative charge; it is the main ingredient of many household detergents. Dodecylbenzene sulphonic acid is also anionic (the acidic -SO3H group can ionise to give a negatively charged sulphonate). Dodecylbenzene has no polar or ionic head group at all; it is just a hydrocarbon and has no cleansing action, so it is not a detergent. The trick in this question is to look for the permanently charged species: a quaternary ammonium group (N+) means cationic, while -SO3- means anionic. Cationic detergents are generally quaternary ammonium salts. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 5, "subject": "Chemistry", "chapter": "Biomolecules", "question": "The type of linkage present between nucleotides is", "options": {"A": "Phosphoester linkage", "B": "Phosphodiester linkage", "C": "Amide linkage", "D": "Glycosidic linkage"}, "correctAnswer": "B", "correctAnswerText": "Phosphodiester linkage", "explanation": "Nucleotides are the building blocks of nucleic acids (DNA and RNA). Each nucleotide has three parts: a nitrogenous base, a pentose sugar (ribose or deoxyribose) and a phosphate group. When nucleotides are joined together to form a polynucleotide chain, the phosphate group links the 3'-hydroxyl group of one sugar to the 5'-hydroxyl group of the next sugar. Since this bond is formed through TWO ester linkages (one to each sugar hydroxyl), it is called a 3'–5' phosphodiester linkage. The name 'di-ester' indicates that the phosphate is esterified to two different sugar molecules. A phosphoester linkage is a single ester bond between a phosphate and one hydroxyl group; it occurs within a single nucleotide (linking the phosphate to the 5' carbon of its own sugar), not between two nucleotides. An amide (peptide) linkage is the bond between amino acids in proteins, so it is not relevant to nucleic acids. A glycosidic linkage is the bond that joins two monosaccharides in a disaccharide or polysaccharide (for example, the α-1,4-glycosidic bond in starch or maltose). Therefore, the correct bond joining nucleotide monomers in the polynucleotide chain is the phosphodiester linkage. Remember: nucleotides are joined 'phospho-DI-ester' because the phosphate makes two ester links, one with each neighbouring sugar. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 6, "subject": "Chemistry", "chapter": "Biomolecules", "question": "α-D-(+)-glucose and β-D-(+)-glucose are", "options": {"A": "Enantiomers", "B": "Conformers", "C": "Epimers", "D": "Anomers"}, "correctAnswer": "D", "correctAnswerText": "Anomers", "explanation": "α-D-(+)-glucose and β-D-(+)-glucose differ only in the configuration at the anomeric carbon (C1), which is the hemiacetal carbon. In cyclic form, α-glucose has the -OH group on C1 below the plane (trans to the -CH2OH group at C5), while β-glucose has it above the plane. Such diastereomers that differ only at the anomeric (hemiacetal) carbon are called anomers. They interconvert in aqueous solution through the open-chain form, a process called mutarotation, and both give the same open-chain aldehyde. Enantiomers are non-superimposable mirror images that differ at ALL stereocentres; α and β glucose differ at only one centre, so they are not mirror images. Conformers are different spatial arrangements obtained by rotation about single bonds (conformational isomers), which does not apply here because the difference is a configurational one that requires bond breaking. Epimers are diastereomers that differ in configuration at any single chiral centre EXCEPT the anomeric carbon; for example, D-glucose and D-mannose differ at C2 and are epimers, as are D-glucose and D-galactose (differ at C4). The special name given when the differing centre is C1 (anomeric carbon) is anomer. Remember the mnemonic: anomeric carbon is C1 (the aldehyde carbon in cyclic form), and α/β designation refers to the position of OH at C1 only. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 7, "subject": "Chemistry", "chapter": "Organic Chemistry: Some Basic Principles and Techniques", "question": "Propanone and Propanal are", "options": {"A": "Position isomers", "B": "Functional isomers", "C": "Chain isomers", "D": "Geometrical isomers"}, "correctAnswer": "B", "correctAnswerText": "Functional isomers", "explanation": "Propanone (CH3-CO-CH3) is a ketone and propanal (CH3-CH2-CHO) is an aldehyde. Both have the same molecular formula, C3H6O, but they contain different functional groups: propanone contains a carbonyl group (-CO-) inside the carbon chain (ketone), while propanal contains a terminal -CHO group (aldehyde). Isomers that have the same molecular formula but different functional groups are called functional isomers. This is the clearest example of functional isomerism for C3H6O. Position isomers have the same functional group but at different positions on the same carbon skeleton; for example, propan-1-ol and propan-2-ol. Chain isomers have the same functional group and formula but different carbon skeletons (branching); for example, butane and 2-methylpropane. Geometrical (cis-trans) isomers arise from restricted rotation around a double bond or a ring, with different spatial arrangements of groups; this requires a C=C bond and is not applicable to propanone or propanal, which have no C=C bonds. The simple way to spot functional isomers is to check the formula: if two compounds share the same formula but belong to different homologous series (here aldehyde vs ketone), they are functional isomers. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 8, "subject": "Chemistry", "chapter": "Hydrocarbons", "question": "Sodium ethanoate on heating with soda lime gives 'X'. Electrolysis of aqueous solution of sodium ethanoate gives 'Y'. 'X' and 'Y' respectively are", "options": {"A": "Methane and Ethane", "B": "Methane and Methane", "C": "Ethane and Methane", "D": "Ethane and Ethane"}, "correctAnswer": "A", "correctAnswerText": "Methane and Ethane", "explanation": "When sodium ethanoate (sodium acetate, CH3COONa) is heated with soda lime (a mixture of NaOH and CaO), decarboxylation occurs and a methyl group (-CH3) with one hydrogen from the methylene is lost as carbon dioxide; the product is methane. The reaction is: CH3COONa + NaOH →(CaO, Δ) CH4 + Na2CO3. This is the laboratory preparation of methane (X = CH4). On the other hand, electrolysis of an aqueous solution of sodium ethanoate is called Kolbe's electrolysis. At the anode, acetate ions lose electrons to give free radicals, which immediately dimerise to produce ethane along with carbon dioxide and hydrogen: 2CH3COONa + 2H2O →(electrolysis) C2H6 + 2NaOH + 2CO2 + H2. So the product at the anode is ethane (Y = C2H6). Therefore X is methane and Y is ethane. A very common mistake is to mix up these two reactions: heating with soda lime (decarboxylation) gives the alkane with one carbon fewer (methane from acetate), while electrolysis (Kolbe's reaction) couples the alkyl groups to give ethane. Remember: soda lime/decarboxylation → CH4; Kolbe electrolysis → C2H6. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 9, "subject": "Chemistry", "chapter": "Aldehydes, Ketones and Carboxylic Acids", "question": "But-1-yne on reaction with dil. H2SO4 in presence of Hg2+ ions at 333 K gives", "options": {"A": "Butan-2-one", "B": "Butanal", "C": "Butan-1-ol", "D": "Butan-1-one (Butanal)"}, "correctAnswer": "A", "correctAnswerText": "Butan-2-one", "explanation": "This reaction is the acid-catalysed hydration of an alkyne (Kucherov reaction). But-1-yne, CH3-CH2-C≡CH, reacts with dilute H2SO4 in the presence of Hg2+ ions (usually HgSO4) at about 333 K. Water adds across the triple bond to give an unstable intermediate called an enol (vinyl alcohol): CH3-CH2-C(OH)=CH2. This enol immediately tautomerises (keto-enol tautomerism) to the more stable keto form. According to Markovnikov's rule, the -OH adds to the more substituted carbon, so the enol has the OH on the internal carbon (C2). After tautomerisation, we get a ketone with the carbonyl at C2, i.e., butan-2-one (CH3-CO-CH2-CH3). The reaction is: CH3CH2C≡CH + H2O →(Hg2+, H+, 333 K) [CH3CH2C(OH)=CH2] → CH3CH2COCH3. Terminal alkynes other than acetylene give methyl ketones by this reaction; only acetylene itself gives acetaldehyde (an aldehyde). So butan-2-one is correct because the carbon attached to the triple bond carries a hydrogen and the water adds giving a methyl ketone. Butanal is not formed because internal alkynes do not give aldehydes, and butan-1-ol or butan-1-one are not the products of alkyne hydration. A key exam point: alkyne + H2O/Hg2+ gives a carbonyl compound; internal alkyne → ketone, terminal alkyne other than ethyne → methyl ketone. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 10, "subject": "Chemistry", "chapter": "Amines", "question": "Biologically active adrenaline and ephedrine used to increase blood pressure contain", "options": {"A": "Primary amino group", "B": "Secondary amino group", "C": "Tertiary amino group", "D": "Quaternary ammonium salt"}, "correctAnswer": "B", "correctAnswerText": "Secondary amino group", "explanation": "Adrenaline (epinephrine) is a hormone secreted by the adrenal medulla and is used as a drug to raise blood pressure, especially during cardiac arrest or anaphylactic shock. Ephedrine is an alkaloid obtained from Ephedra plants and is used as a bronchodilator and decongestant. In both molecules, the nitrogen atom is bonded to a carbon chain and carries one hydrogen and is attached to two carbon-containing groups; i.e., the nitrogen is bonded to two alkyl/aryl carbons (the methyl group -CH3 and the ethylamine side chain) and one hydrogen, which makes it a secondary amino group (-NH-). In adrenaline, the nitrogen is attached to the benzyl carbon (C6H3(OH)2-CH(OH)-CH2-) and to a -CH3 group, so it is a secondary amine. In ephedrine, the nitrogen is bonded to the CH3 group and the C6H5-CH(CH3)-CH(OH)- group, again making it a secondary amine. A primary amino group has nitrogen attached to one carbon and two hydrogens (-NH2); a tertiary amino group has nitrogen attached to three carbons (no N-H); a quaternary ammonium salt has a positively charged nitrogen attached to four groups (R4N+). Since adrenaline and ephedrine both contain an -NH-CH3 or -NH- type group (one N-H bond and two C-N bonds), they contain secondary amino groups. Remember: count the number of C-N bonds - one C-N = primary, two C-N = secondary, three C-N = tertiary. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 11, "subject": "Chemistry", "chapter": "Amines", "question": "In the reaction, Aniline →(NaNO2 + dil. HCl) P →(Phenol + NaOH) Q, identify Q.", "options": {"A": "C6H5N2Cl", "B": "ortho-hydroxyazobenzene", "C": "para-hydroxyazobenzene", "D": "meta-hydroxyazobenzene"}, "correctAnswer": "C", "correctAnswerText": "para-hydroxyazobenzene", "explanation": "The reaction sequence is the preparation of an azo dye. First, aniline (C6H5NH2) reacts with sodium nitrite (NaNO2) and dilute HCl at low temperature (0-5°C) to form benzenediazonium chloride, C6H5N2+Cl- (this is P). This is called diazotisation. Then the diazonium salt P is treated with phenol (C6H5OH) in alkaline medium (NaOH). In a basic medium, phenol exists as the phenoxide ion (C6H5O-), which is an activated aromatic ring. The diazonium cation (an electrophile) attacks the aromatic ring of the phenoxide ion and couples with it. The coupling occurs para to the -OH group (the para position is the most reactive and least sterically hindered; ortho is also possible but para is favoured). The product is para-hydroxyazobenzene, which has the structure HO-C6H4-N=N-C6H5. This is a red-orange azo dye. The para position is preferred over ortho because of steric hindrance at the ortho positions. Meta-hydroxyazobenzene is not formed because the -OH group is an ortho/para director, so the incoming diazonium group never goes to the meta position. C6H5N2Cl is the intermediate P, not the final product Q. This reaction is called diazo coupling and is used to synthesise azo dyes such as methyl orange. Remember: phenol (alkaline) + diazonium salt → para-hydroxyazobenzene (azo dye). Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 12, "subject": "Chemistry", "chapter": "Chemistry in Everyday Life", "question": "The female sex hormone which is responsible for the development of secondary female characteristics and participates in the control of menstrual cycle is", "options": {"A": "Testosterone", "B": "Estradiol", "C": "Insulin", "D": "Thyroxine"}, "correctAnswer": "B", "correctAnswerText": "Estradiol", "explanation": "Estradiol (also called oestradiol) is the principal female sex hormone belonging to the oestrogen family. It is secreted by the ovaries and is responsible for the development of secondary sexual characteristics in females such as breast development, widening of hips, deposition of fat, and development of the reproductive organs. It also participates in regulating the menstrual cycle along with progesterone. Estradiol is a steroid hormone with a phenolic A-ring. Testosterone is the male sex hormone (an androgen) responsible for male secondary sexual characteristics; it is secreted by the testes. Insulin is a peptide hormone secreted by the beta cells of the pancreas; it regulates blood glucose levels and is not a sex hormone. Thyroxine (T4) is an iodine-containing amino-acid derivative secreted by the thyroid gland; it regulates basal metabolic rate and growth. The key distinguishing point is that sex hormones are steroids and are produced by the gonads - estradiol by ovaries (female) and testosterone by testes (male). The question specifically asks for the female hormone controlling the menstrual cycle and female secondary characteristics, which is estradiol. A common mistake is choosing testosterone, but that is the male hormone. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 13, "subject": "Chemistry", "chapter": "Haloalkanes and Haloarenes", "question": "In the following scheme of reaction:\nC2H5Cl →(X) C2H5F →(Y) CH2=CH2 →(Z) C4H10,\nX, Y and Z respectively are:", "options": {"A": "AgF, alcoholic KOH and benzene", "B": "HF, aqueous KOH and Na in dry ether", "C": "Hg2F2, alcoholic KOH and Na in dry ether", "D": "CoF2, aqueous KOH and benzene"}, "correctAnswer": "C", "correctAnswerText": "Hg2F2, alcoholic KOH and Na in dry ether", "explanation": "The first step converts chloroethane (C2H5Cl) into fluoroethane (C2H5F). This is a halogen exchange reaction (Finkelstein-type, but for F) in which a mercurous fluoride such as Hg2F2 or a silver fluoride is used because the Ag+ or Hg2+ ion precipitates the chloride ion, driving the equilibrium. Since chloroethane is an alkyl halide, it reacts with Hg2F2 (mercurous fluoride) to give C2H5F and Hg2Cl2. X = Hg2F2. The second step converts C2H5F (ethyl fluoride) into ethene (CH2=CH2). Heating an alkyl halide with alcoholic KOH causes dehydrohalogenation (elimination of HX) to form an alkene. So Y = alcoholic KOH. The third step converts ethene (CH2=CH2) into butane (C4H10). The dimerisation of two ethene molecules to butane is not a direct simple reaction; however, the intended reaction is the Wurtz-type coupling after converting ethene to an organosodium intermediate, or more simply, ethene is hydrogenated. In this classic scheme, Z is Na in dry ether (the Wurtz reaction pathway). Note the intended chemistry: ethene is first converted to ethyl group(s) and coupled. The correct sequence of reagents matches option C: Hg2F2 (for F exchange), alcoholic KOH (elimination to alkene), Na in dry ether (Wurtz coupling). AgF would give the fluoro compound but then options with benzene or KMnO4 do not fit the alkene→butane step. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 14, "subject": "Chemistry", "chapter": "Alcohols, Phenols and Ethers", "question": "8.8 g of monohydric alcohol added to ethyl magnesium iodide in ether liberates 2240 cm3 of ethane at STP. This monohydric alcohol when oxidised using pyridinium-chlorochromate forms a carbonyl compound that answers silver mirror test (Tollen's test). The monohydric alcohol is", "options": {"A": "butan-2-ol", "B": "2, 2-dimethyl propan-1-ol", "C": "pentan-2-ol", "D": "2, 2-dimethyl ethan-1-ol"}, "correctAnswer": "B", "correctAnswerText": "2, 2-dimethyl propan-1-ol", "explanation": "A monohydric alcohol (R-OH) reacts with ethyl magnesium iodide (a Grignard reagent) to liberate ethane gas by replacing the acidic -OH hydrogen: ROH + C2H5MgI → ROMgI + C2H6. One mole of alcohol releases one mole of ethane (22,400 cm3 at STP). Here, 2240 cm3 of ethane is released, which is 2240/22400 = 0.1 mol of ethane, hence 0.1 mol of alcohol is present. We are given 8.8 g of alcohol for 0.1 mol, so molar mass = 8.8/0.1 = 88 g/mol. For a monohydric alcohol CnH2n+2O, molar mass = 14n + 18 = 88, so 14n = 70, n = 5. So the alcohol has 5 carbons (molecular formula C5H12O). Now, the oxidation product (using PCC) answers the Tollen's test, which means the product is an aldehyde (aldehydes give silver mirror with Tollen's reagent). PCC oxidises primary alcohols to aldehydes without over-oxidising, while secondary alcohols give ketones (which do not answer Tollen's test). So the alcohol must be a primary alcohol with 5 carbons. Among the options, only 2,2-dimethylpropan-1-ol (neopentyl alcohol, (CH3)3C-CH2OH) is a primary alcohol with 5 carbons and molar mass 88. Butan-2-ol and pentan-2-ol are secondary alcohols (give ketones on PCC oxidation), and 2,2-dimethyl ethan-1-ol is not a valid 5-carbon primary alcohol. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 15, "subject": "Chemistry", "chapter": "Alcohols, Phenols and Ethers", "question": "When a tertiary alcohol 'A' (C4H10O) reacts with 20% H3PO4 at 358 K, it gives a compound 'B' (C4H8) as a major product. The IUPAC name of the compound 'B' is", "options": {"A": "But-1-ene", "B": "But-2-ene", "C": "Cyclobutane", "D": "2-Methylpropene"}, "correctAnswer": "D", "correctAnswerText": "2-Methylpropene", "explanation": "A tertiary alcohol with molecular formula C4H10O is 2-methylpropan-2-ol, (CH3)3C-OH (tert-butyl alcohol). When heated with 20% phosphoric acid (a dehydrating agent) at 358 K, it undergoes acid-catalysed dehydration (elimination of water) to give an alkene with formula C4H8. Dehydration follows Saytzeff's rule but, more importantly, for tert-butyl alcohol the product is 2-methylpropene, (CH3)2C=CH2, because elimination of water from (CH3)3C-OH gives (CH3)2C=CH2 (the double bond forms between the central carbon and one of the methyl carbons). This is the only possible alkene from tert-butyl alcohol apart from the highly unstable isomer that would require removing H from a different position. 2-Methylpropene is an alkene with a branched carbon skeleton (isobutene). But-1-ene (CH2=CH-CH2-CH3) and but-2-ene (CH3-CH=CH-CH3) would be obtained from dehydration of butan-1-ol or butan-2-ol (primary/secondary alcohols), not from the tertiary alcohol. Cyclobutane has the same formula C4H8 but is a cyclic alkane, and dehydration of an alcohol gives an alkene, not a cycloalkane. The key identification: the tertiary alcohol C4H10O must be 2-methylpropan-2-ol, and its dehydration gives 2-methylpropene. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 16, "subject": "Chemistry", "chapter": "Aldehydes, Ketones and Carboxylic Acids", "question": "PCC is", "options": {"A": "K2Cr2O7 + Pyridine", "B": "CrO3 + CHCl3", "C": "CrO3 + H2SO4", "D": "A complex of chromium trioxide with pyridine + HCl"}, "correctAnswer": "D", "correctAnswerText": "A complex of chromium trioxide with pyridine + HCl", "explanation": "PCC stands for pyridinium chlorochromate. It is a complex salt formed by dissolving chromium trioxide (CrO3) in concentrated hydrochloric acid and then adding pyridine. The product is C5H5NH+CrO3Cl- (pyridinium chlorochromate, C5H6CrClNO3). PCC is a mild oxidising agent, which is its most important feature: it selectively oxidises primary alcohols to aldehydes and secondary alcohols to ketones without further oxidation of the aldehyde to carboxylic acid. For example, ethanol is oxidised to ethanal (acetaldehyde) by PCC, whereas strong oxidising agents like K2Cr2O7/H2SO4 or acidic KMnO4 would oxidise it all the way to ethanoic acid. Option A (K2Cr2O7 + pyridine) is not the standard PCC composition; potassium dichromate with pyridine is not pyridinium chlorochromate. Option B (CrO3 + CHCl3) is a different mixture and not PCC. Option C (CrO3 + H2SO4) is Jones reagent (acidic chromium trioxide), a strong oxidant that converts primary alcohols to acids. The distinguishing feature of PCC is the pyridinium cation (C5H5NH+) combined with the chlorochromate anion (CrO3Cl-), which comes from pyridine + HCl + CrO3. Remember the mnemonic: PCC = Pyridinium ChloroChromate = pyridine + HCl + CrO3. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 17, "subject": "Chemistry", "chapter": "Coordination Compounds", "question": "On treating 100 mL of 0.1 M aqueous solution of the complex CrCl3·6H2O with excess of AgNO3, 2.86 g of AgCl was obtained. The complex is", "options": {"A": "[Cr(H2O)3Cl3]·3H2O", "B": "[Cr(H2O)4Cl2]Cl·2H2O", "C": "[Cr(H2O)5Cl]Cl2·H2O", "D": "[Cr(H2O)6]Cl3"}, "correctAnswer": "C", "correctAnswerText": "[Cr(H2O)5Cl]Cl2·H2O", "explanation": "The number of chloride ions that can be precipitated by AgNO3 depends on how many Cl- ions are present outside the coordination sphere (ionisable). Moles of complex = M × V = 0.1 × 0.100 = 0.01 mol. Mass of AgCl obtained = 2.86 g; molar mass of AgCl = 143.5 g/mol, so moles of AgCl = 2.86/143.5 = 0.0199 ≈ 0.02 mol. Thus 0.01 mol of complex gives 0.02 mol of AgCl, meaning each formula unit of the complex releases 2 chloride ions (0.02/0.01 = 2). So two Cl- ions must be outside the coordination sphere (ionic/counter ions). Now check the options: in option C, [Cr(H2O)5Cl]Cl2·H2O, the chromium is in the complex ion [Cr(H2O)5Cl]2+ with 5 water molecules and 1 chloride inside, and there are 2 chloride ions outside (Cl2). This releases 2 Cl- per formula unit on dissociation: [Cr(H2O)5Cl]Cl2 → [Cr(H2O)5Cl]2+ + 2Cl-. This matches the 2.86 g of AgCl (2 moles per mole of complex). Option A has all three Cl inside (gives 0 AgCl), option B has 1 Cl outside (gives 1 mol AgCl), and option D has all three Cl outside (gives 3 mol AgCl). The total water and chloride count is 6 in all options (CrCl3·6H2O). Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 18, "subject": "Chemistry", "chapter": "Coordination Compounds", "question": "The complex compounds [Co(NH3)5SO4]Br and [Co(NH3)5Br]SO4 are", "options": {"A": "Coordination isomers", "B": "Geometrical isomers", "C": "Optical isomers", "D": "Ionisation isomers"}, "correctAnswer": "D", "correctAnswerText": "Ionisation isomers", "explanation": "Ionisation isomerism arises when two coordination compounds have the same molecular formula but exchange a ligand with a counter ion (the ion outside the coordination sphere). In [Co(NH3)5SO4]Br, the sulphate group (SO4) is inside the coordination sphere (a ligand bonded to Co) and bromide is the counter ion outside. In [Co(NH3)5Br]SO4, the bromide is inside the coordination sphere and sulphate is the counter ion outside. Both complexes have the same overall composition, Co(NH3)5SO4Br, but they differ in which ion is inside (bonded) and which is outside (ionic). When dissolved, they produce different ions in solution: the first gives Br- ions and the second gives SO42- ions, so they can be distinguished by precipitation tests. For example, the first complex precipitates AgBr with AgNO3 but not BaSO4, while the second precipitates BaSO4 with BaCl2 but not AgBr. Coordination isomers involve exchange of ligands between the cation and anion in a compound with two coordination spheres (e.g., [Co(NH3)6][Cr(CN)6] and [Cr(NH3)6][Co(CN)6]). Geometrical and optical isomers are stereoisomers, which require the same connectivity but different spatial arrangements, which is not the case here. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 19, "subject": "Chemistry", "chapter": "Coordination Compounds", "question": "Which of the following statements are true about [CoF6]3- ion?\nI) The complex has octahedral geometry.\nII) Coordination number of Co is 3 and oxidation state is +6.\nIII) The complex is sp3d2 hybridised.\nIV) It is a high spin complex.", "options": {"A": "I, II and IV", "B": "I, III and IV", "C": "II and IV", "D": "II, III and IV"}, "correctAnswer": "B", "correctAnswerText": "I, III and IV", "explanation": "In [CoF6]3-, the oxidation state of Co is calculated as x + 6(-1) = -3, so x = +3 (Co is in +3 state, not +6). The coordination number is the number of donor atoms bonded to the metal, which is 6 (six F- ligands), not 3. Since there are 6 ligands arranged around the central Co in a symmetrical way, the geometry is octahedral (statement I is true). Co in +3 state has electronic configuration [Ar]3d6. Fluoride is a weak-field ligand (from the spectrochemical series, where F- is at the weak end), so it does not cause pairing of electrons; the complex is high spin with four unpaired electrons (statements III and IV). For an octahedral complex, the hybridisation is d2sp3 (inner orbital) or sp3d2 (outer orbital). Since F- is a weak-field ligand forming a high-spin complex, the outer orbital hybridisation sp3d2 is used (statement III is true). Thus statements I, III and IV are true, while statement II is false (coordination number is 6 and oxidation state is +3). A common trap in this question is the oxidation state: students forget that F- has a -1 charge and forget to calculate x from the overall charge -3. Remember: weak field ligands (F-, Cl-, H2O in some cases) give high-spin octahedral complexes with sp3d2 hybridisation. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 20, "subject": "Chemistry", "chapter": "Haloalkanes and Haloarenes", "question": "A haloalkane undergoes SN2 or SN1 reaction depending on", "options": {"A": "Solvent used in the reaction", "B": "Low temperature", "C": "The type of halogen atom", "D": "Stability of the haloalkane"}, "correctAnswer": "A", "correctAnswerText": "Solvent used in the reaction", "explanation": "Nucleophilic substitution reactions of haloalkanes can proceed by two mechanisms: SN1 (unimolecular) and SN2 (bimolecular). The choice between them is governed primarily by the nature of the solvent (along with the structure of the substrate and the strength of the nucleophile). Polar protic solvents (like water, ethanol, methanol) favour the SN1 mechanism because they stabilise the carbocation intermediate and the leaving group by solvation through hydrogen bonding. Polar aprotic solvents (like DMF, DMSO, acetone) favour the SN2 mechanism because they do not solvate the nucleophile strongly, leaving the nucleophile free (naked) and more reactive, and they do not stabilise the carbocation. So the solvent is the factor being tested in this question: the same haloalkane can react by SN2 in a polar aprotic solvent and by SN1 in a polar protic solvent. The type of halogen atom influences the rate (reactivity order RI > RBr > RCl) but does not by itself determine the mechanism. Low temperature generally slows reactions but does not switch the mechanism. The stability of the haloalkane is not a standard factor for mechanism selection; rather, the stability of the carbocation intermediate determines whether SN1 is favoured (tertiary > secondary > primary). Hence, among the given choices, the solvent is the correct factor that decides between SN1 and SN2. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 21, "subject": "Chemistry", "chapter": "Haloalkanes and Haloarenes", "question": "2-Methyl propane can be prepared by Wurtz reaction. The haloalkanes taken along with metallic sodium and dry ether are:", "options": {"A": "chloromethane and 2-chloropropane", "B": "chloroethane and chloromethane", "C": "chloroethane and 1-chloropropane", "D": "chloromethane and 1-chloropropane"}, "correctAnswer": "A", "correctAnswerText": "chloromethane and 2-chloropropane", "explanation": "The Wurtz reaction is the coupling of two alkyl halides with metallic sodium in dry ether to form a higher alkane: 2R-X + 2Na →(dry ether) R-R + 2NaX. To prepare 2-methylpropane, which has the structure CH3-CH(CH3)-CH3 (isobutane), we need to couple a methyl group with an isopropyl group. The methyl group comes from chloromethane (CH3Cl) and the isopropyl group comes from 2-chloropropane (CH3-CHCl-CH3). The reaction is: CH3Cl + CH3-CHCl-CH3 + 2Na →(dry ether) CH3-CH(CH3)-CH3 + 2NaCl, giving 2-methylpropane. If we used chloroethane and chloromethane (option B), the product would be propane (coupling CH3 + C2H5 gives C3H8). If we used chloroethane and 1-chloropropane (option C), the product would be pentane (C2H5 + C3H7). If we used chloromethane and 1-chloropropane (option D), the product would be butane (CH3 + CH3CH2CH2 gives n-butane, not 2-methylpropane). Remember that in the Wurtz reaction, mixing two different halides gives a mixture of three products, but the desired product is obtained from the specific combination. To get a branched alkane like 2-methylpropane, the two alkyl groups must be methyl and isopropyl. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 22, "subject": "Chemistry", "chapter": "Equilibrium (Ionic)", "question": "In the analysis of III group basic radicals of salts, the purpose of adding NH4Cl(s) to NH4OH is:", "options": {"A": "to increase the concentration of OH- ions", "B": "to precipitate the radicals of group IV and V", "C": "to suppress the dissociation of NH4OH", "D": "to introduce Cl- ions"}, "correctAnswer": "C", "correctAnswerText": "to suppress the dissociation of NH4OH", "explanation": "In qualitative analysis of basic radicals (cations), group III cations (Fe3+, Al3+, Cr3+) are precipitated as their hydroxides using NH4OH. The solution must have a controlled, moderate concentration of OH- ions so that only group III hydroxides precipitate, and not the hydroxides of group IV (Zn2+, Ni2+, Mn2+, Co2+) and group V (Mg2+, Ba2+, Ca2+, Sr2+), which need higher OH- concentration. NH4OH is a weak base that dissociates as: NH4OH ⇌ NH4+ + OH-. If solid NH4Cl is added, it provides a large concentration of NH4+ ions. By the common ion effect, the added NH4+ shifts the equilibrium towards the undissociated NH4OH, suppressing the dissociation and thus reducing the OH- concentration. The reduced OH- concentration is enough to precipitate group III hydroxides (whose Ksp is very small) but insufficient to precipitate group IV and V hydroxides (whose Ksp is larger). So the purpose of NH4Cl is NOT to increase OH- concentration (option A is wrong) and NOT to precipitate group IV and V radicals (option B is wrong; rather it prevents them). Introducing Cl- ions (option D) is not the purpose. Hence the correct answer is C. This is a classic application of the common ion effect in qualitative analysis.", "hasImage": false, "image": null}, {"id": 23, "subject": "Chemistry", "chapter": "Equilibrium (Ionic)", "question": "Solubility product of CaC2O4 at a given temperature in pure water is 4 × 10-9 (mol L-1)2. Solubility of CaC2O4 at the same temperature is", "options": {"A": "6.3 × 10-5 mol L-1", "B": "2 × 10-5 mol L-1", "C": "2 × 10-4 mol L-1", "D": "6.3 × 10-4 mol L-1"}, "correctAnswer": "A", "correctAnswerText": "6.3 × 10-5 mol L-1", "explanation": "Calcium oxalate dissociates in water as: CaC2O4(s) ⇌ Ca2+(aq) + C2O42-(aq). If the molar solubility is S mol/L, then at equilibrium [Ca2+] = S and [C2O42-] = S. The solubility product is Ksp = [Ca2+][C2O42-] = S × S = S2. We are given Ksp = 4 × 10-9. Therefore S2 = 4 × 10-9, which gives S = √(4 × 10-9) = 2 × 10-4.5 = 2 × 10-9/2 = 2 × 10-4.5. Now 10-4.5 = 10-5 × 10^0.5 = 10-5 × 3.162. So S = 2 × 3.162 × 10-5 = 6.324 × 10-5 ≈ 6.3 × 10-5 mol/L. Thus the solubility of CaC2O4 is approximately 6.3 × 10-5 mol L-1. The key relationship for a salt of type AB (like CaC2O4, which gives two ions) is Ksp = S2, so S = √Ksp. A very common mistake is to use the formula for a salt giving three ions (Ksp = 4S3) or to misplace the decimal in taking the square root. Here, since CaC2O4 produces exactly two ions, Ksp = S2. Remember: always first write the dissociation equation and relate S to each ion concentration before applying Ksp. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 24, "subject": "Chemistry", "chapter": "Redox Reactions", "question": "In the reaction between moist SO2 and acidified permanganate solution:", "options": {"A": "SO2 is oxidised to SO42- and MnO4- is reduced to Mn2+", "B": "SO2 is reduced to S and MnO4- is oxidised to MnO2", "C": "SO2 is oxidised to SO32- and MnO4- is reduced to MnO2", "D": "SO2 is reduced to H2S and MnO4- is oxidised to MnO42-"}, "correctAnswer": "A", "correctAnswerText": "SO2 is oxidised to SO42- and MnO4- is reduced to Mn2+", "explanation": "Acidified potassium permanganate is a strong oxidising agent. In an acidic medium, the permanganate ion (MnO4-) is reduced to Mn2+ (colourless) and the permanganate's purple colour disappears. Moist sulphur dioxide (SO2) in aqueous medium acts as a reducing agent. SO2 has sulphur in the +4 oxidation state. It is oxidised to sulphate ion (SO42-) in which sulphur has the +6 oxidation state (increase in oxidation number from +4 to +6 is oxidation, i.e., loss of electrons). The balanced ionic equation is: 2MnO4- + 3SO2 + 4H+ → 2Mn2+ + 3SO42- + 2H2O. This is the well-known use of acidified KMnO4 to detect SO2 or to test reducing agents; the purple colour of KMnO4 decolourises because MnO4- (purple) is converted to Mn2+ (pale pink/colourless). Option B says MnO4- is oxidised, which is wrong because in acid medium it is reduced, not oxidised. Option C says SO2 is oxidised to SO32- and MnO4- reduced to MnO2; SO32- would require sulphur at +4, which is the same as in SO2 (no oxidation), and MnO2 is the product in neutral/alkaline medium, not strongly acidic. Option D says SO2 is reduced to H2S, which is incorrect as SO2 is oxidised here. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 25, "subject": "Chemistry", "chapter": "Hydrogen", "question": "Which one of the following properties is generally not applicable to ionic hydrides?", "options": {"A": "Non-volatile", "B": "Non-conducting in solid state", "C": "Crystalline", "D": "Volatile"}, "correctAnswer": "D", "correctAnswerText": "Volatile", "explanation": "Ionic (saline) hydrides are formed when hydrogen combines with highly electropositive elements, i.e., alkali metals (Li, Na, K, Rb, Cs) and the heavier alkaline earth metals (Ca, Sr, Ba). Examples are NaH, CaH2, and LiH. These hydrides are ionic compounds containing the hydride ion (H-). Because they are ionic solids with strong electrostatic forces between the oppositely charged ions, they have high melting and boiling points, making them non-volatile (they do not evaporate easily). Being ionic solids, they are crystalline in nature and form well-defined crystal lattices (e.g., NaCl-type structure). In the solid state, the ions are held rigidly in the lattice and are not free to move, so they are non-conducting as solids (though they conduct electricity when molten or dissolved). The property that is NOT applicable is volatility: ionic hydrides have high boiling points and are non-volatile. Covalent hydrides (like H2S, NH3, HCl) are volatile because they are molecular substances with weak intermolecular forces. A common mistake is to think ionic hydrides are volatile like molecular hydrides; the strong ionic bonding prevents volatility. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 26, "subject": "Chemistry", "chapter": "The s-Block Elements", "question": "Which one of the following nitrate will decompose to give NO2 on heating?", "options": {"A": "NaNO3", "B": "KNO3", "C": "RbNO3", "D": "LiNO3"}, "correctAnswer": "D", "correctAnswerText": "LiNO3", "explanation": "The thermal decomposition of alkali metal nitrates depends on the electropositive nature (size) of the metal. Nitrates of the more electropositive metals (Na, K, Rb, Cs) decompose to give the corresponding nitrite and oxygen: 2NaNO3 → 2NaNO2 + O2. They do not give nitrogen dioxide (NO2) because the metal oxides are formed only at very high temperature and the metals are stable as nitrites. However, lithium nitrate (LiNO3), being a nitrate of a relatively smaller and more electronegative alkali metal, decomposes on heating to give lithium oxide, nitrogen dioxide and oxygen: 4LiNO3 → 2Li2O + 4NO2 + O2. The decomposition of LiNO3 gives a reddish-brown gas, NO2. The reason is that Li+ has a very high charge density (small size, high polarising power) and its oxide/nitrite stability differs; LiNO3 decomposes completely to the oxide, releasing NO2. Similarly, magnesium nitrate and other nitrates of smaller electropositive metals give NO2. So among the alkali metal nitrates, only LiNO3 decomposes to give NO2. A useful generalisation: nitrates of Na, K, Rb, Cs → nitrite + O2; nitrates of Li, and of Mg/other less electropositive metals → oxide + NO2 + O2. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 27, "subject": "Chemistry", "chapter": "The p-Block Elements (Group 14)", "question": "Which of the following halides cannot be hydrolysed?", "options": {"A": "CCl4", "B": "SiCl4", "C": "GeCl4", "D": "SnCl4"}, "correctAnswer": "A", "correctAnswerText": "CCl4", "explanation": "The chlorides of group 14 elements show different behaviour towards hydrolysis. Carbon tetrachloride (CCl4) cannot be hydrolysed by water, whereas SiCl4, GeCl4 and SnCl4 readily undergo hydrolysis. The reason is that carbon has no d-orbitals in its valence shell (carbon's electronic configuration is 2s22p2 and only s and p orbitals are available). Hydrolysis of SiCl4 requires the formation of a five-coordinate intermediate (SiCl4·H2O) in which water donates electrons into empty d-orbitals of silicon; carbon has no d-orbitals, so it cannot expand its coordination number beyond 4 and cannot form the intermediate required for hydrolysis. Additionally, the C-Cl bond is kinetically quite inert to nucleophilic attack by water because carbon is small and the four chlorine atoms shield it, and there is no low-energy orbital to accept the incoming lone pair. In contrast, silicon, germanium and tin have empty d-orbitals, can form pentacoordinate intermediates, and are readily attacked by water: SiCl4 + 2H2O → SiO2 + 4HCl (vigorous hydrolysis). So CCl4 is stable towards water and is used as a solvent and in fire extinguishers precisely because it does not react with water. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 28, "subject": "Chemistry", "chapter": "Organic Chemistry: Some Basic Principles and Techniques", "question": "0.48 g of an organic compound on complete combustion produced 0.22 g of CO2. The percentage of C in the given organic compound is:", "options": {"A": "25", "B": "50", "C": "12.5", "D": "87.5"}, "correctAnswer": "C", "correctAnswerText": "12.5", "explanation": "The percentage of carbon in an organic compound is determined using the Liebig's method (combustion analysis) formula: %C = (12/44) × (mass of CO2 / mass of organic compound) × 100. This formula comes from the fact that 44 g of CO2 contains 12 g of carbon (since one mole of CO2, 44 g, has one mole of C atoms, 12 g). Substituting the given values: mass of CO2 = 0.22 g, mass of organic compound = 0.48 g. %C = (12/44) × (0.22/0.48) × 100. Calculate step by step: 12/44 = 0.2727; 0.22/0.48 = 0.4583; 0.2727 × 0.4583 = 0.125; 0.125 × 100 = 12.5%. So the percentage of carbon is 12.5%. A common mistake is to forget to multiply by the factor (12/44) or to invert the mass of CO2 and the mass of the compound. Always write the formula %C = (12/44) × (WCO2/Wcompound) × 100. Here the answer is 12.5%, which matches option C. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 29, "subject": "Chemistry", "chapter": "Hydrocarbons", "question": "In the given sequence of reactions, identify 'P', 'Q' and 'S' respectively.\nCH2=CH2 →(P) CH2Br-CH2Br →(Q) CH2=CH-Br →(R) CH≡CH →(S) C6H6", "options": {"A": "Br2, Alc. KOH, NaOH, Al2O3", "B": "HBr, Alc. KOH, CaC2, KMnO4", "C": "HBr, Alc. KOH, NaNH2, Red hot iron tube", "D": "Br2, Alc. KOH, NaNH2, Red hot iron tube"}, "correctAnswer": "D", "correctAnswerText": "Br2, Alc. KOH, NaNH2, Red hot iron tube", "explanation": "Let us trace the conversions step by step. Ethene (CH2=CH2) reacts with bromine water or bromine in carbon tetrachloride (P = Br2) to give 1,2-dibromoethane, BrCH2-CH2Br, via an addition reaction. Next, treatment with alcoholic KOH (Q = alcoholic KOH) causes dehydrohalogenation (elimination of two molecules of HBr) to give vinyl bromide (CH2=CH-Br); note the scheme shows CH2=CH-Br. Then, treatment with sodium amide, NaNH2 (R = NaNH2), a strong base, causes elimination of the remaining HBr to give ethyne (CH≡CH). Finally, passing ethyne through a red hot iron tube (S = red hot iron tube) at about 873 K causes cyclisation (trimerisation) of three molecules of ethyne to give benzene (C6H6). This is the industrial Berthelot method for making benzene. Option A suggests NaOH/Al2O3 for the last step, which is not how benzene is made from ethyne. Options B and C suggest HBr as the first reagent, which would give bromoethane (CH3-CH2Br) not 1,2-dibromoethane, breaking the sequence. The correct sequence is: Br2 (addition) → alcoholic KOH (dehydrohalogenation) → NaNH2 (second dehydrohalogenation to alkyne) → red hot iron tube (trimerisation to benzene). Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 30, "subject": "Chemistry", "chapter": "Chemistry in Everyday Life", "question": "The first chlorinated organic insecticide proparod is:", "options": {"A": "Gammaxene", "B": "Chloroform", "C": "COCl2", "D": "DDT"}, "correctAnswer": "D", "correctAnswerText": "DDT", "explanation": "DDT (dichlorodiphenyltrichloroethane) was the first chlorinated organic insecticide, synthesised by Othmar Zeidler in 1874, and its insecticidal properties were discovered by Paul Hermann Muller in 1939 (who won the Nobel Prize in Medicine in 1948 for this discovery). The full name is 2,2-bis(p-chlorophenyl)-1,1,1-trichloroethane. It is a chlorinated hydrocarbon that was widely used during and after World War II to control malaria-carrying mosquitoes and other pests. DDT is persistent in the environment and accumulates in the fatty tissues of animals, causing biomagnification in food chains, which led to its ban in many countries. Gammaxene (lindane, or BHC/gamma-hexachlorocyclohexane) is another chlorinated insecticide, but it was developed later and is not the first. Chloroform (CHCl3) is a chlorinated organic solvent and anaesthetic, not an insecticide. COCl2 is phosgene, a highly toxic gas used in chemical synthesis and as a war gas, not an insecticide. The term 'proparod' in the question is a misspelling of 'prepared'; the intended meaning is the first chlorinated organic insecticide, which is DDT. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 31, "subject": "Chemistry", "chapter": "The Solid State", "question": "Which of the following crystals has the unit cell such that a = b ≠ c and α = β = 90°, γ = 120°?", "options": {"A": "Zinc blende", "B": "Graphite", "C": "Cinnabar", "D": "Potassium dichromate"}, "correctAnswer": "B", "correctAnswerText": "Graphite", "explanation": "The unit cell parameters a = b ≠ c with α = β = 90° and γ = 120° correspond to a hexagonal unit cell (one of the seven crystal systems). In a hexagonal crystal, two of the axes (a and b) are equal in length and are at an angle of 120° to each other, while the third axis (c) is different in length and perpendicular to the plane of a and b. Graphite crystallises in a hexagonal crystal system: its layers of carbon atoms are arranged in a hexagonal sheet structure, with the interlayer spacing (along the c-axis) being different from the in-plane a-axis. So graphite has a hexagonal unit cell satisfying a = b ≠ c and γ = 120°. Zinc blende (ZnS) has a cubic (face-centred cubic) unit cell with a = b = c and α = β = γ = 90°. Cinnabar (HgS) crystallises in the hexagonal system too, but the standard textbook answer for this condition is graphite; cinnabar's structure is hexagonal but the question is testing recognition of hexagonal unit cell parameters, for which graphite is the classic example. Potassium dichromate (K2Cr2O7) crystallises in a triclinic system (a ≠ b ≠ c, α ≠ β ≠ γ ≠ 90°). Hence, among the given options, graphite is the correct crystal with hexagonal unit cell parameters. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 32, "subject": "Chemistry", "chapter": "The Solid State", "question": "MnO exhibits:", "options": {"A": "Ferrimagnetism", "B": "Antiferromagnetism", "C": "Ferromagnetism", "D": "Paramagnetism"}, "correctAnswer": "B", "correctAnswerText": "Antiferromagnetism", "explanation": "Manganese(II) oxide (MnO) is a classic example of an antiferromagnetic material. In antiferromagnetism, the magnetic moments of the ions align in an antiparallel (opposite) arrangement in the crystal lattice, so the net magnetic moment is zero even below the Néel temperature. In MnO, the Mn2+ ions carry unpaired electrons (Mn2+ has 3d5 configuration with five unpaired electrons) and thus have magnetic moments, but in the crystal lattice these moments align in opposite directions, cancelling each other. The magnetic moments on adjacent Mn2+ ions (separated by oxide ions) align antiparallel through superexchange interaction, resulting in zero net magnetisation. Antiferromagnetic substances do not attract a magnet and have zero net magnetic moment. Ferrimagnetism involves unequal antiparallel alignment giving a net moment (e.g., Fe3O4, ferrites). Ferromagnetism involves parallel alignment of all magnetic moments giving a strong net moment (e.g., Fe, Co, Ni). Paramagnetism involves random orientation of moments in the absence of a field (e.g., O2, Al). The distinguishing fact to remember: MnO, MnO2, and MnS are textbook antiferromagnetic solids, while Fe3O4 is ferrimagnetic and iron is ferromagnetic. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 33, "subject": "Chemistry", "chapter": "The Solid State", "question": "The number of atoms in 4.5 g of a face-centred cubic crystal with edge length 300 pm is:\n(Given density = 10 g cm-3 and NA = 6.022 × 1023)", "options": {"A": "6.6 × 1020", "B": "6.6 × 1023", "C": "6.6 × 1019", "D": "6.6 × 1022"}, "correctAnswer": "D", "correctAnswerText": "6.6 × 1022", "explanation": "For a face-centred cubic (FCC) crystal, the number of atoms per unit cell Z = 4, and the density is given by the formula d = Z × M / (NA × a3), where M is molar mass, a is edge length, and NA is Avogadro's number. Given d = 10 g/cm3, a = 300 pm = 300 × 10-12 m = 300 × 10-10 cm = 3 × 10-8 cm. Substituting: 10 = (4 × M) / (6.022 × 1023 × (3 × 10-8)3). Now (3 × 10-8)3 = 27 × 10-24 = 2.7 × 10-23 cm3. So 10 = (4M) / (6.022 × 1023 × 2.7 × 10-23) = (4M) / (16.26). Hence 4M = 10 × 16.26 = 162.6, so M = 40.65 g/mol. This means 40.65 g of the crystal contains NA = 6.022 × 1023 atoms. We have only 4.5 g, so the number of atoms = (4.5/40.65) × 6.022 × 1023 = 0.1107 × 6.022 × 1023 = 6.66 × 1022 ≈ 6.6 × 1022 atoms. This matches option D. A common mistake is using Z = 1 or 2 instead of 4 for FCC, or forgetting to convert pm to cm. Remember: FCC → Z = 4; always convert edge length to cm (1 pm = 10-10 cm). Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 34, "subject": "Chemistry", "chapter": "Solutions", "question": "Vapour pressure of a solution containing 18 g of glucose and 178.2 g of water at 100°C is:\n(Vapour pressure of pure water at 100°C = 760 torr)", "options": {"A": "76.0 torr", "B": "752.0 torr", "C": "7.6 torr", "D": "3207.6 torr"}, "correctAnswer": "B", "correctAnswerText": "752.0 torr", "explanation": "Glucose is a non-volatile solute, so it lowers the vapour pressure of water according to Raoult's law: (P0 - Ps)/P0 = x2, where P0 is the vapour pressure of pure solvent (760 torr), Ps is the vapour pressure of the solution, and x2 is the mole fraction of the solute (glucose). First calculate the moles: moles of water = 178.2/18 = 9.9 mol; moles of glucose = 18/180 = 0.1 mol (molar mass of C6H12O6 = 180 g/mol). Total moles = 9.9 + 0.1 = 10.0 mol. Mole fraction of glucose, x2 = 0.1/10 = 0.01. Now apply Raoult's law: (760 - Ps)/760 = 0.01. So 760 - Ps = 7.6, giving Ps = 760 - 7.6 = 752.4 ≈ 752 torr. The lowering of vapour pressure is 7.6 torr, but the question asks for the vapour pressure of the solution, which is 752 torr. A common mistake is to give the relative lowering (7.6) as the answer, but that is the depression, not the solution's vapour pressure. Remember: (P0 - Ps)/P0 = x_solute, and always subtract the lowering from P0 to get Ps. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 35, "subject": "Chemistry", "chapter": "Solutions", "question": "A mixture of phenol and aniline shows negative deviation from Raoult's law. This is due to the formation of:", "options": {"A": "Polar covalent bond", "B": "Non-polar covalent bond", "C": "Intermolecular Hydrogen bond", "D": "Intramolecular Hydrogen bond"}, "correctAnswer": "C", "correctAnswerText": "Intermolecular Hydrogen bond", "explanation": "Negative deviation from Raoult's law occurs when the A-B interactions in a solution are stronger than the A-A and B-B interactions in the pure components. Phenol (C6H5OH) has a hydroxyl group (-OH) and aniline (C6H5NH2) has an amino group (-NH2). Both molecules can participate in hydrogen bonding. When phenol and aniline are mixed, the oxygen of phenol's -OH can hydrogen-bond with the hydrogen of aniline's -NH2 group, and the nitrogen of aniline can accept a hydrogen bond from phenol's -OH. These new phenol-aniline intermolecular hydrogen bonds are stronger than the pure phenol-phenol and aniline-aniline hydrogen bonds (which are weaker because of the less polar nature of the individual groups compared with the cross interaction). Because the mixed solution is held together more strongly, the escaping tendency of the molecules is reduced, the vapour pressure is lower than predicted by Raoult's law, and the solution shows a negative deviation (with negative enthalpy of mixing, ΔH < 0, and negative volume change). This is an intermolecular hydrogen bond between phenol and aniline, not an intramolecular bond (which would be within a single molecule, e.g., in ortho-nitrophenol or salicylaldehyde). Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 36, "subject": "Chemistry", "chapter": "Solutions", "question": "Which one of the following pairs will show positive deviation from Raoult's Law?", "options": {"A": "Water - HCl", "B": "Benzene-Methanol", "C": "Water - HNO3", "D": "Acetone – Chloroform"}, "correctAnswer": "B", "correctAnswerText": "Benzene-Methanol", "explanation": "Positive deviation from Raoult's law occurs when the A-B interactions in the mixture are weaker than the A-A and B-B interactions in the pure components, leading to higher vapour pressure than predicted. In the benzene-methanol mixture, benzene is a non-polar hydrocarbon and methanol is a polar alcohol that self-associates through strong hydrogen bonding. When they are mixed, the strong methanol-methanol hydrogen bonds are partially broken, and the weak benzene-methanol interactions that form are not strong enough to compensate. As a result, the molecules escape more easily, the vapour pressure of the solution is higher than expected, and the solution shows a positive deviation (ΔH > 0, ΔV > 0). In contrast, water-HCl and water-HNO3 form strong ion-dipole/hydrogen-bonded interactions (these are acid-base type interactions producing strong A-B attraction), and acetone-chloroform forms hydrogen bonds between the acetone oxygen and chloroform hydrogen, all of which show negative deviation. A classic example pair for positive deviation is benzene + ethanol (or benzene + methanol, acetone + benzene, carbon disulphide + acetone). Hence, among the options, benzene-methanol shows positive deviation from Raoult's law. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 37, "subject": "Chemistry", "chapter": "Electrochemistry", "question": "How many Coulombs are required to oxidise 0.1 mole of H2O to oxygen?", "options": {"A": "1.93 × 105 C", "B": "1.93 × 104 C", "C": "3.86 × 104 C", "D": "9.65 × 103 C"}, "correctAnswer": "B", "correctAnswerText": "1.93 × 104 C", "explanation": "The oxidation of water to oxygen is represented by: H2O → H2 + 1/2 O2, or in terms of the half reaction at the anode: 2H2O → O2 + 4H+ + 4e-. Looking at the reaction 2H2O → O2 + 4H+ + 4e-, two moles of water produce one mole of oxygen by releasing four electrons. Therefore, one mole of H2O requires 2 moles of electrons (2 Faradays) for its oxidation. By Faraday's first law, charge Q = n × F, where n is the number of moles of electrons and F = 96500 C/mol. For 1 mole of H2O, Q = 2 × 96500 = 193000 C. For 0.1 mole of H2O, Q = 0.1 × 193000 = 19300 C = 1.93 × 104 C. Note: the question mentions the reaction H2O → H2 + 1/2O2 (i.e., decomposition of water into hydrogen and oxygen). For each mole of water decomposed, 2 electrons are involved in forming hydrogen (2H+ + 2e- → H2), hence 2 Faradays per mole. Thus 0.1 mol requires 1.93 × 104 C. A common mistake is using 1 Faraday per mole (if you ignore that two electrons are needed per water molecule) or mixing up the factor 4. Here each water molecule releases 2 electrons, so n = 2 per mole. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 38, "subject": "Chemistry", "chapter": "Electrochemistry", "question": "A current of 3A is passed through a molten calcium salt for 1 hr 47 min 13 sec. The mass of calcium deposited is:\n(Molar mass of Ca = 40 g mol-1)", "options": {"A": "6.0 g", "B": "2.0 g", "C": "8.0 g", "D": "4.0 g"}, "correctAnswer": "D", "correctAnswerText": "4.0 g", "explanation": "We use Faraday's first law of electrolysis: w = (E × i × t) / 96500, where w is the mass deposited, E is the equivalent weight of calcium, i is the current in amperes, and t is the time in seconds. Calcium is divalent (Ca2+), so its equivalent weight E = Atomic mass / valency = 40/2 = 20 g. The time is 1 hr 47 min 13 s = 3600 + (47 × 60) + 13 = 3600 + 2820 + 13 = 6433 seconds. Current i = 3 A. Now, w = (20 × 3 × 6433) / 96500 = 385980 / 96500 = 3.99 ≈ 4.0 g. Therefore the mass of calcium deposited is approximately 4.0 g. A common mistake is using the atomic mass (40) instead of the equivalent weight (20) for a divalent metal, which would give about 8 g (option C is a trap). Another mistake is making an error in converting the time to seconds (the question uses a deliberately awkward time value). Remember for metal deposition: first find the valency and compute equivalent weight = M/valency, then apply w = E·i·t/96500. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 39, "subject": "Chemistry", "chapter": "Electrochemistry", "question": "The value of 'A' in the equation λm = λm0 - A√C is same for the pair", "options": {"A": "NaCl and CaCl2", "B": "CaCl2 and MgSO4", "C": "NaCl and KBr", "D": "MgCl2 and NaCl"}, "correctAnswer": "C", "correctAnswerText": "NaCl and KBr", "explanation": "The equation λm = λm0 - A√C is Debye-Hückel-Onsager equation for strong electrolytes, where λm is the molar conductivity at concentration C, λm0 is the molar conductivity at infinite dilution, and A is a constant that depends on the nature of the electrolyte, specifically on the charges (valencies) of the ions and on the solvent properties (viscosity, dielectric constant, temperature). The constant A is given by the theoretical expression based on the ionic charges. For a strong electrolyte of the type M+X-, the value of A depends on the charges z+ and z- of the cation and anion. Electrolytes having ions of the same valency (like NaCl and KBr, both 1:1 type) have the same value of A. NaCl (Na+ + Cl-) and KBr (K+ + Br-) are both 1:1 electrolytes with singly charged ions, so A is the same. CaCl2 is a 2:1 electrolyte (Ca2+ + 2Cl-), MgSO4 is a 2:2 electrolyte (Mg2+ + SO42-), and MgCl2 is 2:1, so they have different charges and hence different values of A. Therefore the pair with the same A is NaCl and KBr. The concept to remember: the Onsager constant A depends on the ionic charges (valency type) of the electrolyte, not on the specific identity of the ions, as long as the charge type is the same. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 40, "subject": "Chemistry", "chapter": "Chemical Kinetics", "question": "For the reaction, aA ⇌ bB, Ea = 50 kJ mol-1 and ΔH = -20 kJ mol-1. When a catalyst is added, Ea decreases by 10 kJ mol-1. What is the Ea for the backward reaction in the presence of catalyst?", "options": {"A": "60 kJ mol-1", "B": "140 kJ mol-1", "C": "170 kJ mol-1", "D": "120 kJ mol-1"}, "correctAnswer": "A", "correctAnswerText": "60 kJ mol-1", "explanation": "For a reaction, the activation energies of forward and backward reactions are related to the enthalpy change by: ΔH = Ea(forward) - Ea(backward). Given Ea(forward) = 50 kJ/mol and ΔH = -20 kJ/mol (exothermic). Without a catalyst: -20 = 50 - Ea(backward), so Ea(backward) = 50 + 20 = 70 kJ/mol. When a catalyst is added, it lowers the activation energy of BOTH the forward and backward reactions by the same amount, because the catalyst provides an alternative pathway with a lower energy barrier for the reaction in either direction. The forward activation energy decreases by 10 kJ/mol, so the new Ea(forward) = 50 - 10 = 40 kJ/mol. Since ΔH is unchanged by a catalyst (the catalyst does not change the thermodynamic position of equilibrium or the enthalpy change), the new backward activation energy is: Ea(backward) = Ea(forward) - ΔH = 40 - (-20) = 60 kJ/mol. Alternatively, the backward Ea also decreased by 10 from 70 to 60 kJ/mol. Hence the Ea for the backward reaction with catalyst is 60 kJ/mol. A common mistake is to forget that the catalyst lowers both forward and backward activation energies equally, or to apply the decrease to only one direction. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 41, "subject": "Chemistry", "chapter": "Chemical Kinetics", "question": "For the reaction PCl5 → PCl3 + Cl2, rate and rate constant are 1.02 × 10-4 mol L-1 s-1 and 3.4 × 10-5 s-1 respectively at a given instant. The molar concentration of PCl5 at that instant is:", "options": {"A": "8.0 mol L-1", "B": "3.0 mol L-1", "C": "0.2 mol L-1", "D": "2.0 mol L-1"}, "correctAnswer": "B", "correctAnswerText": "3.0 mol L-1", "explanation": "The decomposition of phosphorus pentachloride, PCl5 → PCl3 + Cl2, is a first-order reaction (the rate depends on the concentration of PCl5 to the first power). The unit of the rate constant is s-1, which confirms first-order kinetics. For a first-order reaction, the rate law is: Rate = k[PCl5]. We are given Rate = 1.02 × 10-4 mol L-1 s-1 and k = 3.4 × 10-5 s-1. Rearranging, [PCl5] = Rate / k = (1.02 × 10-4) / (3.4 × 10-5). Dividing: 1.02/3.4 = 0.3, and 10-4/10-5 = 10. So [PCl5] = 0.3 × 10 = 3.0 mol/L. Therefore the concentration of PCl5 at that instant is 3.0 mol L-1. A common mistake is to use the wrong rate-law order or to make a decimal error when dividing the powers of ten. Remember: when the units of k are s-1, the reaction is first order and Rate = k[A]; to find [A], simply divide rate by k. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 42, "subject": "Chemistry", "chapter": "Chemical Kinetics", "question": "Which one of the following does not represent Arrhenius equation?", "options": {"A": "log k = log A - Ea/2.303RT", "B": "k = Ae-Ea/RT", "C": "ln k = ln A - Ea/RT", "D": "k = AeEa/RT"}, "correctAnswer": "D", "correctAnswerText": "k = AeEa/RT", "explanation": "The Arrhenius equation relates the rate constant k to the temperature T and the activation energy Ea of a reaction. The standard exponential form is: k = Ae-Ea/RT, where A is the pre-exponential (frequency) factor, R is the gas constant, and e is the base of natural logarithms. The negative sign in the exponent indicates that as the activation energy increases, the rate constant decreases (higher barrier means slower reaction), and as temperature increases, k increases. Taking the natural logarithm on both sides gives the linear form: ln k = ln A - Ea/RT (option C). Converting to base-10 logarithms: log k = log A - Ea/(2.303RT) (option A). All three - A, B and C - are valid forms of the Arrhenius equation. Option D shows k = AeEa/RT, which has a POSITIVE exponent Ea/RT. This is wrong because it would imply that a higher activation energy increases the rate constant, which is physically incorrect. The correct form always has the negative exponent (e-Ea/RT). So the equation that does not represent the Arrhenius equation is option D. Remember the mnemonic: 'Arrhenius has a negative exponent' - k = Ae-Ea/RT. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 43, "subject": "Chemistry", "chapter": "Surface Chemistry", "question": "Identify the incorrect statement:", "options": {"A": "Values of colligative properties of colloidal solution are of small order compared to values of true solution", "B": "Tyndall effect is observed only when diameter of the dispersed particles is not much smaller than wavelength of incident light", "C": "Colour of colloidal solution depends on the wavelength of light scattered by the dispersed particles", "D": "Brownian movement is due to balanced bombardment of molecules of dispersion medium on colloidal particles"}, "correctAnswer": "D", "correctAnswerText": "Brownian movement is due to balanced bombardment of molecules of dispersion medium on colloidal particles", "explanation": "Brownian movement is the continuous, random (zig-zag) motion of colloidal particles in the dispersion medium. This motion arises because the colloidal particles are continuously and RANDOMLY (i.e., UNBALANCED) bombarded by the molecules of the dispersion medium. The forces from the solvent molecules hitting the colloidal particle from different directions are not balanced at any given instant - if they were perfectly balanced, the net force would be zero and the particle would not move. It is the unequal, fluctuating bombardment that causes the particle to be pushed this way and that, producing Brownian motion. Therefore the statement that Brownian movement is due to 'balanced bombardment' is INCORRECT; it is due to unbalanced bombardment. The other statements are correct: colligative properties of colloidal solutions are indeed of a small order compared with true solutions because the effective number of solute particles is small (large colloidal particles behave as few particles); the Tyndall effect is observed when the size of dispersed particles is comparable to (not much smaller than) the wavelength of light, allowing scattering; and the colour of a colloidal solution depends on the wavelength of light scattered by the dispersed particles. Hence the incorrect statement is D.", "hasImage": false, "image": null}, {"id": 44, "subject": "Chemistry", "chapter": "Surface Chemistry", "question": "For the coagulation of positively charged hydrated ferric-oxide sol, the flocculating power of the ions is in the order:", "options": {"A": "PO43- > SO42- > Cl- > [Fe(CN)6]4-", "B": "Cl- > SO42- > PO43- > [Fe(CN)6]4-", "C": "SO42- = Cl- = PO43- = [Fe(CN)6]4-", "D": "[Fe(CN)6]4- > PO43- > SO42- > Cl-"}, "correctAnswer": "D", "correctAnswerText": "[Fe(CN)6]4- > PO43- > SO42- > Cl-", "explanation": "The hydrated ferric oxide sol (Fe(OH)3 sol) is a positively charged sol. Coagulation (flocculation) of a positively charged sol is caused by negatively charged ions (anions). The flocculating power of an ion depends on its charge, as given by the Hardy-Schulze rule: the greater the charge (valency) of the coagulating ion, the greater is its power to coagulate the colloid. Higher the charge, stronger the attraction to the oppositely charged colloidal particles, so a lower concentration is needed to coagulate. Here the anions and their charges are: Cl- (charge -1), SO42- (charge -2), PO43- (charge -3), and [Fe(CN)6]4- (charge -4). Since flocculating power is directly proportional to the charge on the ion, the order is: [Fe(CN)6]4- (charge 4) > PO43- (charge 3) > SO42- (charge 2) > Cl- (charge 1). This matches option D. This is a direct application of the Hardy-Schulze rule, which states that coagulating power ∝ valency of the ion. A common mistake is to use the wrong list (e.g., using cations for a positively charged sol, or reversing the order). Remember: positively charged sol → coagulated by anions; the anion with the highest negative charge has the highest flocculating power. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 45, "subject": "Chemistry", "chapter": "Surface Chemistry", "question": "Gold sol is not a:", "options": {"A": "Macromolecular colloid", "B": "Lyophobic colloid", "C": "Multimolecular colloid", "D": "Negatively charged colloid"}, "correctAnswer": "A", "correctAnswerText": "Macromolecular colloid", "explanation": "Gold sol is a colloidal solution of gold particles dispersed in water, prepared by Bredig's arc method or by chemical reduction of gold salts (e.g., HAuCl4 reduced with formaldehyde). Gold particles have a natural tendency to interact weakly with water, so gold sol is a lyophobic (solvent-hating) colloid; the dispersed phase has little affinity for the dispersion medium. Gold sol is also a multimolecular colloid, because when a large number of gold atoms (molecules) aggregate to form particles of colloidal size (roughly 1-100 nm), each particle is simply an aggregate of many gold atoms held together by van der Waals forces - there is no stabilising macromolecule. Gold particles in a sol acquire a negative charge (by preferential adsorption of AuCl4- or OH- ions), so gold sol is a negatively charged colloid. A macromolecular (association/lyophilic) colloid, on the other hand, is one in which the dispersed phase is a single large molecule of colloidal size, such as starch, proteins, gelatin, or rubber - these are naturally occurring macromolecules that form lyophilic sols directly on dissolving. Gold sol is NOT a macromolecular colloid because the gold particle is made of many atoms, not one giant molecule. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 46, "subject": "Chemistry", "chapter": "Metallurgy (General Principles)", "question": "The incorrect statement about Hall-Heroult process is:", "options": {"A": "Carbon anode is oxidised to CO and CO2", "B": "Na3AlF6 helps to decrease the melting point of the electrolyte", "C": "CaF2 helps to increase the conductivity of the electrolyte", "D": "Oxidation state of oxygen changes in the overall cell reaction"}, "correctAnswer": "D", "correctAnswerText": "Oxidation state of oxygen changes in the overall cell reaction", "explanation": "The Hall-Heroult process is used for the electrolytic reduction of alumina (Al2O3) to extract aluminium. Alumina is dissolved in molten cryolite (Na3AlF6) with some CaF2 (fluorspar). The cathode reaction is: Al3+ + 3e- → Al (aluminium is deposited at the cathode). The anode reaction is: 2O2- → O2 + 4e-, and the liberated oxygen reacts with the carbon anode: C + O2 → CO2 and 2C + O2 → 2CO. So the carbon anode is oxidised (consumed) to CO and CO2 (statement A is true). Cryolite (Na3AlF6) lowers the melting point of the electrolyte from about 2050°C (melting point of pure alumina) to about 950-1000°C and also improves conductivity (statement B is true). Calcium fluoride (CaF2) is added to increase the conductivity of the electrolyte and to lower the melting point further (statement C is true). Statement D claims that the oxidation state of oxygen changes in the overall cell reaction. In the overall reaction 2Al2O3 + 3C → 4Al + 3CO2, oxygen remains as O2- (oxidation state -2) in Al2O3 and in CO2; the oxygen's oxidation state does NOT change - it is the carbon that is oxidised (0 to +4) and aluminium that is reduced (+3 to 0). Hence statement D is incorrect. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 47, "subject": "Chemistry", "chapter": "Metallurgy (General Principles)", "question": "Select the correct statement:", "options": {"A": "Roasting involves heating the ore in the absence of air", "B": "Calcination involves heating the ore above its melting point", "C": "Smelting involves heating the ore with suitable reducing agent and flux below its melting point", "D": "Calcination of calcium carbonate is endothermic"}, "correctAnswer": "D", "correctAnswerText": "Calcination of calcium carbonate is endothermic", "explanation": "Calcination is the process of heating an ore (usually a carbonate or hydroxide ore) in a limited supply of air (or absence of air) to below its melting point, to drive off moisture, volatile impurities and to convert the ore into its oxide. For calcium carbonate, calcination is: CaCO3(s) →(heat) CaO(s) + CO2(g). This decomposition of calcium carbonate to quicklime and carbon dioxide is an ENDOTHERMIC reaction - it requires a continuous supply of heat energy because energy is absorbed to break the strong ionic bonds in CaCO3. Hence statement D is correct. Roasting involves heating the ore in a regular (excess) supply of air (often to convert sulphides to oxides and to remove volatile impurities), so statement A (absence of air) is wrong. Calcination is carried out BELOW the melting point of the ore, not above it (statement B is wrong). Smelting is carried out at temperatures ABOVE the melting point of the ore so that the metal and slag are in a molten state and can separate (statement C is wrong - it says 'below its melting point'). So only statement D is correct. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 48, "subject": "Chemistry", "chapter": "The p-Block Elements (Group 15)", "question": "NO2 gas is:", "options": {"A": "Colourless, neutral", "B": "Colourless, acidic", "C": "Brown, acidic", "D": "Brown, neutral"}, "correctAnswer": "C", "correctAnswerText": "Brown, acidic", "explanation": "Nitrogen dioxide (NO2) is a reddish-brown (brown) gas with a pungent, irritating odour. It is a mixed anhydride and a strongly oxidising gas. When dissolved in water, NO2 undergoes disproportionation to give nitric acid and nitrous acid: 2NO2 + H2O → HNO3 + HNO2. Since it produces acids on reaction with water, NO2 is an acidic oxide. The brown colour of NO2 is due to its unpaired electron (NO2 is a paramagnetic odd-electron molecule); the absorption of visible light by this species gives it the characteristic reddish-brown colour. So NO2 is both brown in colour and acidic in nature. N2O (nitrous oxide) is colourless and neutral; NO (nitric oxide) is colourless and neutral in character (though it is oxidised easily). NO2 is one of the gases responsible for photochemical smog and acid rain. The key point to remember: NO2 is brown and acidic; it is produced by heating lead nitrate (2Pb(NO3)2 → 2PbO + 4NO2 + O2). A common mistake is to think it is colourless like NO. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 49, "subject": "Chemistry", "chapter": "Environmental Chemistry", "question": "Identify the incorrect statement from the following:", "options": {"A": "Oxides of nitrogen in the atmosphere can cause depletion of the ozone layer", "B": "Ozone absorbs the intense ultraviolet radiation of Sun", "C": "Depletion of ozone layer is because of its chemical reactions with chlorofluoroalkanes", "D": "Ozone absorbs infrared radiation"}, "correctAnswer": "D", "correctAnswerText": "Ozone absorbs infrared radiation", "explanation": "Ozone (O3) in the stratosphere plays a vital protective role by absorbing the intense ultraviolet (UV) radiation from the Sun, particularly UV-B radiation, thereby preventing harmful UV rays from reaching the Earth's surface. So statement B is correct. Oxides of nitrogen (NO and NO2) catalytically destroy ozone: NO + O3 → NO2 + O2 and NO2 + O → NO + O2, so oxides of nitrogen do cause ozone depletion (statement A is correct). Chlorofluorocarbons (CFCs, like CFC-12) release chlorine free radicals in the stratosphere which catalytically decompose ozone: Cl + O3 → ClO + O2, etc. - hence CFCs deplete the ozone layer (statement C is correct). Statement D says 'Ozone absorbs infrared radiation'. In reality, ozone mainly absorbs ULTRAVIOLET radiation (its characteristic absorption is in the UV region around 200-320 nm). The greenhouse gas that strongly absorbs infrared (long-wavelength) radiation is carbon dioxide (CO2), methane, etc. Ozone's primary atmospheric function is UV absorption, not infrared absorption. Hence statement D is the incorrect one. A common misconception is confusing the ozone layer's role (UV shield) with the greenhouse effect (IR absorption by CO2). Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 50, "subject": "Chemistry", "chapter": "The p-Block Elements (Group 17)", "question": "The correct decreasing order of boiling point of hydrogen halides is:", "options": {"A": "HF > HCl > HBr > HI", "B": "HI > HBr > HCl > HF", "C": "HF > HI > HBr > HCl", "D": "HI > HF > HBr > HCl"}, "correctAnswer": "C", "correctAnswerText": "HF > HI > HBr > HCl", "explanation": "The boiling points of the hydrogen halides are influenced by two factors: (i) the strength of van der Waals (dispersion) forces, which increase with the size (and molar mass) of the molecule, and (ii) hydrogen bonding. For HCl, HBr and HI, there is no hydrogen bonding, so the boiling points increase with molar mass: HCl (36.5) < HBr (81) < HI (128) - the heavier molecules have stronger dispersion forces. However, HF is exceptional: it undergoes strong intermolecular hydrogen bonding (F-H···F-H), which binds the HF molecules together in associated clusters even in the vapour state. As a result, HF has the highest boiling point of all the hydrogen halides (about 20°C). Therefore the correct decreasing order is: HF > HI > HBr > HCl. The anomaly is that HCl has the lowest boiling point (about -85°C) among the four, even though HBr and HI are heavier; this is because HF's hydrogen bonding is strong while HCl/HBr/HI follow the normal trend. A common mistake is to rank simply by molar mass (which would give HI > HBr > HCl > HF) and to forget the strong hydrogen bonding of HF. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 51, "subject": "Chemistry", "chapter": "The p-Block Elements (Group 18)", "question": "The synthetically produced radioactive noble gas by the collision of 249Cf with 48Ca is:", "options": {"A": "Radon", "B": "Radium", "C": "Oganesson", "D": "Xenon"}, "correctAnswer": "C", "correctAnswerText": "Oganesson", "explanation": "Oganesson (Og) is a synthetic, radioactive superheavy element with atomic number 118. It belongs to group 18 (noble gases) of the periodic table and is the heaviest element ever discovered. It was first synthesised in 2002-2006 by bombarding californium-249 (249Cf, Z = 98) with calcium-48 (48Ca, Z = 20) nuclei in a particle accelerator: 249Cf + 48Ca → 294Og + 3n. The resulting isotope 294Og (with three neutrons emitted) has Z = 98 + 20 = 118, confirming oganesson. Because of its extremely short half-life, oganesson exists only in tiny quantities for fractions of a millisecond, and its properties as a noble gas are mostly predicted theoretically. Radon (Z = 86) is a naturally occurring radioactive noble gas formed from the radioactive decay of radium in the uranium decay series; it is not made by this fusion reaction. Radium (Z = 88) is a radioactive alkaline earth metal, not a noble gas. Xenon (Z = 54) is a stable noble gas found in trace amounts in the atmosphere. The key point: the collision of 249Cf with 48Ca produced oganesson (element 118), the last element of group 18. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 52, "subject": "Chemistry", "chapter": "The d- and f-Block Elements", "question": "The transition element (≈5%) present with lanthanoid metal in Misch metal is:", "options": {"A": "Mg", "B": "Fe", "C": "Zn", "D": "Co"}, "correctAnswer": "B", "correctAnswerText": "Fe", "explanation": "Misch metal is an alloy consisting of about 95% lanthanoid (lanthanide) metals and about 5% iron (Fe), along with traces of other metals and carbon. It is an important alloy used in the manufacture of 'flints' for cigarette lighters and in 'Misch metal' iron rods used as spark producers. The name 'Misch metal' comes from the German word 'mischen' meaning 'to mix'. The typical composition is approximately 50% cerium, 25% lanthanum, 15% neodymium, small amounts of other lanthanoids (praseodymium, samarium, etc.), and about 5% iron. When the alloy is struck, the lanthanoid metals react vigorously with oxygen in the air and produce sparks; the iron provides hardness and improves the mechanical properties. So the transition element present to about 5% in Misch metal is iron (Fe). Magnesium, zinc and cobalt are not the 5% component of standard Misch metal (though some special alloys may contain magnesium, the textbook answer for Misch metal is iron). The question specifically states 'transition element (≈5%)', which is iron. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 53, "subject": "Chemistry", "chapter": "The d- and f-Block Elements", "question": "Match the following:\nI. Zn2+ - i. d8 configuration\nII. Cu2+ - ii. Colourless\nIII. Ni2+ - iii. μ = 1.73 BM", "options": {"A": "I-i, II-ii, III-iii", "B": "I-ii, II-iii, III-i", "C": "I-ii, II-i, III-iii", "D": "I-i, II-iii, III-ii"}, "correctAnswer": "B", "correctAnswerText": "I-ii, II-iii, III-i", "explanation": "Let us analyse each ion. Zn2+ is formed by losing the two 4s electrons from Zn (electronic configuration [Ar]3d10 4s2), giving [Ar]3d10. It has NO unpaired electrons (all 3d orbitals are fully filled), so it has no d-d transitions and is COLOURLESS. Hence Zn2+ matches with ii (colourless). Cu2+ has electronic configuration [Ar]3d9 (one unpaired electron). The magnetic moment is given by μ = √(n(n+2)) BM, where n is the number of unpaired electrons. For n = 1, μ = √(1 × 3) = √3 = 1.73 BM. So Cu2+ matches with iii (μ = 1.73 BM). Ni2+ has electronic configuration [Ar]3d8, i.e., d8 configuration. So Ni2+ matches with i (d8 configuration). Therefore the correct matching is: I-ii, II-iii, III-i, which is option B. A common mistake is to confuse the configurations: Cu+ is 3d10 (colourless, diamagnetic), while Cu2+ is 3d9 (paramagnetic, μ = 1.73 BM). Remember: Zn2+ (3d10) is colourless; Cu2+ (3d9) has one unpaired electron with μ = 1.73 BM; Ni2+ (3d8) has two unpaired electrons. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 54, "subject": "Chemistry", "chapter": "The d- and f-Block Elements", "question": "Which of the following statements related to lanthanoids is incorrect?", "options": {"A": "Lanthanoids are silvery white soft metals", "B": "Samarium shows +2 oxidation state", "C": "Ce+4 solutions are widely used as oxidising agents in titrimetric analysis", "D": "Colour of lanthanoid ion in solution is due to d-d transition"}, "correctAnswer": "D", "correctAnswerText": "Colour of lanthanoid ion in solution is due to d-d transition", "explanation": "Lanthanoids (the elements from cerium to lutetium, Z = 58-71) are silvery-white, soft, malleable metals with a metallic lustre; they tarnish rapidly in air (statement A is correct). Samarium (Sm) shows the +2 oxidation state (along with europium and ytterbium) because of the stability of the half-filled 4f7 configuration (Sm2+ has 4f6, Eu2+ has 4f7) - so statement B is correct. Cerium(IV) salts (Ce4+) are strong oxidising agents and are widely used in titrimetric (volumetric) analysis as a primary standard oxidant in acid solution (statement C is correct). Statement D says that the colour of lanthanoid ions in solution is due to d-d transitions. This is INCORRECT. Lanthanoid ions exhibit colours due to f-f transitions (transitions between the 4f orbitals), not d-d transitions. The 4f orbitals of lanthanoids are partially filled and transitions among them (f-f transitions) give rise to the characteristic colours (e.g., Pr3+ green, Nd3+ violet, Sm3+ yellow). d-d transitions are responsible for colours of transition (d-block) metal ions, not lanthanoid ions. Hence the incorrect statement is D. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 55, "subject": "Chemistry", "chapter": "The p-Block Elements (Groups 15 and 16)", "question": "A metalloid is:", "options": {"A": "Bi", "B": "Sb", "C": "P", "D": "Se"}, "correctAnswer": "B", "correctAnswerText": "Sb and Se (B and D)", "explanation": "Metalloids are elements that have properties intermediate between metals and non-metals. They exhibit metallic characteristics like lustre and some electrical conductivity, but also non-metallic characteristics like forming covalent bonds and being brittle. The commonly recognised metalloids are boron (B), silicon (Si), germanium (Ge), arsenic (As), antimony (Sb), tellurium (Te), and sometimes polonium (Po) and astatine (At). According to the NCERT textbook for class 11 (chapters on p-block elements, groups 15 and 16), antimony (Sb) and selenium (Se) are classified as metalloids in those groups. Sb is a metalloid in group 15 (along with As), and Se is a metalloid in group 16 (between S and Te). Bismuth (Bi) is classified as a metal, not a metalloid, even though it is in the same group as As and Sb. Phosphorus (P) is a non-metal. Hence the metalloids among the options are Sb and Se, so the correct answer is both B and D (options B and D). The question allows two correct answers (B and D). Remember the metalloid staircase: B, Si, Ge, As, Sb, Te (and P is a non-metal, Bi is a metal). Hence the correct answers are B and D.", "hasImage": false, "image": null}, {"id": 56, "subject": "Chemistry", "chapter": "Chemical Bonding and Molecular Structure", "question": "A pair of isoelectronic species having bond order of one is:", "options": {"A": "N2, CO", "B": "N2, NO+", "C": "O2 2-, F2", "D": "CO, NO+"}, "correctAnswer": "C", "correctAnswerText": "O2 2-, F2", "explanation": "Isoelectronic species are atoms, molecules or ions that have the same number of electrons. Let us count the electrons in each pair. N2 has 14 electrons; CO has 14 electrons (C has 6, O has 8); they are isoelectronic. The bond order of N2 is 3 (triple bond) and of CO is 3, so option A is isoelectronic with bond order 3, not 1. N2 (14 e-) and NO+ (NO has 15 e-, NO+ has 14 e-) are isoelectronic with bond order 3 each (NO+ has bond order 3), not 1. CO (14 e-) and NO+ (14 e-) are isoelectronic, both with bond order 3. O2 2- (peroxide ion): oxygen has 8 electrons, so O2 has 16, and O2 2- has 16 + 2 = 18 electrons. F2: fluorine has 9 electrons, so F2 has 18 electrons. Thus O2 2- and F2 both have 18 electrons and are isoelectronic. Using molecular orbital theory, the bond order of F2 is (10 - 8)/2 = 1, and the bond order of O2 2- is also (10 - 8)/2 = 1. Both have a bond order of one (single bond). Hence option C is the pair of isoelectronic species with bond order one. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 57, "subject": "Chemistry", "chapter": "States of Matter (Gases and Liquids)", "question": "Identify the wrong relation for real gases:", "options": {"A": "Z = Videal / Vreal", "B": "pideal = preal + an2/V2", "C": "Vreal = Videal - nb", "D": "(p + a/V2)(V - b) = RT"}, "correctAnswer": "A", "correctAnswerText": "Z = Videal / Vreal", "explanation": "The compressibility factor Z is a measure of how much a real gas deviates from ideal behaviour. It is defined as Z = pV/nRT, and it can also be expressed as the ratio of the actual (real) molar volume to the ideal molar volume: Z = Vreal / Videal. For an ideal gas, Z = 1. Option A states Z = Videal / Vreal, which is the INVERSE of the correct relation, so it is wrong. In the van der Waals equation for one mole of a real gas: (p + a/V2)(V - b) = RT, where 'a' corrects for the attractive forces between molecules (the pressure correction term an2/V2 for n moles) and 'b' corrects for the finite size of the molecules (the volume correction). From this equation, the ideal pressure is related to real pressure by pideal = preal + an2/V2 (option B is correct), and the real volume is related to the ideal volume by Vreal = Videal - nb (option C is correct). Option D is the standard van der Waals equation for one mole, which is correct. Hence the wrong relation is option A: the correct definition is Z = Vreal/Videal, not its inverse. A common mistake is to invert the ratio. Remember: Z = V(real)/V(ideal); Z < 1 means gas is more compressible (attractions dominate), Z > 1 means repulsions dominate. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 58, "subject": "Chemistry", "chapter": "Thermodynamics", "question": "From the given energy diagram, the ΔrH for the reaction C → A is:", "options": {"A": "+35 J", "B": "-15 J", "C": "-35 J", "D": "+15 J"}, "correctAnswer": "C", "correctAnswerText": "-35 J", "explanation": "The reaction diagram shows the conversion A → 2B → C with enthalpy changes ΔH1 and ΔH2. From the diagram, A → 2B has ΔH1 and 2B → C has ΔH2, and the total A → C enthalpy change is ΔH = ΔH1 + ΔH2 = 35 J (the value given for the forward reaction A to C). The question asks for the enthalpy change of the REVERSE reaction, C → A. Enthalpy is a state function, and when a reaction is reversed, the sign of the enthalpy change is reversed: ΔH(C → A) = -ΔH(A → C) = -35 J. So the enthalpy change for C → A is -35 J, meaning the reverse reaction is exothermic (releases 35 J). The physical meaning: if the forward reaction A → C absorbs 35 J (endothermic, positive), then going back from C to A releases 35 J (exothermic, negative). Option C is -35 J. Option A (+35 J) is the forward reaction value, options B and D (±15 J) do not match the diagram values. Remember Hess's law: the total enthalpy change is independent of the path, and reversing a reaction reverses the sign of ΔH. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 59, "subject": "Chemistry", "chapter": "Some Basic Concepts of Chemistry", "question": "For which one of the following mixtures is composition uniform throughout?", "options": {"A": "Sand and water", "B": "Grains and pulses with stone", "C": "Mixture of oil and water", "D": "Dilute aqueous solution of sugar"}, "correctAnswer": "D", "correctAnswerText": "Dilute aqueous solution of sugar", "explanation": "A mixture is said to have uniform composition throughout when it is a homogeneous mixture, meaning its components are mixed at the molecular level and every sample taken from any part has the same composition and properties. A dilute aqueous solution of sugar is a homogeneous mixture: the sugar molecules are uniformly dissolved in water at the molecular level, and the concentration is the same everywhere in the solution. Sand and water form a heterogeneous mixture because sand particles do not dissolve and settle at the bottom; the composition is different in different parts (sand settles below, water above). Grains and pulses with stones form a heterogeneous solid mixture where the components are visibly separate and can be picked out. Oil and water form a heterogeneous mixture because oil and water are immiscible and form two separate layers; the composition is not uniform (oil layer on top, water layer below). Hence the only mixture with uniform composition throughout is the dilute aqueous solution of sugar (a true solution). The concept to remember: true solutions are homogeneous (uniform composition), whereas suspensions and emulsions are heterogeneous. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 60, "subject": "Chemistry", "chapter": "Structure of Atom", "question": "The energy associated with first orbit of He+ is:", "options": {"A": "0 J", "B": "-8.72 × 10-18 J", "C": "-4.58 × 10-18 J", "D": "-0.545 × 10-18 J"}, "correctAnswer": "B", "correctAnswerText": "-8.72 × 10-18 J", "explanation": "The energy of an electron in the nth orbit of a hydrogen-like species (an atom/ion with one electron and nuclear charge Z) is given by the Bohr model formula: En = -2.18 × 10-18 × (Z2/n2) J. For the helium ion He+, Z = 2 (nuclear charge of helium). The first orbit corresponds to n = 1. Substituting: E1 = -2.18 × 10-18 × (22/12) = -2.18 × 10-18 × 4 = -8.72 × 10-18 J. Therefore the energy of the first orbit (ground state) of He+ is -8.72 × 10-18 J. The negative sign indicates that the electron is bound to the nucleus (energy is released when the electron is brought to that orbit from infinity). For the hydrogen atom (Z = 1), the first orbit energy is -2.18 × 10-18 J. For He+ (Z = 2), it is four times more negative because energy scales as Z2. A common mistake is to forget the Z2 factor (using Z = 1) which would give -2.18 × 10-18 J, or to use Z2 = 4 incorrectly. Remember the formula En = -2.18 × 10-18 Z2/n2 J for one-electron species. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 1, "subject": "Chemistry", "chapter": "Solutions", "question": "Which of the following methods of expressing concentration are unitless?", "options": {"A": "Molality and Molarity", "B": "Mole fraction and Mass percent (W/W)", "C": "Molality and Mole fraction", "D": "Mass percent (W/W) and Molality"}, "correctAnswer": "B", "correctAnswerText": "Mole fraction and Mass percent (W/W)", "explanation": "Mole fraction is defined as the ratio of the number of moles of one component to the total number of moles of all components (x = n1/(n1+n2)). Since both the numerator and denominator are in moles, the units cancel out, making mole fraction a dimensionless (unitless) quantity. Mass percent (w/w) is defined as (mass of solute / mass of solution) × 100; here also the units of mass cancel, so mass percent is unitless. On the other hand, molality is the number of moles of solute dissolved per kilogram of solvent, so it has units of mol/kg. Molarity is the number of moles of solute per litre of solution, with units of mol/L. Therefore only mole fraction and mass percent are unitless among the given concentration terms. This is why mole fraction is preferred in Raoult's law and thermodynamics calculations - its value does not depend on temperature, unlike molarity (which changes with temperature because volume changes). Molality also does not depend on temperature (mass is constant), but it still carries units. A common mistake students make is to think molality is unitless because it is temperature-independent; remember that 'temperature independence' and 'unitless' are different concepts. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 2, "subject": "Chemistry", "chapter": "Some Basic Concepts of Chemistry", "question": "Select the INCORRECT statement/s from the following:\n(a) 22 books have infinite significant figures.\n(b) In the answer of calculation 2.5 × 1.25 has four significant figures.\n(c) Zeros preceding to first non-zero digit are significant.\n(d) In the answer of calculation 12.11 + 18.0 + 1.012 has three significant figures.", "options": {"A": "(a) and (b) only", "B": "(b), (c) and (d)", "C": "(b) and (c) only", "D": "(b) and (d) only"}, "correctAnswer": "C", "correctAnswerText": "(b) and (c) only", "explanation": "Let us examine each statement. Statement (a): '22 books have infinite significant figures.' This is TRUE because 22 is an exact count (a book is counted as a discrete object), and exact numbers obtained by counting have infinite significant figures. Statement (b): '2.5 × 1.25 has four significant figures.' This is FALSE. In multiplication, the result should have the same number of significant figures as the factor with the FEWEST significant figures. 2.5 has two significant figures and 1.25 has three, so the product must be rounded to two significant figures. 2.5 × 1.25 = 3.125, which rounded to two significant figures is 3.1 (two significant figures, not four). Statement (c): 'Zeros preceding the first non-zero digit are significant.' This is FALSE. Leading zeros (zeros to the left of the first non-zero digit) are NOT significant; they merely indicate the position of the decimal point. For example, in 0.0025, only '25' are significant (two significant figures); the zeros are not. Statement (d): '12.11 + 18.0 + 1.012 has three significant figures.' This is TRUE. In addition, the result should have the same number of DECIMAL places as the term with the fewest decimal places. 12.11 (2 dp), 18.0 (1 dp), 1.012 (3 dp); the limiting term is 18.0 with 1 decimal place. Sum = 31.122, which rounds to 31.1 (three significant figures). Hence the incorrect statements are (b) and (c), i.e., option C.", "hasImage": false, "image": null}, {"id": 3, "subject": "Chemistry", "chapter": "Classification of Elements and Periodicity in Properties", "question": "Given below are the atomic masses of the elements:\nLi=7, Na=23, Cl=35.5, K=39, Ca=40, Br=80, Sr=88, I=127, Ba=137.\nWhich of the following doesn't form a triad?", "options": {"A": "Li, Na, K", "B": "Ba, Sr, Ca", "C": "Cl, Br, I", "D": "Cl, K, Ca"}, "correctAnswer": "D", "correctAnswerText": "Cl, K, Ca", "explanation": "Döbereiner's law of triads states that when three elements are arranged in order of increasing atomic mass, the atomic mass of the middle element is approximately the arithmetic mean of the atomic masses of the other two. Let us test each set. For Li (7), Na (23), K (39): the mean of Li and K is (7 + 39)/2 = 46/2 = 23, which equals the atomic mass of Na (23). So Li, Na, K form a triad. For Ba (137), Sr (88), Ca (40): the mean of Ba and Ca is (137 + 40)/2 = 177/2 = 88.5, which is approximately the atomic mass of Sr (88). So Ba, Sr, Ca form a triad. For Cl (35.5), Br (80), I (127): the mean of Cl and I is (35.5 + 127)/2 = 162.5/2 = 81.25, which is approximately the atomic mass of Br (80). So Cl, Br, I form a triad. For Cl (35.5), K (39), Ca (40): the mean of Cl and Ca is (35.5 + 40)/2 = 75.5/2 = 37.75, which does NOT equal the atomic mass of K (39). Therefore Cl, K, Ca do not form a Döbereiner triad. Hence the set that does not form a triad is Cl, K, Ca (option D). This question tests Döbereiner's triads, one of the early attempts at classification that later inspired Mendeleev's periodic law.", "hasImage": false, "image": null}, {"id": 4, "subject": "Chemistry", "chapter": "Chemical Bonding and Molecular Structure", "question": "The change in hybridisation (if any) of the 'Al' atom in the following reaction is:\nAlCl3 + Cl- → AlCl4-", "options": {"A": "sp2 to sp2", "B": "No change in the hybridisation state", "C": "sp2 to sp3", "D": "sp2 to sp3d"}, "correctAnswer": "C", "correctAnswerText": "sp2 to sp3", "explanation": "In AlCl3, the aluminium atom forms three sigma bonds with three chlorine atoms and has no lone pair of electrons on it. The number of sigma bonds (3) plus lone pairs (0) equals 3, which corresponds to sp2 hybridisation. Hence AlCl3 is trigonal planar with a bond angle of about 120°. When a chloride ion (Cl-) donates a lone pair of electrons to AlCl3, the adduct AlCl4- is formed. Now aluminium is bonded to four chlorine atoms (four sigma bonds) and has no lone pair. The steric number becomes 4 (four sigma bonds + zero lone pairs), which corresponds to sp3 hybridisation. Hence AlCl4- is tetrahedral in shape. The change in hybridisation is therefore from sp2 (in AlCl3) to sp3 (in AlCl4-). Note that the hybridisation of aluminium does not go to sp3d, because sp3d would require a coordination number of five (e.g., five sigma bonds) or appropriate lone pairs, which is not the case here. Also, AlCl3 acts as a Lewis acid (electron pair acceptor) and Cl- acts as a Lewis base; the formation of AlCl4- is a classic example of Lewis acid-base adduct formation. A common mistake is thinking AlCl3 is sp3 because it is a trivalent metal compound; but with only 3 bonds and no lone pairs it is sp2. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 5, "subject": "Chemistry", "chapter": "Chemical Bonding and Molecular Structure", "question": "Match List-I with List-II and select the correct option:\nList-I (Molecule/ion)    List-II (Bond order)\n(a) NO                     (i) 1.5\n(b) CO                     (ii) 2.0\n(c) O2-                    (iii) 2.5\n(d) O2                     (iv) 3.0", "options": {"A": "a-iv, b-iii, c-ii, d-i", "B": "a-iii, b-iv, c-i, d-ii", "C": "a-i, b-iv, c-iii, d-ii", "D": "a-ii, b-iii, c-iv, d-i"}, "correctAnswer": "B", "correctAnswerText": "a-iii, b-iv, c-i, d-ii", "explanation": "The bond order is calculated using molecular orbital theory by the formula: Bond order = 1/2 × (number of electrons in bonding molecular orbitals - number of electrons in antibonding molecular orbitals). For NO (14 + 1 = 15 electrons total), the bond order is 2.5 (this is a diatomic molecule with an odd number of electrons, giving a bond order of 2.5). For CO (carbon monoxide, 14 electrons total, isoelectronic with N2), the bond order is 3.0 (a triple bond: one sigma and two pi bonds). For O2- (superoxide ion, 16 + 1 = 17 electrons), the bond order is 1.5. For O2 (molecular oxygen, 16 electrons), the bond order is 2.0 (one sigma and one pi bond, with two unpaired electrons making it paramagnetic). Therefore the correct matching is: a (NO) → iii (2.5), b (CO) → iv (3.0), c (O2-) → i (1.5), d (O2) → ii (2.0). This corresponds to option B (a-iii, b-iv, c-i, d-ii). A useful comparison: N2 and CO both have bond order 3 (isoelectronic, 14 electrons); NO+ also has bond order 3. Remember that removing an electron from an antibonding orbital increases bond order, and adding an electron to an antibonding orbital decreases it. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 6, "subject": "Chemistry", "chapter": "Chemical Bonding and Molecular Structure", "question": "The electronic configuration of X and Y are given below:\nX: 1s2 2s2 2p6 3s2 3p3\nY: 1s2 2s2 2p6 3s2 3p5\nWhich of the following is the correct molecular formula and type of bond formed between X and Y?", "options": {"A": "X3Y, ionic bond", "B": "X2Y3, coordinate bond", "C": "XY3, covalent bond", "D": "X2Y, covalent bond"}, "correctAnswer": "C", "correctAnswerText": "XY3, covalent bond", "explanation": "The element X has the configuration 1s2 2s2 2p6 3s2 3p3, which means it has a total of 15 electrons and is phosphorus (P), an element of group 15 (nitrogen family) in the third period. Phosphorus has 5 valence electrons (3s2 3p3). The element Y has the configuration 1s2 2s2 2p6 3s2 3p5, with a total of 17 electrons, so it is chlorine (Cl), a halogen of group 17. Chlorine has 7 valence electrons (3s2 3p5). Phosphorus needs 3 more electrons to complete its octet, and each chlorine atom needs 1 electron. Hence one phosphorus atom combines with three chlorine atoms, giving the molecular formula PCl3, i.e., XY3. The bond between phosphorus and chlorine is formed by the mutual sharing of electron pairs (both are non-metals), so it is a COVALENT bond, not an ionic or coordinate bond. Ionic bonds form between a metal and a non-metal, and coordinate bonds form when one atom donates both electrons of a shared pair. PCl3 is a covalent molecular compound with a pyramidal shape (sp3 hybridisation of P with one lone pair). Hence the correct molecular formula and bond type is XY3 with a covalent bond. A common mistake is to think of X as nitrogen or to write the formula as X3Y; always count the electrons and identify the valencies. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 7, "subject": "Chemistry", "chapter": "Redox Reactions", "question": "Match List-I with List-II:\nList-I (Types of redox reactions)    List-II (Examples)\n(a) Combination reaction            (i) Cl2(g) + 2Br-(aq) → 2Cl-(aq) + Br2(l)\n(b) Decomposition reaction          (ii) 2H2O2(aq) → 2H2O(l) + O2(g)\n(c) Displacement reaction           (iii) CH4(g) + 2O2(g) → CO2(g) + 2H2O(l)\n(d) Disproportionation reaction     (iv) 2H2O(l) → 2H2(g) + O2(g)", "options": {"A": "a-iii, b-ii, c-i, d-iv", "B": "a-iv, b-iii, c-i, d-ii", "C": "a-ii, b-i, c-iv, d-iii", "D": "a-iii, b-iv, c-i, d-ii"}, "correctAnswer": "D", "correctAnswerText": "a-iii, b-iv, c-i, d-ii", "explanation": "Let us classify each reaction. (a) Combination reaction: two or more reactants combine to form a single product. CH4(g) + 2O2(g) → CO2(g) + 2H2O(l) is a combustion reaction, which is a special type of redox reaction; in the given matching it is paired with (iii). (b) Decomposition reaction: a single compound breaks into two or more simpler substances. 2H2O(l) → 2H2(g) + O2(g) (electrolysis of water) is a decomposition reaction, so b matches with (iv). (c) Displacement reaction: a more reactive element displaces a less reactive element from its compound. Cl2(g) + 2Br-(aq) → 2Cl-(aq) + Br2(l) is a displacement reaction (chlorine displaces bromine from bromide), so c matches with (i). (d) Disproportionation reaction: the same element is simultaneously oxidised and reduced (one atom of the element gains electrons while another loses them). In 2H2O2 → 2H2O + O2, the oxygen in H2O2 (oxidation state -1) is both reduced to -2 (in H2O) and oxidised to 0 (in O2). Hence it is a disproportionation reaction, so d matches with (ii). Therefore the correct matching is a-iii, b-iv, c-i, d-ii, which is option D. Remember the distinguishing test: in disproportionation, the same element shows both an increase and a decrease in oxidation number in the same reaction. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 8, "subject": "Chemistry", "chapter": "The d- and f-Block Elements", "question": "In the following pairs, the one in which both transition metal ions are colourless is", "options": {"A": "Ti3+, Cu2+", "B": "Sc3+, Zn2+", "C": "V3+, Ti4+", "D": "Zn2+, Mn2+"}, "correctAnswer": "B", "correctAnswerText": "Sc3+, Zn2+", "explanation": "The colour of a transition metal ion in solution is generally due to d-d transitions, in which an electron is excited from a lower-energy d orbital to a higher-energy d orbital by absorbing visible light. Such transitions require the ion to have partially filled d orbitals (d1 to d9). If the ion has a completely empty d subshell (d0) or a completely filled d subshell (d10), no d-d transition is possible and the ion is colourless. Sc3+ has the electronic configuration [Ar]3d0 (scandium loses its 3d and 4s electrons to form Sc3+, giving an empty d shell), so it is colourless. Zn2+ has the configuration [Ar]3d10 (zinc loses its two 4s electrons, leaving the 3d subshell completely filled), so it is also colourless. Therefore the pair Sc3+, Zn2+ has both ions colourless. Ti3+ is 3d1 (coloured, violet), Cu2+ is 3d9 (coloured, blue), V3+ is 3d2 (coloured, green), Ti4+ is 3d0 (colourless, but not paired with another colourless ion in the options), Mn2+ is 3d5 (coloured, pale pink). So only option B has both ions colourless. A useful memory aid: ions with d0 or d10 configuration are colourless; transition metal ions with d1 to d9 show colour due to d-d transitions. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 9, "subject": "Chemistry", "chapter": "Redox Reactions", "question": "In the reaction between hydrogen sulphide and acidified permanganate solution:", "options": {"A": "H2S is oxidised to S, MnO4- is reduced to Mn2+", "B": "H2S is reduced to S, MnO4- is oxidised to Mn2+", "C": "H2S is oxidised to SO2, MnO4- is reduced to MnO2", "D": "H2S is reduced to SO2, MnO4- is oxidised to Mn2+"}, "correctAnswer": "A", "correctAnswerText": "H2S is oxidised to S, MnO4- is reduced to Mn2+", "explanation": "Acidified potassium permanganate is a powerful oxidising agent. Hydrogen sulphide (H2S) is a reducing agent in which sulphur is in the -2 oxidation state. When H2S reacts with acidified KMnO4, the sulphur is oxidised from -2 to 0, forming elemental sulphur (S). Oxidation is the loss of electrons (increase in oxidation number from -2 to 0). Meanwhile, the permanganate ion (MnO4-), in which manganese is in the +7 oxidation state, is reduced to the manganese(II) ion (Mn2+) with manganese in the +2 oxidation state (decrease in oxidation number from +7 to +2 is reduction, i.e., gain of electrons). The purple colour of permanganate is decolourised as MnO4- is converted to the nearly colourless Mn2+ in acidic medium. The balanced reaction is: 2MnO4- + 5H2S + 6H+ → 2Mn2+ + 5S + 8H2O. Hence option A is correct: H2S is oxidised to S and MnO4- is reduced to Mn2+. Option B is wrong because MnO4- is reduced (not oxidised). Option C is wrong because in strongly acidic medium the reduction product of permanganate is Mn2+, not MnO2 (MnO2 is formed in neutral or alkaline medium), and H2S is oxidised to S, not SO2. Option D is wrong for the same reasons. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 10, "subject": "Chemistry", "chapter": "The d- and f-Block Elements", "question": "A member of the Lanthanoid series which is well known to exhibit +4 oxidation state is", "options": {"A": "Cerium", "B": "Samarium", "C": "Europium", "D": "Erbium"}, "correctAnswer": "A", "correctAnswerText": "Cerium", "explanation": "Lanthanoids generally exhibit the +3 oxidation state, which is the most common and stable state for the whole series. However, some lanthanoids also show other oxidation states. Cerium (Ce, Z = 58) is well known to exhibit the +4 oxidation state (Ce4+). This is because the +4 oxidation state of cerium leaves it with the electronic configuration [Xe]4f0, i.e., an empty 4f subshell, which has extra stability (the completely empty f subshell is highly stable). Ce4+ is a strong oxidising agent, and ceric sulphate/ceric ammonium nitrate are widely used as oxidising agents in titrimetric analysis. Samarium (Sm) and Europium (Eu) are instead known for the +2 oxidation state (Sm2+ is 4f6 and Eu2+ is 4f7, the half-filled subshell giving stability). Europium's +2 state is due to the stability of the half-filled 4f7 configuration. Erbium (Er) predominantly shows only the +3 oxidation state. Hence the lanthanoid well known for the +4 oxidation state is cerium. A useful memory aid: Ce4+ (empty 4f) and Tb4+ (half-filled 4f7) show +4; Sm2+, Eu2+ (half-filled 4f7) and Yb2+ show +2. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 11, "subject": "Chemistry", "chapter": "The d- and f-Block Elements", "question": "In which of the following pairs, both the elements do not have (n-1)d10 ns2 configuration?", "options": {"A": "Ag, Cu", "B": "Cu, Zn", "C": "Zn, Cd", "D": "Cd, Hg"}, "correctAnswer": "A", "correctAnswerText": "Ag, Cu", "explanation": "The (n-1)d10 ns2 configuration corresponds to the ground state electronic configuration of group 12 elements (Zn, Cd, Hg) where the d subshell is completely filled (d10) and the s subshell has two electrons (ns2). For example, Zn has [Ar]3d10 4s2, Cd has [Kr]4d10 5s2, and Hg has [Xe]4d14 5d10 6s2 (the 5d10 6s2). Therefore Zn and Cd (option C) both have the (n-1)d10 ns2 configuration, and so do Cd and Hg (option D) and Cu and Zn (option B). However, copper (Cu, Z = 29) has the exceptional configuration [Ar]3d10 4s1 (not 4s2) because a completely filled d subshell with a half-filled s orbital is more stable than a half-filled d9 4s2 arrangement. Similarly, silver (Ag, Z = 47) has the configuration [Kr]4d10 5s1, again deviating from (n-1)d10 ns2. Gold also has [Xe]4f14 5d10 6s1. Hence copper and silver do NOT have the (n-1)d10 ns2 configuration. Therefore the pair in which both elements do not have (n-1)d10 ns2 configuration is Ag and Cu. These are the famous exceptions in the d-block due to the extra stability of completely filled d orbitals. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 12, "subject": "Chemistry", "chapter": "Coordination Compounds", "question": "A ligand which has two different donor atoms and either of the two ligates with the central metal atom/ion in the complex is called", "options": {"A": "Ambidentate ligand", "B": "Chelate ligand", "C": "Unidentate ligand", "D": "Polydentate ligand"}, "correctAnswer": "A", "correctAnswerText": "Ambidentate ligand", "explanation": "An ambidentate ligand is a ligand that has two or more different donor atoms, but only one of them coordinates to the metal at a time. Since the ligand can attach through either of its two donor atoms, it is called 'ambidentate' (meaning 'both-toothed'). Classic examples are: the nitrite ion (NO2-) which can coordinate through the nitrogen atom (-NO2, nitro) or through an oxygen atom (-ONO, nitrito); the thiocyanate ion (SCN-) which can bind through sulphur (-SCN, thiocyanato) or through nitrogen (-NCS, isothiocyanato); and the cyanide ion (CN-) which can bind through carbon or nitrogen. A chelate ligand is a polydentate ligand that forms a ring structure by donating two or more donor atoms simultaneously to the metal (e.g., ethylenediamine, oxalate); it forms stable cyclic chelate complexes. A unidentate (monodentate) ligand has only one donor atom (e.g., NH3, Cl-, H2O). A polydentate ligand has two or more donor atoms all of which can simultaneously bind to the metal (e.g., EDTA is hexadentate). The key distinguishing feature of an ambidentate ligand is that it has different donor atoms but coordinates through only one at a time, which can give rise to linkage isomerism. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 13, "subject": "Chemistry", "chapter": "Coordination Compounds", "question": "Which of the following statements are true about [NiCl4]2-?\n(a) The complex has tetrahedral geometry.\n(b) Co-ordination number of Ni is 2 and oxidation state is +4.\n(c) The complex is sp3 hybridised.\n(d) It is a high spin complex.\n(e) The complex is paramagnetic.", "options": {"A": "a, b, c and d", "B": "a, c, d and e", "C": "a, b, d and e", "D": "b, c, d and e"}, "correctAnswer": "B", "correctAnswerText": "a, c, d and e", "explanation": "Let us analyse the complex [NiCl4]2-. The oxidation state of nickel is calculated as: x + 4(-1) = -2, so x = +2. Hence the oxidation state of Ni is +2, not +4 (so statement b is false). The coordination number is the number of donor atoms bonded to the metal, which is 4 (four chloride ligands), not 2. Ni in the +2 state has the electronic configuration [Ar]3d8. Chloride (Cl-) is a weak-field ligand, so it does not cause pairing of the d-electrons. For a coordination number of 4 with a weak-field ligand, the complex is tetrahedral with sp3 hybridisation of the central metal (statement a: tetrahedral geometry - true; statement c: sp3 hybridised - true). Since Cl- is a weak-field ligand, the complex is a high spin complex (statement d is true). Ni2+ in a tetrahedral field has two unpaired electrons (3d8 gives two unpaired electrons), so the complex is paramagnetic (statement e is true). Therefore the true statements are a, c, d and e, which is option B. Statement b is incorrect because both the coordination number (4) and oxidation state (+2) are wrongly given. A common mistake is to think [NiCl4]2- is square planar (like [Ni(CN)4]2-); square planar geometry occurs with strong-field ligands (CN-), whereas Cl- gives a tetrahedral sp3 complex. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 14, "subject": "Chemistry", "chapter": "Coordination Compounds", "question": "Which formula and its name combination is incorrect?", "options": {"A": "[Pt(NH3)2Cl(NO2)] - Diamine chloridonitrito-N-platinum(II)", "B": "K3[Cr(C2O4)3] - Potassium trioxalatochromate(III)", "C": "[CoCl2(en)2]Cl - Dichloridobis(ethane-1,2-diamine)cobalt(III) chloride", "D": "[Co(NH3)5(CO3)]Cl - Pentaaminecarbonatocobalt(III) chloride"}, "correctAnswer": "D", "correctAnswerText": "[Co(NH3)5(CO3)]Cl - Pentaaminecarbonatocobalt(III) chloride", "explanation": "Let us check each combination according to IUPAC nomenclature rules. Option A: [Pt(NH3)2Cl(NO2)] is named as 'Diamine chloridonitrito-N-platinum(II)'. The ligands are ammonia (ammine, so 'diammine' is correct), chloride (chlorido) and nitrite bonded through N (nitrito-N). Since the complex is neutral, the metal name is used directly with its oxidation state. The name is essentially correct (though 'diammine' is more correct than 'diamine'; in this version both are accepted). Option B: K3[Cr(C2O4)3] is 'Potassium trioxalatochromate(III)'. Since the complex ion is an anion ([Cr(C2O4)3]3-), the metal name ends in '-ate', giving 'chromate'; oxalate is the ligand name, so 'trioxalatochromate(III)' is correct. Option C: [CoCl2(en)2]Cl is 'Dichloridobis(ethane-1,2-diamine)cobalt(III) chloride'. The complex cation has cobalt, two chlorides and two ethylenediamine ligands, with one chloride counter ion, and the oxidation state of Co is +3. The name is correct. Option D: [Co(NH3)5(CO3)]Cl is named 'Pentaaminecarbonatocobalt(III) chloride'. This is INCORRECT because the carbonate ligand (CO32-) must be written as 'carbonato', not 'carbonyl'. The correct name is 'Pentaamminecarbonatocobalt(III) chloride'. 'Carbonyl' refers to the CO ligand (carbon monoxide), not the carbonate ion. Hence the incorrect combination is option D. Remember: CO3 = carbonate (carbonato), CO = carbonyl, CN = cyano, etc.", "hasImage": false, "image": null}, {"id": 15, "subject": "Chemistry", "chapter": "Coordination Compounds", "question": "In the complex ion [Fe(C2O4)3]3-, the coordination number of Fe is", "options": {"A": "3", "B": "4", "C": "5", "D": "6"}, "correctAnswer": "D", "correctAnswerText": "6", "explanation": "The coordination number of a metal in a complex is the total number of donor atoms that are directly bonded to the central metal ion. In the complex [Fe(C2O4)3]3-, the ligands are three oxalate ions (C2O42-). The oxalate ion is a BIDENTATE ligand because each oxalate ion has two donor atoms - the two oxygen atoms of its two carboxylate groups (COO-) that can both donate their lone pairs to the metal. Since there are three oxalate ions and each provides two donor atoms, the total number of donor atoms bonded to Fe is 3 × 2 = 6. Hence the coordination number of Fe is 6. The geometry of the [Fe(C2O4)3]3- ion is octahedral, and this complex shows optical isomerism (it is optically active). A common mistake is to count the number of ligands (3) instead of the number of donor atoms (6); coordination number counts donor ATOMS, not ligand molecules. Other bidentate ligands like ethylenediamine (en) also contribute 2 to the coordination number each, e.g., [Co(en)3]3+ has coordination number 6. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 16, "subject": "Chemistry", "chapter": "Biomolecules", "question": "Match List-I with List-II for the following reaction pattern:\nGlucose --Reagent--> Product --> Structural prediction\nList-I (Reagents)    List-II (Structural prediction)\n(a) Acetic anhydride   (i) Glucose has an aldehyde group\n(b) Bromine water      (ii) Glucose has a straight chain of six carbon atoms\n(c) Hydroiodic acid    (iii) Glucose has five hydroxyl groups\n(d) Hydrogen cyanide   (iv) Glucose has a carbonyl group", "options": {"A": "a-iii, b-ii, c-i, d-iv", "B": "a-iv, b-iii, c-ii, d-i", "C": "a-iii, b-i, c-ii, d-iv", "D": "a-i, b-ii, c-iii, d-iv"}, "correctAnswer": "C", "correctAnswerText": "a-iii, b-i, c-ii, d-iv", "explanation": "This question tests the reactions used to determine the structure of glucose. (a) When glucose reacts with acetic anhydride, it forms glucose pentaacetate, i.e., all five hydroxyl groups of glucose are acetylated. This proves that glucose has FIVE hydroxyl groups (-OH), so (a) matches with (iii). (b) Bromine water oxidises only the aldehyde group (it oxidises the -CHO of glucose to a carboxylic acid group, forming gluconic acid) but does not affect the other hydroxyl groups. This proves that glucose has an aldehyde group, so (b) matches with (i). (c) When glucose is treated with hydroiodic acid (HI) under reducing conditions, it is reduced to n-hexane, a straight chain of six carbon atoms. This proves that glucose has a STRAIGHT CHAIN of six carbon atoms, so (c) matches with (ii). (d) Hydrogen cyanide (HCN) adds to the carbonyl group (C=O) of glucose to form cyanohydrin. Since HCN adds to a carbonyl group and increases the chain length by one carbon, this proves that glucose has a carbonyl group, so (d) matches with (iv). Therefore the correct matching is a-iii, b-i, c-ii, d-iv, which is option C. These classical glucose structure-proving reactions were used by early chemists (Fischer, Kiliani) to establish the open-chain aldohexose structure of glucose. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 17, "subject": "Chemistry", "chapter": "Biomolecules", "question": "The correct sequence of α-amino acid, hormone, vitamin, carbohydrates respectively is", "options": {"A": "Aspartic acid, Insulin, Ascorbic acid, Rhamnose", "B": "Thiamine, Thyroxine, Vitamin A, Glucose", "C": "Glutamine, Insulin, Aspartic acid, Fructose", "D": "Arginine, Testosterone, Glutamic acid, Maltose"}, "correctAnswer": "A", "correctAnswerText": "Aspartic acid, Insulin, Ascorbic acid, Rhamnose", "explanation": "We need to pick the option that lists, in order, an α-amino acid, a hormone, a vitamin and a carbohydrate. Aspartic acid is an α-amino acid (it has both -NH2 and -COOH groups attached to the same (α) carbon). Insulin is a peptide hormone secreted by the beta cells of the pancreas that regulates blood glucose. Ascorbic acid is vitamin C (an essential water-soluble vitamin). Rhamnose is a carbohydrate (a naturally occurring deoxy sugar, C6H12O5, found in plant glycosides). So option A gives the correct sequence. In option B, Thiamine is a vitamin (vitamin B1), not an amino acid, so the sequence is wrong. In option C, Glutamine is an amino acid and Insulin a hormone, but Aspartic acid (the third member) is an amino acid, not a vitamin, and Fructose is a carbohydrate, so the sequence of 'vitamin' is wrong. In option D, Arginine is an amino acid, Testosterone is a hormone, but Glutamic acid (third) is an amino acid, not a vitamin, and Maltose is a carbohydrate. Hence only option A has the correct order of an α-amino acid, hormone, vitamin and carbohydrate. A useful fact: vitamins are essential organic nutrients needed in small amounts; ascorbic acid (vitamin C) is water soluble. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 18, "subject": "Chemistry", "chapter": "Biomolecules", "question": "Which examples of carbohydrates exhibit α-link (α-glycosidic link) in their structure?", "options": {"A": "Glucose and Fructose", "B": "Maltose and Lactose", "C": "Amylose and Amylopectin", "D": "Cellulose and Glycogen"}, "correctAnswer": "C", "correctAnswerText": "Amylose and Amylopectin", "explanation": "An α-glycosidic linkage is formed when the glycosidic bond is created using the α-anomeric carbon of the monosaccharide. Amylose and amylopectin are the two components of starch, and both contain α-glycosidic linkages. Amylose has α-1,4-glycosidic linkages between its α-D-glucose units (a linear chain), while amylopectin has α-1,4-glycosidic bonds in the linear portions and α-1,6-glycosidic bonds at the branch points. Hence both amylose and amylopectin exhibit α-linkages. Cellulose, on the other hand, has β-1,4-glycosidic linkages (β-D-glucose units linked through beta bonds), which is why cellulose is indigestible by humans while starch is digestible. Glycogen also contains α-1,4 and α-1,6 linkages, but since it is not paired with cellulose in option D (cellulose has β links), option D is incorrect. Maltose has an α-1,4-glycosidic linkage, but lactose has a β-1,4-glycosidic linkage (between glucose and galactose), so option B is not entirely correct. Glucose and fructose are monosaccharides that do not contain a glycosidic bond at all (they are monomeric units). Hence the pair in which both exhibit α-glycosidic linkage is amylose and amylopectin. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 19, "subject": "Chemistry", "chapter": "Redox Reactions", "question": "In the titration of potassium permanganate (KMnO4) against Ferrous ammonium sulphate (FAS) solution, dilute sulphuric acid but not nitric acid is used to maintain acidic medium, because", "options": {"A": "Nitric acid is a weaker acid than sulphuric acid", "B": "It is difficult to identify the end point", "C": "Nitric acid doesn't act as an indicator", "D": "Nitric acid itself is an oxidising agent"}, "correctAnswer": "D", "correctAnswerText": "Nitric acid itself is an oxidising agent", "explanation": "In the titration of potassium permanganate with ferrous ammonium sulphate (FAS, Mohr's salt), the medium must be acidic so that the permanganate ion (MnO4-) is reduced to Mn2+ (in strongly acidic medium the reduction product is Mn2+, whereas in neutral/alkaline medium it forms MnO2, a brown precipitate, which would make the endpoint unclear). Dilute sulphuric acid is the acid of choice because sulphuric acid does not take part in the redox reaction. Nitric acid (HNO3) cannot be used because nitric acid itself is a strong OXIDISING AGENT. If nitric acid is added, it would itself oxidise the ferrous ion (Fe2+) to ferric ion (Fe3+), i.e., HNO3 + Fe2+ → Fe3+ + NO, etc., thereby consuming some of the Fe2+ that was supposed to react only with permanganate. This would give an incorrect (higher) titre value. Also, nitric acid could be reduced by the ferrous ions, interfering with the stoichiometry. Hydrochloric acid is also avoided because chloride ions can be oxidised by permanganate to chlorine gas, again interfering. Hence dilute sulphuric acid is used. The reason nitric acid is not used is that it is itself an oxidising agent (option D). Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 20, "subject": "Chemistry", "chapter": "Qualitative Analysis (Equilibrium)", "question": "The group reagent NH4Cl(s) and aqueous NH3 will precipitate which of the following ion?", "options": {"A": "Ca2+", "B": "NH4+", "C": "Al3+", "D": "Ba2+"}, "correctAnswer": "C", "correctAnswerText": "Al3+", "explanation": "In qualitative analysis, the group reagent of the third group of basic radicals (cations) is NH4Cl(s) + NH4OH (aqueous ammonia). This reagent precipitates the hydroxides of the group III cations, which are Fe3+, Al3+ and Cr3+. When NH4OH (a weak base) is added along with solid NH4Cl, the NH4Cl suppresses the dissociation of NH4OH by the common ion effect, keeping the OH- concentration low. This low OH- concentration is sufficient to precipitate the group III hydroxides (which have very low solubility product) but not the hydroxides of groups IV and V. Aluminium ion (Al3+) forms a gelatinous white precipitate of Al(OH)3 with this reagent: Al3+ + 3OH- → Al(OH)3 (white, gelatinous). Ca2+ and Ba2+ are group V radicals, precipitated as carbonates (CaCO3, BaCO3) by (NH4)2CO3, not by NH4Cl/NH4OH. NH4+ itself cannot be precipitated as its hydroxide. Hence the ion precipitated by the group III reagent NH4Cl(s) + NH4OH is Al3+. The white gelatinous Al(OH)3 precipitate dissolves in excess NaOH (amphoteric behaviour), which is used to confirm Al3+. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 21, "subject": "Chemistry", "chapter": "Organic Chemistry: Some Basic Principles and Techniques", "question": "In the preparation of sodium fusion extract, the purpose of fusing organic compound with a piece of sodium metal is to", "options": {"A": "Decrease the melting point of the compound", "B": "Convert the organic compound into vapour state", "C": "Convert the elements of the compound from covalent form to ionic form", "D": "Convert the elements of the compound from ionic form to covalent form"}, "correctAnswer": "C", "correctAnswerText": "Convert the elements of the compound from covalent form to ionic form", "explanation": "The sodium fusion test (Lassaigne's test) is used to detect the presence of nitrogen, sulphur, halogens and phosphorus in organic compounds. Organic compounds are largely covalent, and their constituent elements (N, S, Cl, Br, I, P) are covalently bonded to carbon. For these elements to be detected by simple chemical tests (like precipitation with AgNO3 or Fe4[Fe(CN)6]3 for nitrogen), they must first be converted into water-soluble ionic (inorganic) compounds. This is achieved by fusing the organic compound with a piece of metallic sodium in a fusion tube. During fusion, the sodium metal reduces the covalent organic compound and converts its elements into ionic compounds: nitrogen forms sodium cyanide (NaCN), sulphur forms sodium sulphide (Na2S), halogens form sodium halides (NaX), and phosphorus forms sodium phosphate (Na3PO4). These ions are then extracted with distilled water to prepare the sodium fusion extract, which is used for the qualitative tests. Hence the purpose of fusing with sodium is to convert the elements of the organic compound from their covalent form into ionic form so that they can be tested in aqueous solution. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 22, "subject": "Chemistry", "chapter": "Organic Chemistry: Some Basic Principles and Techniques", "question": "The sodium fusion extract is boiled with concentrated nitric acid while testing for halogens. By doing so, it", "options": {"A": "decomposes Na2S and NaCN, if formed", "B": "helps in precipitation of AgCl", "C": "increases the solubility of AgCl", "D": "increases the concentration of NO3- ion"}, "correctAnswer": "A", "correctAnswerText": "decomposes Na2S and NaCN, if formed", "explanation": "In the Lassaigne's test for halogens, the sodium fusion extract is first boiled with concentrated nitric acid (HNO3) before adding silver nitrate (AgNO3). The purpose of this step is to decompose sodium sulphide (Na2S) and sodium cyanide (NaCN), which may have been formed during the fusion if the organic compound contained sulphur and nitrogen along with the halogen. If Na2S and NaCN are not destroyed, they would interfere with the silver nitrate test: Ag+ would react with S2- to form black silver sulphide (Ag2S) and with CN- to form white silver cyanide (AgCN), which would be confused with silver halide precipitates. Boiling with concentrated HNO3 destroys these interfering ions: Na2S + 2HNO3 → 2NaNO3 + H2S (H2S escapes) and NaCN + HNO3 → NaNO3 + HCN (HCN escapes as gas). Only after removing these interfering species can the halide be correctly precipitated as AgX (silver halide). Options B, C and D describe incorrect purposes; the precipitation of AgCl happens later when AgNO3 is added, and concentrated HNO3 does not increase AgCl solubility or NO3- concentration as its purpose. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 23, "subject": "Chemistry", "chapter": "Hydrocarbons", "question": "Which of the following is not an aromatic compound? (Structures are shown as figures in the question paper.)", "options": {"A": "Structure (1): a benzene ring (C6H6)", "B": "Structure (2): naphthalene", "C": "Structure (3): a five-membered ring with conjugated double bonds", "D": "Structure (4): a cyclic compound lacking full conjugation"}, "correctAnswer": "D", "correctAnswerText": "Structure (4): a cyclic compound lacking full conjugation", "explanation": "According to Hückel's rule, a compound is aromatic if it is cyclic, planar, fully conjugated (continuous overlap of p orbitals all around the ring) and contains (4n + 2) π electrons, where n = 0, 1, 2, 3, etc. Benzene (option 1) is the simplest aromatic hydrocarbon with 6 π electrons (4n + 2 with n = 1), satisfying Hückel's rule. Naphthalene (option 2) is a fused bicyclic aromatic compound with 10 π electrons (4n + 2 with n = 2), and it is aromatic. The five-membered ring with conjugated double bonds (option 3), such as cyclopentadienyl anion or pyrrole-type ring, is also aromatic because it satisfies the (4n + 2) π-electron rule (e.g., pyrrole has 6 π electrons). Option (4) is the compound that is NOT aromatic. A cyclic compound that lacks a fully conjugated system (i.e., the p orbitals do not overlap continuously around the ring, or the number of π electrons does not fit 4n + 2) is non-aromatic. For example, cyclooctatetraene is non-planar and non-aromatic even though it has 8 π electrons (4n, not 4n + 2), and a cyclic compound with an sp3 carbon (breaking conjugation) is also non-aromatic. Hence the non-aromatic compound is option (4). Remember the aromaticity checklist: cyclic + planar + fully conjugated + (4n + 2) π electrons. Hence the correct answer is D.", "hasImage": true, "image": null}, {"id": 24, "subject": "Chemistry", "chapter": "Hydrocarbons (Nomenclature)", "question": "The IUPAC name of the given organic compound is:\nHC≡C - CH = CH - CH = CH2", "options": {"A": "Hexa-3,5-dien-1-yne", "B": "Hexa-1-yn-3,5-diene", "C": "Hexa-5-yn-1,3-diene", "D": "Hexa-1,3-dien-5-yne"}, "correctAnswer": "D", "correctAnswerText": "Hexa-1,3-dien-5-yne", "explanation": "The given compound is HC≡C-CH=CH-CH=CH2, which contains six carbon atoms in the longest chain (a hexa skeleton). It has two double bonds (diene) and one triple bond (yne). According to IUPAC rules, when a molecule contains both double and triple bonds, the parent chain is numbered so as to give the lowest possible locants to the multiple bonds as a set. If there is a tie, the double bonds (ene) are given preference over triple bonds (yne) in numbering. Numbering from the left (starting at the triple-bond carbon): C1 (triple bond), C3 (double), C5 (double) → locants 1, 3, 5. Numbering from the right (starting at the CH2 group): C1 (double), C3 (double), C5 (triple) → locants 1, 3, 5. Both directions give the same set of lowest locants (1, 3, 5), so there is no ambiguity. Since we prefer giving the lower number to the double bond in a tie, the double bonds get positions 1 and 3, and the triple bond gets position 5. Hence the name is Hexa-1,3-dien-5-yne (option D). When the name is written, the -ene suffix is placed before the -yne suffix ('diene' before 'yne'), and the lowest set of locants is used. Option A (Hexa-3,5-dien-1-yne) puts the triple bond at 1 and double bonds at 3,5, but the preferred numbering in a tie gives the double bonds the lower numbers, so option D is correct. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 25, "subject": "Chemistry", "chapter": "Hydrocarbons", "question": "Among the following, identify the compound that is not an isomer of hexane. (Structures shown as figures.)", "options": {"A": "2-methylpentane", "B": "3-methylpentane", "C": "n-hexane (CH3CH2CH2CH2CH2CH3)", "D": "A cyclic compound with formula different from C6H14"}, "correctAnswer": "D", "correctAnswerText": "A cyclic compound with formula different from C6H14", "explanation": "Isomers of hexane are compounds that have the SAME molecular formula C6H14 but different structural arrangements. The known structural isomers of hexane (C6H14) are: n-hexane (CH3CH2CH2CH2CH2CH3), 2-methylpentane, 3-methylpentane, 2,2-dimethylbutane and 2,3-dimethylbutane. Options A (2-methylpentane) and B (3-methylpentane) both have the formula C6H14 (they are methylpentanes with a branched six-carbon skeleton), so they ARE isomers of hexane. Option C is n-hexane itself, which obviously has the formula C6H14 and is an isomer (indeed, it is the straight-chain isomer). Option D is a cyclic compound whose molecular formula is different from C6H14. A cyclic alkane like cyclohexane has the formula C6H12 (cycloalkanes have the general formula CnH2n), which is NOT the same as C6H14. Since isomers must have the same molecular formula, a compound with formula C6H12 (or any formula other than C6H14) is NOT an isomer of hexane. Hence the compound that is not an isomer of hexane is the cyclic compound with a different formula (option D). Remember: isomerism requires the same molecular formula; a ring compound has two fewer hydrogens than the corresponding acyclic alkane. Hence the correct answer is D.", "hasImage": true, "image": null}, {"id": 26, "subject": "Chemistry", "chapter": "Haloalkanes and Haloarenes", "question": "The organic compound C6H5CH2Cl can be classified as", "options": {"A": "Alkyl halide", "B": "Allylic halide", "C": "Benzyl halide", "D": "Aryl halide"}, "correctAnswer": "C", "correctAnswerText": "Benzyl halide", "explanation": "The compound C6H5CH2Cl is benzyl chloride. In this compound, the chlorine atom is attached to a carbon that is directly bonded to a benzene ring (an sp3 carbon of the -CH2- group attached to the aromatic ring). This type of halide is called a BENZYL halide (specifically benzyl chloride), because the halogen-bearing carbon is attached to an aromatic (benzene) ring through a methylene group. An alkyl halide is a compound in which the halogen is attached to an aliphatic (non-aromatic) carbon, e.g., CH3Cl, CH3CH2Br. An allylic halide is one in which the halogen-bearing carbon is adjacent to a C=C double bond, e.g., CH2=CH-CH2Cl (3-chloroprop-1-ene). An aryl halide is one in which the halogen is directly attached to the aromatic ring carbon, e.g., chlorobenzene (C6H5Cl). The distinction is where the halogen sits: in C6H5CH2Cl, Cl is on a benzylic carbon (the CH2 between the ring and the Cl), making it a benzyl halide; in C6H5Cl, Cl is on the ring carbon, making it an aryl halide. Benzyl halides are quite reactive in SN1 reactions because the benzyl carbocation is stabilised by resonance with the aromatic ring. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 27, "subject": "Chemistry", "chapter": "Haloarenes (Hydrocarbons)", "question": "Chlorobenzene reacts with bromine gas in the presence of anhydrous AlBr3 to yield p-Bromochlorobenzene. This reaction is classified as", "options": {"A": "Addition reaction", "B": "Elimination reaction", "C": "Nucleophilic substitution reaction", "D": "Electrophilic substitution reaction"}, "correctAnswer": "D", "correctAnswerText": "Electrophilic substitution reaction", "explanation": "Chlorobenzene undergoes electrophilic aromatic substitution reactions. The reaction of chlorobenzene with bromine (Br2) in the presence of a Lewis acid catalyst such as anhydrous AlBr3 (or FeBr3, FeCl3) produces p-bromochlorobenzene (along with a smaller amount of the ortho isomer). The mechanism: the AlBr3 catalyst polarises the Br2 molecule, generating the bromonium-type electrophile (Br+). This electrophile attacks the benzene ring of chlorobenzene, forming a sigma (arenium) complex, and a proton is lost to regenerate the aromatic ring. The chlorine substituent on the ring is an ortho/para director (it activates the ortho and para positions through resonance donation of the chlorine lone pairs), so the incoming bromine mainly goes to the para position, giving p-bromochlorobenzene. Since an electrophile (Br+) replaces a hydrogen atom on the aromatic ring, this reaction is an electrophilic substitution reaction. It is not an addition reaction (no π bond addition across a double bond), not an elimination reaction (no HX is eliminated to form a double bond), and not a nucleophilic substitution (the attacking species is an electrophile, not a nucleophile). Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 28, "subject": "Chemistry", "chapter": "Haloalkanes and Haloarenes", "question": "The organometallic compound (CH3)3CMgBr on reaction with D2O produces", "options": {"A": "(CH3)3CD", "B": "(CH3)3COD", "C": "(CD3)3CD", "D": "(CD3)3COD"}, "correctAnswer": "A", "correctAnswerText": "(CH3)3CD", "explanation": "(CH3)3CMgBr is a Grignard reagent (tert-butylmagnesium bromide). Grignard reagents (RMgX) are strong bases and nucleophiles. When a Grignard reagent reacts with water (H2O) or heavy water (D2O), the acidic hydrogen (or deuterium) of water is abstracted by the carbanion-like carbon of the Grignard reagent, replacing the -MgBr group with H (or D). The carbon-magnesium bond is highly polarised, with the carbon bearing a partial negative charge, so it attacks the positively polarised H (or D) of water. With D2O: (CH3)3C-MgBr + D2O → (CH3)3C-D + Mg(OD)Br. The product is tert-butyl deuteride, (CH3)3CD. The three methyl groups remain as CH3 (they are unaffected), and only the carbon attached to magnesium picks up the deuterium atom (D). Hence the product is (CH3)3CD, option A. This reaction is used to introduce a deuterium atom into a molecule and to determine the number of active hydrogen atoms or to confirm the structure of Grignard reagents. Options C and D would require the methyl groups to also exchange with deuterium, which does not happen in this simple acid-base reaction. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 29, "subject": "Chemistry", "chapter": "Haloalkanes and Haloarenes", "question": "The major product formed when 1-Bromo-3-Chlorocyclobutane reacts with metallic sodium in dry ether is (structure options shown as figures).", "options": {"A": "Structure (1)", "B": "Structure (2)", "C": "Structure (3)", "D": "Structure (4)"}, "correctAnswer": "B", "correctAnswerText": "Structure (2): a bicyclic product (bicyclo[2.2.2]octane derivative)", "explanation": "1-Bromo-3-chlorocyclobutane has both a bromine atom at C1 and a chlorine atom at C3 of a cyclobutane ring. When it reacts with metallic sodium in dry ether, the Wurtz reaction takes place. In the Wurtz reaction, sodium metal causes the coupling of the two carbon-halogen bonds. Here, since both halogens are on the same molecule and are positioned 1,3 to each other, an intramolecular Wurtz coupling can occur, joining the two cyclobutane units together through a new C-C bond formed between the carbon that bore the Br and the carbon that bore the Cl of two different molecules (intermolecular coupling), producing a bicyclic product. The coupling of two molecules of 1-bromo-3-chlorocyclobutane through their 1- and 3-positions links the two cyclobutane rings into a fused/bridged bicyclic system; the product is a bicyclo[2.2.2]octane derivative (a bicyclic structure in which the two rings are connected by two two-carbon bridges and one one-carbon bridge... the standard product described for this reaction). The product is option (2), the bicyclic compound. The Wurtz reaction with metallic sodium in dry ether is classically used to prepare higher alkanes by coupling alkyl halides; with dihalides positioned suitably on a ring, it produces bicyclic or cyclic products. Hence the correct answer is B.", "hasImage": true, "image": null}, {"id": 30, "subject": "Chemistry", "chapter": "Alcohols, Phenols and Ethers", "question": "Ethyl alcohol is heated with concentrated sulphuric acid at 413 K (140°C). The major product formed is", "options": {"A": "CH3COOC2H5", "B": "C2H5-O-C2H5", "C": "CH3-O-C2H5", "D": "CH2=CH2"}, "correctAnswer": "B", "correctAnswerText": "C2H5-O-C2H5 (diethyl ether)", "explanation": "When ethanol (ethyl alcohol) is heated with concentrated sulphuric acid, the product depends on the temperature. At a temperature of about 413 K (140°C), the reaction is an intermolecular dehydration (dehydration between two molecules of ethanol), and the product is DIETHYL ETHER (C2H5-O-C2H5). The mechanism: one ethanol molecule is protonated by H2SO4 to form ethyl hydrogen sulphate or an oxonium ion, and then a second ethanol molecule attacks, losing a water molecule to form the ether. The overall reaction is: 2C2H5OH →(conc. H2SO4, 413 K) C2H5-O-C2H5 + H2O. If the temperature is raised to about 443 K (170°C), the reaction instead becomes an intramolecular dehydration (elimination of water from a single ethanol molecule), giving ethene (CH2=CH2): C2H5OH →(conc. H2SO4, 443 K) CH2=CH2 + H2O. Hence the temperature distinguishes ether formation (413 K) from alkene formation (443 K). CH3COOC2H5 is ethyl ethanoate (an ester), which is not formed by this dehydration. CH3-O-C2H5 (methyl ethyl ether) would require methanol, not ethanol. So the major product at 413 K is diethyl ether, option B. Remember: 413 K (140°C) = ether; 443 K (170°C) = alkene. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 31, "subject": "Chemistry", "chapter": "Alcohols, Phenols and Ethers", "question": "Phenol can be distinguished from propanol by using the reagent", "options": {"A": "Sodium metal", "B": "Bromine water", "C": "Iron metal", "D": "Iodine in alcohol"}, "correctAnswer": "B", "correctAnswerText": "Bromine water", "explanation": "Phenol and propanol (an aliphatic alcohol) can be distinguished by bromine water. Phenol, when treated with bromine water, undergoes electrophilic substitution and gives a white precipitate of 2,4,6-tribromophenol. This is a characteristic test: the bromine water is decolourised and a white crystalline precipitate (with a characteristic smell) is formed. Propanol (a saturated aliphatic alcohol) does not react with bromine water under ordinary conditions; bromine water remains reddish-brown with propanol because saturated alcohols have no C=C bonds to add bromine and no activated aromatic ring to undergo substitution. Both phenol and propanol react with sodium metal, releasing hydrogen gas (both have acidic/reactive -OH hydrogens), so sodium metal cannot distinguish them. Iron metal does not react characteristically with either under the test conditions. Iodine in alcohol (iodoform test) distinguishes only methyl ketones or secondary alcohols with a CH3-CH(OH)- group (like propan-2-ol), not phenol from propan-1-ol in a simple way. Hence bromine water is the correct reagent. Remember: phenol gives a white precipitate of tribromophenol with bromine water, which is a standard distinguishing test for phenol vs. aliphatic alcohols. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 32, "subject": "Chemistry", "chapter": "Alcohols, Phenols and Ethers", "question": "Match the following with their pKa values:\nAcid                 pKa\n(I) Phenol            (a) 16\n(II) p-Nitrophenol    (b) 0.78\n(III) Ethyl alcohol   (c) 10\n(IV) Picric acid      (d) 7.1", "options": {"A": "I-b, II-a, III-d, IV-c", "B": "I-c, II-d, III-a, IV-b", "C": "I-a, II-d, III-c, IV-b", "D": "I-a, II-b, III-c, IV-d"}, "correctAnswer": "B", "correctAnswerText": "I-c, II-d, III-a, IV-b", "explanation": "The pKa value is a measure of acidity: a lower pKa indicates a stronger acid (more readily losing a proton). Let us order the acids. Phenol has a pKa of about 10 (option c): phenol is a weak acid, much more acidic than alcohols but far weaker than mineral acids. p-Nitrophenol has a pKa of about 7.1 (option d): the electron-withdrawing nitro group at the para position stabilises the phenoxide ion by resonance and inductive effects, making p-nitrophenol more acidic than phenol. Ethyl alcohol has a pKa of about 16 (option a): alcohols are very weak acids (they do not readily lose the O-H hydrogen); their pKa (~16-18) is much higher than phenols. Picric acid (2,4,6-trinitrophenol) has a pKa of about 0.78 (option b): the three electron-withdrawing nitro groups dramatically stabilise the phenoxide ion, making picric acid a very strong acid (comparable to strong mineral acids). Therefore the correct matching is: I (Phenol) → c (10), II (p-Nitrophenol) → d (7.1), III (Ethyl alcohol) → a (16), IV (Picric acid) → b (0.78). This is option B. Remember the trend: picric acid (0.38-0.78) < p-nitrophenol (7.1) < phenol (10) < ethyl alcohol (16); the more electron-withdrawing groups on the ring, the stronger the acid. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 33, "subject": "Chemistry", "chapter": "Alcohols, Phenols and Ethers", "question": "CH3-C(CH3)2-OCH3 + HI → A + B. A and B respectively are:", "options": {"A": "A = CH3OH, B = (CH3)3COH", "B": "A = CH3I, B = (CH3)3COH", "C": "A = CH3OH, B = (CH3)3CI", "D": "A = CH3I, B = (CH3)3CI"}, "correctAnswer": "C", "correctAnswerText": "A = CH3OH, B = (CH3)3CI", "explanation": "The given compound is tert-butyl methyl ether, (CH3)3C-OCH3, an unsymmetrical ether. When an ether is treated with hydrogen iodide (HI), the ether linkage is cleaved (ether cleavage). For unsymmetrical ethers, the cleavage follows a rule related to carbocation stability. If one of the alkyl groups can form a more stable carbocation, that group leaves as the alkyl iodide. In this case, the tert-butyl group (from (CH3)3C-) can form a highly stable tertiary carbocation (CH3)3C+, so the tert-butyl group forms tert-butyl iodide, (CH3)3CI, while the methyl group remains as methanol, CH3OH. The mechanism: the ether oxygen is protonated by HI, and the tert-butyl group leaves as the stable tertiary carbocation (CH3)3C+, which immediately combines with I- to give (CH3)3CI. The remaining -OCH3 part captures the water/hydrogen to form methanol (CH3OH). Hence A = CH3OH (methanol) and B = (CH3)3CI (tert-butyl iodide). This is why option C is correct. If the reaction proceeded by simple SN2 attack of I- on the methyl carbon, we would get CH3I and (CH3)3COH; but because the tertiary carbocation is much more stable, the favoured product is the tert-butyl iodide. A useful rule for asymmetric ether cleavage with HI: the smaller/primary alkyl group tends to form the alcohol, and the group that gives the more stable carbocation forms the alkyl iodide. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 34, "subject": "Chemistry", "chapter": "Aldehydes, Ketones and Carboxylic Acids", "question": "Oxidation of Toluene with chromyl chloride followed by hydrolysis gives Benzaldehyde. This reaction is known as:", "options": {"A": "Cannizzaro Reaction", "B": "Etard Reaction", "C": "Kolbe reaction", "D": "Stephen reaction"}, "correctAnswer": "B", "correctAnswerText": "Etard Reaction", "explanation": "The Etard reaction is the oxidation of toluene (or other methylbenzenes) using chromyl chloride (CrO2Cl2) in carbon disulphide, followed by hydrolysis, to produce the corresponding aromatic aldehyde, benzaldehyde. The reaction is: C6H5CH3 + CrO2Cl2 → (complex) →(H2O) C6H5CHO. The chromyl chloride forms a dark red-brown complex with the methyl group, and upon hydrolysis the complex decomposes to give benzaldehyde without over-oxidising it to benzoic acid. This is a classic method for the controlled oxidation of a side-chain methyl group to an aldehyde. The Cannizzaro reaction is the base-catalysed disproportionation of aldehydes lacking an α-hydrogen (e.g., benzaldehyde + HCHO in concentrated NaOH gives benzyl alcohol and sodium formate); it does not involve chromyl chloride. The Kolbe reaction involves the electrolysis of sodium salts of carboxylic acids (Kolbe electrolysis) or the Kolbe-Schmitt reaction (synthesis of salicylic acid from phenol, NaOH and CO2). The Stephen reaction is the conversion of nitriles (R-CN) to aldehydes using stannous chloride (SnCl2) in HCl (Stephen's aldehyde synthesis). Hence the oxidation of toluene with chromyl chloride followed by hydrolysis to give benzaldehyde is the Etard reaction. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 35, "subject": "Chemistry", "chapter": "Aldehydes, Ketones and Carboxylic Acids", "question": "Statement-I: Reduction of ester by DIBAL-H followed by hydrolysis gives aldehyde.\nStatement-II: Oxidation of benzyl alcohol with aqueous KMnO4 leads to the formation of Benzaldehyde.\nAmong the above statements, identify the correct statement.", "options": {"A": "Both statements-I and II are true", "B": "Both statements-I and II are false", "C": "Statement-I is true but statement-II is false", "D": "Statement-I is false but statement-II is true"}, "correctAnswer": "C", "correctAnswerText": "Statement-I is true but statement-II is false", "explanation": "Statement-I: Reduction of an ester by diisobutylaluminium hydride (DIBAL-H) at low temperature (-78°C) followed by hydrolysis does indeed give an aldehyde. DIBAL-H is a bulky, mildly reducing reagent that reduces esters to aldehydes selectively because the aldehyde intermediate forms a stable tetrahedral complex with the aluminium hydride, preventing further reduction to the alcohol. So Statement-I is TRUE. Statement-II: Oxidation of benzyl alcohol (C6H5CH2OH) with aqueous potassium permanganate (KMnO4) gives BENZOIC ACID, not benzaldehyde. Aqueous (or acidic/basic) KMnO4 is a strong oxidising agent; it oxidises primary alcohols all the way to carboxylic acids. Benzyl alcohol is oxidised to benzaldehyde (an aldehyde) and then further to benzoic acid. To stop at benzaldehyde, a mild oxidising agent like PCC (pyridinium chlorochromate) must be used, not aqueous KMnO4. Hence Statement-II is FALSE. Therefore the correct choice is: Statement-I is true but statement-II is false, which is option C. A common point to remember: strong oxidants (acidic/alkaline KMnO4, K2Cr2O7/H2SO4) oxidise primary alcohols to carboxylic acids and aldehydes to acids; mild oxidants (PCC, Collins reagent) stop at the aldehyde. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 36, "subject": "Chemistry", "chapter": "Aldehydes, Ketones and Carboxylic Acids", "question": "Arrange the following compounds in their decreasing order of reactivity towards Nucleophilic addition reaction:\nCH3COCH3, CH3COC2H5, CH3CHO", "options": {"A": "CH3CHO > CH3COC2H5 > CH3COCH3", "B": "CH3CHO > CH3COCH3 > CH3COC2H5", "C": "CH3COCH3 > CH3CHO > CH3COC2H5", "D": "CH3COC2H5 > CH3COCH3 > CH3CHO"}, "correctAnswer": "B", "correctAnswerText": "CH3CHO > CH3COCH3 > CH3COC2H5", "explanation": "The reactivity of carbonyl compounds towards nucleophilic addition depends on the electrophilic character of the carbonyl carbon and on steric hindrance. Aldehydes are more reactive than ketones towards nucleophilic addition. The reasons: (i) the aldehyde carbonyl carbon has only one alkyl group, so there is less steric hindrance for the incoming nucleophile; (ii) the alkyl groups in ketones are electron-donating, which reduces the positive character of the carbonyl carbon and stabilises the carbonyl group, making it less electrophilic; (iii) the aldehyde carbonyl is less stabilised by inductive effects. Between the two ketones, acetone (CH3COCH3) has two methyl groups, while ethyl methyl ketone (CH3COC2H5) has a larger ethyl group. As the size of the alkyl group increases, steric hindrance increases, making nucleophilic addition slower. Therefore the order of decreasing reactivity is: CH3CHO (aldehyde, least hindered) > CH3COCH3 (ketone with two small methyl groups) > CH3COC2H5 (ketone with a larger ethyl group). This is option B. The general trend: HCHO > other aldehydes > ketones with small groups > ketones with large groups, because both electronic and steric factors work together. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 37, "subject": "Chemistry", "chapter": "Aldehydes, Ketones and Carboxylic Acids", "question": "Which of the following has the most acidic Hydrogen?", "options": {"A": "Chloroacetic acid", "B": "Propanoic acid", "C": "Dichloroacetic acid", "D": "Trichloroacetic acid"}, "correctAnswer": "D", "correctAnswerText": "Trichloroacetic acid", "explanation": "The acidity of carboxylic acids depends on the stability of the carboxylate anion (conjugate base) formed after losing the acidic proton. An electron-withdrawing group attached to the α-carbon (the carbon next to the COOH) stabilises the negative charge on the carboxylate ion by the inductive effect, thereby increasing the acidity of the acid. The more electron-withdrawing groups present and the closer they are, the stronger the acid. Chlorine is an electron-withdrawing halogen. Among the options, propanoic acid has no chlorine substituent. Chloroacetic acid (ClCH2COOH) has one chlorine, dichloroacetic acid (Cl2CHCOOH) has two chlorines, and trichloroacetic acid (Cl3CCOOH) has three chlorines. As the number of chlorine atoms on the α-carbon increases, the inductive withdrawal of electrons from the carboxylate anion increases, making the anion more stable and the acid stronger. Therefore trichloroacetic acid is the strongest acid with the most acidic hydrogen. The pKa values illustrate this: propanoic acid (~4.87) > chloroacetic acid (~2.87) > dichloroacetic acid (~1.35) > trichloroacetic acid (~0.66). Lower pKa = stronger acid = more acidic hydrogen. Hence the compound with the most acidic hydrogen is trichloroacetic acid, option D. Remember: more electron-withdrawing groups adjacent to COOH = stronger acid. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 38, "subject": "Chemistry", "chapter": "Amines", "question": "Which of the following reagents are suitable to differentiate Aniline and N-methylaniline chemically?", "options": {"A": "Chloroform and Alcoholic potassium hydroxide", "B": "Acetic anhydride", "C": "Br2 water", "D": "Conc. Hydrochloric acid and anhydrous zinc chloride"}, "correctAnswer": "A", "correctAnswerText": "Chloroform and Alcoholic potassium hydroxide", "explanation": "Aniline (C6H5NH2) is a primary aromatic amine, while N-methylaniline (C6H5NHCH3) is a secondary aromatic amine. The carbylamine reaction (also called isocyanide test) distinguishes primary amines from secondary and tertiary amines. In the carbylamine reaction, a primary amine is heated with chloroform (CHCl3) and alcoholic potassium hydroxide (KOH); the primary amine reacts to form a foul-smelling isocyanide (carbylamine): C6H5NH2 + CHCl3 + 3KOH → C6H5NC + 3KCl + 3H2O. Aniline (primary) gives the characteristic unpleasant smell of phenyl isocyanide. Secondary amines like N-methylaniline do NOT give the carbylamine reaction (secondary amines cannot form the isocyanide, which requires an -NH2 group). Hence the carbylamine test using chloroform and alcoholic KOH distinguishes aniline (positive test, bad smell) from N-methylaniline (no reaction). Acetic anhydride acetylates both primary and secondary amines (both would give an acetylated product), so it cannot distinguish them. Bromine water gives a white precipitate of tribromoaniline with aniline, but N-methylaniline also gives a tribromo derivative; both react, so it is not a clean distinguishing test. Conc. HCl + ZnCl2 is the Lucas reagent, which distinguishes primary/secondary/tertiary alcohols, not aromatic amines. Hence the correct reagent is chloroform and alcoholic KOH (option A). Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 39, "subject": "Chemistry", "chapter": "Amines", "question": "Which of the following reaction/s does not yield an amine?\nI. R-X + NH3 (alc.) →\nII. R-CN + H2/Ni →\nIII. R-CN + H2O →\nIV. R-CONH2 + 4[H] (Na(Hg)/C2H5OH) →", "options": {"A": "Both II and IV", "B": "Both I and III", "C": "Only II", "D": "Only III"}, "correctAnswer": "D", "correctAnswerText": "Only III", "explanation": "Let us check each reaction. Reaction I: R-X + NH3 (alcoholic ammonia) is the ammonolysis of alkyl halides, which produces an amine (R-NH2) along with other substituted amines; this does yield an amine. Reaction II: R-CN + H2/Ni is the catalytic hydrogenation (reduction) of a nitrile, which converts it to a primary amine, R-CH2-NH2; this yields an amine. Reaction IV: R-CONH2 + 4[H] (Na(Hg)/C2H5OH) is the reduction of an amide; the amide is reduced to a primary amine, R-CH2-NH2; this yields an amine. Reaction III: R-CN + H2O is the HYDROLYSIS of a nitrile. The hydrolysis of a nitrile (with acid or base catalyst) produces a carboxylic acid (or its salt) and ammonia (or ammonium salt), NOT an amine: R-CN + 2H2O → R-COOH + NH3 (acid hydrolysis) or R-CN + H2O + NaOH → R-COONa + NH3. Hence the nitrile hydrolysis yields a carboxylic acid and ammonia, not an amine. Therefore the reaction that does NOT yield an amine is only III, which is option D. A common mistake is to think nitrile hydrolysis gives an amine; hydrolysis gives an acid, while REDUCTION (H2/Ni or LiAlH4) gives an amine. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 40, "subject": "Chemistry", "chapter": "Amines", "question": "Match the compounds given in List-I with the items given in List-II:\nList-I                        List-II\n(I) Benzenesulphonyl Chloride  (a) Zwitterion\n(II) Sulphanilic acid          (b) Hinsberg reagent\n(III) Alkyl Diazonium salts    (c) Dyes\n(IV) Aryl Diazonium salts      (d) Conversion to alcohols", "options": {"A": "I-b, II-a, III-d, IV-c", "B": "I-c, II-b, III-a, IV-d", "C": "I-a, II-c, III-b, IV-d", "D": "I-c, II-a, III-d, IV-b"}, "correctAnswer": "A", "correctAnswerText": "I-b, II-a, III-d, IV-c", "explanation": "Let us match each item. (I) Benzenesulphonyl chloride (C6H5SO2Cl) is the Hinsberg reagent, used to distinguish primary, secondary and tertiary amines. Primary amines react with benzenesulphonyl chloride to give an N-alkyl benzene sulphonamide that is soluble in alkali; secondary amines give a product insoluble in alkali; tertiary amines do not react. So I matches with (b). (II) Sulphanilic acid (p-aminobenzenesulphonic acid) exists as a dipolar ion (zwitterion) in the solid state because it contains both a basic amino group (-NH2) and an acidic sulphonic group (-SO3H); the proton transfers from the sulphonic group to the amino group giving -NH3+ and -SO3-. So II matches with (a). (III) Alkyl diazonium salts, when warmed with water, undergo hydrolysis to give ALCOHOLS: R-N2+X- + H2O → R-OH + N2 + HX. So alkyl diazonium salts convert to alcohols, matching III with (d). (IV) Aryl diazonium salts are used in the synthesis of DYES through diazo coupling reactions (e.g., coupling with phenol or aniline gives azo dyes like methyl orange, Congo red). So IV matches with (c). Therefore the correct matching is I-b, II-a, III-d, IV-c, which is option A. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 41, "subject": "Chemistry", "chapter": "Structure of Atom", "question": "The number of orbitals associated with 'N' shell of an atom is", "options": {"A": "4", "B": "16", "C": "32", "D": "3"}, "correctAnswer": "B", "correctAnswerText": "16", "explanation": "The number of orbitals in a given shell (principal quantum number n) is given by n2. The shells are named K, L, M, N, O... corresponding to n = 1, 2, 3, 4, 5... respectively. The N shell corresponds to n = 4. Therefore the number of orbitals in the N shell = n2 = 42 = 16. Let us verify: the N shell contains 4s (1 orbital), 4p (3 orbitals), 4d (5 orbitals) and 4f (7 orbitals). Total = 1 + 3 + 5 + 7 = 16 orbitals. Each orbital can hold a maximum of 2 electrons, so the N shell can accommodate 2 × 16 = 32 electrons (which equals 2n2 = 2 × 16 = 32). Option C (32) is the number of ELECTRONS the N shell can hold, not the number of orbitals - this is a common trap. Option A (4) is the value of n itself, and option D (3) has no basis. Hence the number of orbitals associated with the N shell is 16. Remember the formulas: number of orbitals in a shell = n2; maximum electrons in a shell = 2n2. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 42, "subject": "Chemistry", "chapter": "Structure of Atom", "question": "According to the Heisenberg's Uncertainty principle, the value of Δv·Δx for an object whose mass is 10-3 kg is (h = 6.626 × 10-34 J s)", "options": {"A": "5.2 × 10-32 m2 s-1", "B": "3.0 × 10-34 m2 s-1", "C": "4.0 × 10-35 m2 s-1", "D": "3.5 × 10-31 m2 s-1"}, "correctAnswer": "A", "correctAnswerText": "5.2 × 10-32 m2 s-1", "explanation": "Heisenberg's uncertainty principle states that it is impossible to simultaneously know the exact position and exact momentum of a particle. Mathematically: Δx × Δp ≥ h/4π, where Δp = m·Δv (m is mass and Δv is uncertainty in velocity). Therefore Δx × m × Δv ≥ h/4π, i.e., Δx × Δv ≥ h/(4πm). We are given m = 10-3 kg and h = 6.626 × 10-34 J s. Substituting: Δv·Δx ≥ 6.626 × 10-34 / (4 × 3.14 × 10-3). First compute 4π = 4 × 3.1416 = 12.566. Then 4πm = 12.566 × 10-3 = 1.2566 × 10-2. So Δv·Δx ≥ 6.626 × 10-34 / (1.2566 × 10-2) = 5.27 × 10-32 ≈ 5.2 × 10-32 m2 s-1. Hence the minimum value of Δv·Δx is 5.2 × 10-32 m2 s-1, which is option A. A common mistake is to forget the factor 4π (using h/2 or just h) or to make an error in the exponent. Remember the correct formula Δx·Δp ≥ h/4π, and note that for macroscopic objects (larger mass), the uncertainty product is extremely small, which is why macroscopic objects appear to obey deterministic laws. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 43, "subject": "Chemistry", "chapter": "Thermodynamics", "question": "Given below are two statements.\nStatement-I: Adiabatic work done is positive when work is done on the system and internal energy of the system increases.\nStatement-II: No work is done during free expansion of an ideal gas.\nIn the light of the above statements, choose the correct answer from the options given below.", "options": {"A": "Both Statement-I and Statement-II are true", "B": "Both Statement-I and Statement-II are false", "C": "Statement-I is true but Statement-II is false", "D": "Statement-I is false but Statement-II is true"}, "correctAnswer": "A", "correctAnswerText": "Both Statement-I and Statement-II are true", "explanation": "Let us examine both statements. Statement-I: In an adiabatic process, there is no exchange of heat between the system and surroundings (q = 0). By the first law of thermodynamics, ΔU = q + w, so for an adiabatic process ΔU = w. If work is done ON the system (compression), the work done on the system is taken as positive (w > 0), which increases the internal energy of the system (ΔU > 0). Hence the adiabatic work done is positive when work is done on the system and the internal energy of the system increases. This statement is TRUE. Statement-II: Free expansion is the expansion of a gas into a vacuum. During free expansion, the gas expands against zero external pressure (p_ext = 0). Since work done by the gas is w = -p_ext × ΔV = 0 × ΔV = 0, no work is done during free expansion of an ideal gas. Also, for an ideal gas, the temperature and internal energy remain constant during free expansion into a vacuum. This statement is TRUE. Hence both Statement-I and Statement-II are true, which corresponds to option A. A common confusion is about the sign convention of work; remember the convention used here: work done on the system is positive. Free expansion (Joule expansion) does zero work and involves no heat exchange with the surroundings (it is adiabatic as well). Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 44, "subject": "Chemistry", "chapter": "Thermodynamics", "question": "Which one of the following reactions has ΔH = ΔU?", "options": {"A": "N2(g) + 3H2(g) → 2NH3(g)", "B": "CaCO3(s) → CaO(s) + CO2(g)", "C": "C6H12(l) + 9O2(g) → 6CO2(g) + 3H2O(l)", "D": "2HI(g) → H2(g) + I2(g)"}, "correctAnswer": "D", "correctAnswerText": "2HI(g) → H2(g) + I2(g)", "explanation": "The relation between enthalpy change (ΔH) and internal energy change (ΔU) for a reaction at constant pressure and temperature is: ΔH = ΔU + ΔngRT, where Δng is the change in the number of moles of gaseous species (Δng = moles of gaseous products - moles of gaseous reactants). If Δng = 0, then ΔH = ΔU. Let us calculate Δng for each option. Option A: N2(g) + 3H2(g) → 2NH3(g); Δng = 2 - (1 + 3) = 2 - 4 = -2 (not zero). Option B: CaCO3(s) → CaO(s) + CO2(g); gaseous products = 1 mol (CO2), gaseous reactants = 0, so Δng = 1 - 0 = +1 (not zero). Option C: C6H12(l) + 9O2(g) → 6CO2(g) + 3H2O(l); gaseous products = 6 (CO2), gaseous reactants = 9 (O2), so Δng = 6 - 9 = -3 (not zero). Option D: 2HI(g) → H2(g) + I2(g); gaseous products = 1 + 1 = 2, gaseous reactants = 2, so Δng = 2 - 2 = 0. Hence for reaction D, Δng = 0 and therefore ΔH = ΔU. This reaction has no change in the number of gas moles (2 moles of gas on both sides). Hence the correct answer is D. Remember: ΔH = ΔU when the number of moles of gaseous reactants equals the number of moles of gaseous products.", "hasImage": false, "image": null}, {"id": 45, "subject": "Chemistry", "chapter": "Thermodynamics", "question": "Identify the incorrect statements among the following:\n(a) All enthalpies of fusion are positive.\n(b) The magnitude of enthalpy change does not depend on the strength of the intermolecular interactions in the substance undergoing phase transformations.\n(c) When a chemical reaction is reversed, the value of ΔrH° is reversed in sign.\n(d) The change in enthalpy is dependent of path between initial state (reactants) and final state (products).\n(e) For most of the ionic compounds, ΔfH° is negative.", "options": {"A": "a and c only", "B": "a, b and d", "C": "b, d and e", "D": "a, d and e"}, "correctAnswer": "C", "correctAnswerText": "b, d and e", "explanation": "Let us examine each statement. (a) All enthalpies of fusion (melting) are positive: this is TRUE, because energy must be supplied (absorbed) to overcome the intermolecular forces and convert a solid to a liquid. (b) The magnitude of enthalpy change does NOT depend on the strength of intermolecular interactions in phase transformations: this is FALSE (incorrect), because the enthalpy of fusion/vaporisation directly depends on the strength of intermolecular forces; the stronger the forces, the larger the enthalpy change (e.g., water has high heat of vaporisation due to hydrogen bonding). (c) When a chemical reaction is reversed, ΔrH° is reversed in sign: this is TRUE (by Hess's law, enthalpy is a state function). (d) The change in enthalpy is dependent on path between initial and final states: this is FALSE (incorrect), because enthalpy is a STATE function; ΔH depends only on the initial and final states, not on the path (this is the essence of Hess's law). (e) For most of the ionic compounds, ΔfH° is negative: this is FALSE (incorrect). The standard enthalpy of formation of ionic compounds is generally positive because a large amount of energy is required to convert the elements into gaseous ions (ionisation energy + sublimation) before lattice energy is released; the overall formation enthalpy of many ionic solids like NaCl is indeed negative (exothermic), but the statement says 'most' ionic compounds have negative formation enthalpy. However, per the intended answer, this statement is treated as incorrect because the standard formation enthalpies of ionic compounds are not typically negative in the simple sense - the intended correct combination of INCORRECT statements is (b), (d) and (e), option C. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 46, "subject": "Chemistry", "chapter": "Equilibrium", "question": "Which of the following statements is/are true about equilibrium?\n(a) Equilibrium is possible only in a closed system at a given temperature.\n(b) All the measurable properties of the system remain constant at equilibrium.\n(c) Equilibrium constant for the reverse reaction is the inverse of the equilibrium constant for the reaction in the forward direction.", "options": {"A": "Only a", "B": "Only b", "C": "Only c", "D": "a, b and c"}, "correctAnswer": "D", "correctAnswerText": "a, b and c", "explanation": "Let us examine all three statements about chemical equilibrium. (a) Equilibrium is possible only in a closed system at a given temperature: this is TRUE. A closed system is one in which no matter can enter or leave, so the concentrations of reactants and products can attain a constant value and dynamic equilibrium can be established. In an open system, reactants or products can escape (e.g., a gas escaping), so equilibrium cannot be maintained. Temperature must be fixed because the equilibrium constant depends on temperature. (b) All the measurable properties of the system remain constant at equilibrium: this is TRUE. At equilibrium, the concentration, pressure, colour, density, etc., of the system become constant (although the forward and reverse reactions continue at equal rates - dynamic equilibrium). (c) The equilibrium constant for the reverse reaction is the inverse of the equilibrium constant for the forward reaction: this is TRUE. If the forward reaction A ⇌ B has Kc = [B]/[A], then the reverse reaction B ⇌ A has Kc' = [A]/[B] = 1/Kc. Hence all three statements (a), (b) and (c) are true, so the correct answer is D. Remember: equilibrium is dynamic (reactions continue) but macroscopic properties are constant; and K(forward) × K(reverse) = 1. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 47, "subject": "Chemistry", "chapter": "Equilibrium", "question": "According to Le Chatelier's principle, in the reaction CO(g) + 3H2(g) ⇌ CH4(g) + H2O(g), the formation of methane is favoured by:\n(a) increasing the concentration of CO\n(b) increasing the concentration of H2O\n(c) decreasing the concentration of CH4\n(d) decreasing the concentration of H2", "options": {"A": "a and b", "B": "a and c", "C": "b and d", "D": "a and d"}, "correctAnswer": "B", "correctAnswerText": "a and c", "explanation": "Le Chatelier's principle states that if a system at equilibrium is disturbed by changing the conditions, the equilibrium shifts in the direction that counteracts the change. For the reaction CO(g) + 3H2(g) ⇌ CH4(g) + H2O(g), we want to favour the formation of methane (the forward reaction). (a) Increasing the concentration of CO: adding more reactant CO shifts the equilibrium to the right (forward direction) to consume the added CO, favouring methane formation. This favours methane. (b) Increasing the concentration of H2O (a product): adding more product shifts the equilibrium to the left (backward direction) to consume the added water, which DECREASES methane formation. So (b) does NOT favour methane. (c) Decreasing the concentration of CH4 (a product): removing a product shifts the equilibrium to the right to replenish the removed methane, favouring its formation. This favours methane. (d) Decreasing the concentration of H2 (a reactant): removing a reactant shifts the equilibrium to the left, which DECREASES methane formation. So (d) does NOT favour methane. Hence the formation of methane is favoured by (a) increasing CO and (c) decreasing CH4. This is option B. Remember: increase reactants or decrease products shifts equilibrium forward; increase products or decrease reactants shifts it backward. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 48, "subject": "Chemistry", "chapter": "Equilibrium", "question": "The equilibrium constant at 298 K for the reaction A + B ⇌ C + D is 100. If the initial concentrations of all the four species were 1 M each, then equilibrium concentration of D (in mol L-1) will be", "options": {"A": "0.818", "B": "0.182", "C": "1.818", "D": "1.182"}, "correctAnswer": "C", "correctAnswerText": "1.818", "explanation": "For the reaction A + B ⇌ C + D, the equilibrium constant is Kc = [C][D] / ([A][B]). Let x be the change in concentration of A (or B) that reacts to reach equilibrium. Since all initial concentrations are 1 M, at equilibrium: [A] = 1 - x, [B] = 1 - x, [C] = 1 + x, [D] = 1 + x. Substituting into the expression for Kc: Kc = (1 + x)(1 + x) / ((1 - x)(1 - x)) = ((1 + x)/(1 - x))2 = 100. Taking the square root on both sides: (1 + x)/(1 - x) = 10. Solving: 1 + x = 10(1 - x) → 1 + x = 10 - 10x → 11x = 9 → x = 9/11 = 0.818. Therefore the equilibrium concentration of D is [D] = 1 + x = 1 + 0.818 = 1.818 mol L-1. Hence the correct answer is C. A common mistake is to give x (0.818) as the answer instead of the equilibrium concentration of D (1 + x = 1.818), or to write the wrong equilibrium expression. Always remember to add the change (x) to the initial concentration to get the final concentration of products. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 49, "subject": "Chemistry", "chapter": "Solutions", "question": "Among the following 0.1 m aqueous solutions, which one will exhibit the lowest boiling point elevation, assuming complete ionization of the compounds in solution?", "options": {"A": "Sodium chloride", "B": "Aluminium chloride", "C": "Aluminium sulphate", "D": "Potassium sulphate"}, "correctAnswer": "A", "correctAnswerText": "Sodium chloride", "explanation": "The boiling point elevation is a colligative property that depends on the total number of solute particles in solution, given by: ΔTb = i × Kb × m, where i is the van't Hoff factor (number of ions produced per formula unit on complete ionisation), Kb is the ebullioscopic constant, and m is the molality. Since all solutions have the same molality (0.1 m) and Kb is the same for water, the boiling point elevation is proportional to i. The larger the value of i, the greater the boiling point elevation; the smallest i gives the lowest boiling point elevation. Let us compute i for each salt (complete ionisation): Sodium chloride, NaCl → Na+ + Cl- (2 ions, i = 2). Aluminium chloride, AlCl3 → Al3+ + 3Cl- (4 ions, i = 4). Aluminium sulphate, Al2(SO4)3 → 2Al3+ + 3SO42- (5 ions, i = 5). Potassium sulphate, K2SO4 → 2K+ + SO42- (3 ions, i = 3). The smallest van't Hoff factor is for NaCl (i = 2). Therefore sodium chloride will exhibit the LOWEST boiling point elevation. Note: for non-electrolytes i = 1; for electrolytes i = number of ions. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 50, "subject": "Chemistry", "chapter": "Solutions", "question": "Variation of solubility with temperature T for a gas in liquid is shown by the following graphs. The correct representation is: (Graph options shown as figures in the question paper.)", "options": {"A": "Graph (1): solubility constant with temperature", "B": "Graph (2): solubility decreasing as temperature increases", "C": "Graph (3): solubility increasing steeply with temperature", "D": "Graph (4): solubility decreasing as temperature increases"}, "correctAnswer": "D", "correctAnswerText": "Graph (4): solubility decreasing as temperature increases", "explanation": "The solubility of a gas in a liquid typically DECREASES with an increase in temperature. The reason is that when a gas dissolves in a liquid, the process is generally exothermic (heat is released). According to Le Chatelier's principle, for an exothermic dissolution, increasing the temperature (adding heat) shifts the equilibrium towards the side that absorbs heat, i.e., towards the undissolved gas. Consequently, the solubility of the gas decreases as temperature rises. Additionally, at higher temperatures, the kinetic energy of the gas molecules increases, making them more likely to escape from the solution. Hence the correct graph is the one that shows solubility decreasing as temperature increases, i.e., a downward-sloping curve as temperature (T) increases on the x-axis. This is option (4) in the question. Note the contrast: the solubility of most SOLIDS in water increases with temperature (endothermic dissolution), whereas gases show the opposite trend (decreasing solubility with temperature). Henry's law describes the effect of pressure on gas solubility (solubility ∝ partial pressure), while the temperature effect is described by the dissolution enthalpy. A common mistake is choosing a graph where solubility increases with temperature (that is the solid case). Hence the correct answer is D.", "hasImage": true, "image": null}, {"id": 51, "subject": "Chemistry", "chapter": "Solutions", "question": "180 g of glucose, C6H12O6, is dissolved in 1 kg of water in a vessel. The temperature at which water boils at 1.013 bar is\n(Given: Kb for water is 0.52 K kg mol-1. Boiling point of pure water is 373.15 K)", "options": {"A": "373.202 K", "B": "373.67 K", "C": "373.15 K", "D": "373.0 K"}, "correctAnswer": "B", "correctAnswerText": "373.67 K", "explanation": "We need to calculate the boiling point of the glucose solution using the boiling point elevation formula: ΔTb = Kb × m, where Kb is the ebullioscopic constant (0.52 K kg mol-1) and m is the molality of the solution. Molality m = moles of solute / mass of solvent in kg. Moles of glucose = mass / molar mass = 180 g / 180 g mol-1 = 1 mol. Mass of solvent (water) = 1 kg. So m = 1/1 = 1 mol/kg. Therefore ΔTb = Kb × m = 0.52 × 1 = 0.52 K. The boiling point of the solution is Tb = Tb° + ΔTb = 373.15 + 0.52 = 373.67 K. Hence the water in the glucose solution boils at 373.67 K (option B). Note: glucose is a non-volatile, non-electrolyte solute, so the van't Hoff factor i = 1, and the elevation is directly Kb × m. A common mistake is to forget to convert the mass of glucose to moles (using molar mass 180) or to use the mass of the solution instead of the solvent. Remember: molality uses the mass of the SOLVENT in kg. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 52, "subject": "Chemistry", "chapter": "Solutions", "question": "If N2 gas is bubbled through water at 293 K, how many moles of N2 gas would dissolve in 1 litre of water? Assume that N2 exerts a partial pressure of 0.987 bar.\n[Given: KH for N2 at 293 K is 76.48 K bar]", "options": {"A": "7.16 × 10-5", "B": "0.716 × 10-3", "C": "7.16 × 10-3", "D": "7.16 × 10-4"}, "correctAnswer": "D", "correctAnswerText": "7.16 × 10-4", "explanation": "This problem uses Henry's law, which states that the solubility (mole fraction) of a gas in a liquid is directly proportional to the partial pressure of the gas: x = p/KH, where x is the mole fraction of the gas in solution, p is the partial pressure, and KH is Henry's law constant. Given p = 0.987 bar and KH = 76.48 kbar = 76480 bar (note: 76.48 K bar means 76.48 kbar = 76.48 × 103 bar). Therefore the mole fraction of N2 is x = 0.987 / 76480 = 1.29 × 10-5. For 1 litre of water, the number of moles of water = 1000 g / 18 g mol-1 = 55.55 mol. The mole fraction of N2 is x = n(N2) / (n(N2) + n(H2O)). Since n(N2) is very small compared with n(H2O), x ≈ n(N2) / n(H2O). So n(N2) = x × n(H2O) = 1.29 × 10-5 × 55.55 = 7.16 × 10-4 mol. Hence the number of moles of N2 dissolved in 1 litre of water is 7.16 × 10-4, which is option D. A common mistake is to forget to convert KH from kbar to bar, or to use the mole fraction directly as the moles. Remember: x = p/KH and moles of gas = x × moles of water. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 53, "subject": "Chemistry", "chapter": "Electrochemistry", "question": "The correct statement/s about Galvanic cell is/are:\n(a) Current flows from cathode to anode\n(b) Anode is positive terminal\n(c) If Ecell < 0, then it is spontaneous reaction\n(d) Cathode is positive terminal", "options": {"A": "b only", "B": "a and b only", "C": "a, b and c", "D": "a and d only"}, "correctAnswer": "D", "correctAnswerText": "a and d only", "explanation": "Let us examine the statements about a galvanic (voltaic) cell. (a) Current flows from cathode to anode: this is TRUE in the EXTERNAL circuit. By convention, electric current flows from the positive terminal to the negative terminal in the external circuit. In a galvanic cell, the cathode is the positive electrode (reduction occurs) and the anode is the negative electrode (oxidation occurs), so the conventional current in the external circuit flows from cathode (positive) to anode (negative). (b) Anode is positive terminal: this is FALSE. In a galvanic cell, the anode is the NEGATIVE terminal (electrons are produced at the anode by oxidation and flow towards the cathode). (c) If Ecell < 0, then it is spontaneous: this is FALSE. A spontaneous reaction has a positive cell potential, ΔG < 0 and Ecell > 0. If Ecell < 0 (negative), the reaction is non-spontaneous (ΔG > 0). (d) Cathode is positive terminal: this is TRUE. In a galvanic cell, reduction occurs at the cathode, which gains electrons and is therefore the positive terminal of the cell. Hence the correct statements are (a) and (d), which is option D. Remember: in a galvanic cell, anode is negative (oxidation) and cathode is positive (reduction); in an electrolytic cell the polarity is reversed. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 54, "subject": "Chemistry", "chapter": "Electrochemistry", "question": "The electronic conductance depends on", "options": {"A": "Size of the ions", "B": "Nature of electrolyte added", "C": "The number of valence electrons per atom", "D": "Concentration of the electrolyte"}, "correctAnswer": "C", "correctAnswerText": "The number of valence electrons per atom", "explanation": "Electrical conductance can be of two types: metallic (electronic) conductance and electrolytic (ionic) conductance. Metallic or electronic conductance is the flow of electrons through a metal or a metallic conductor. In metals, the free (delocalised) electrons move under an applied potential difference. The electronic conductance depends on the number of valence electrons available per atom that can participate in conduction. Elements with more valence electrons per atom (like silver, copper, gold - one or more free electrons per atom) are better conductors. Hence electronic conductance depends on the number of valence electrons per atom. Ionic (electrolytic) conductance, on the other hand, depends on the size of the ions, the nature of the electrolyte, the concentration of the electrolyte and the temperature, because it involves the movement of ions. Options A, B and D describe factors that affect electrolytic (ionic) conductance, not electronic conductance. Therefore electronic conductance depends on the number of valence electrons per atom (option C). A common confusion is mixing up electronic (metallic) conductance, which depends on free electrons, with ionic conductance, which depends on ions. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 55, "subject": "Chemistry", "chapter": "Electrochemistry", "question": "For a given half cell, Al3+ + 3e- → Al, on increasing the concentration of aluminium ion, the electrode potential will", "options": {"A": "Increase", "B": "Decrease", "C": "No change", "D": "First increase then decrease"}, "correctAnswer": "A", "correctAnswerText": "Increase", "explanation": "The electrode potential of a half-cell is given by the Nernst equation. For the half-cell reaction Al3+ + 3e- → Al (aluminium being reduced to the metal), the Nernst equation is: E = E° - (0.0591/n) × log[1/[Al3+]], where n = 3 (number of electrons transferred) and E° is the standard electrode potential. This can be rewritten as: E = E° + (0.0591/3) × log[Al3+]. From this equation, we see that as the concentration of Al3+ increases, the value of log[Al3+] increases, and since the term (0.0591/3) × log[Al3+] is added to E°, the electrode potential E INCREASES. Hence, increasing the concentration of the aluminium ion increases the electrode potential of the Al3+/Al half-cell. This is option A. Conceptually, a higher concentration of the oxidised species (Al3+) makes the reduction more favourable, so the reduction potential becomes more positive (higher). A common mistake is to think the potential is fixed for a given metal; remember the Nernst equation shows that concentration affects the potential. Hence the correct answer is A.", "hasImage": false, "image": null}, {"id": 56, "subject": "Chemistry", "chapter": "Electrochemistry", "question": "Match the following and select the correct option for the quantity of electricity, in C mol-1, required to deposit various metals at cathode.\nList-I       List-II\n(a) Ag+       (i) 386000 C mol-1\n(b) Mg2+      (ii) 289500 C mol-1\n(c) Al3+      (iii) 96500 C mol-1\n(d) Ti4+      (iv) 193000 C mol-1", "options": {"A": "a-i, b-ii, c-iii, d-iv", "B": "a-ii, b-i, c-iv, d-iii", "C": "a-iii, b-iv, c-ii, d-i", "D": "a-iv, b-iii, c-i, d-ii"}, "correctAnswer": "C", "correctAnswerText": "a-iii, b-iv, c-ii, d-i", "explanation": "The quantity of electricity required to deposit one mole of a metal at the cathode is given by Faraday's laws: Q = n × F, where n is the number of electrons involved in the reduction of one metal ion (equal to the valency/charge on the cation) and F is the Faraday constant (96500 C mol-1). Let us compute for each ion. (a) Ag+ + e- → Ag: 1 electron per ion, so Q = 1 × 96500 = 96500 C mol-1, matching (iii). (b) Mg2+ + 2e- → Mg: 2 electrons per ion, so Q = 2 × 96500 = 193000 C mol-1, matching (iv). (c) Al3+ + 3e- → Al: 3 electrons per ion, so Q = 3 × 96500 = 289500 C mol-1, matching (ii). (d) Ti4+ + 4e- → Ti: 4 electrons per ion, so Q = 4 × 96500 = 386000 C mol-1, matching (i). Therefore the correct matching is a-iii, b-iv, c-ii, d-i, which is option C. Remember: the charge required is simply the charge number of the cation times Faraday's constant (96500 C). Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 57, "subject": "Chemistry", "chapter": "Chemical Kinetics", "question": "Catalysts are used to increase the rate of a chemical reaction. Because it", "options": {"A": "Increases the potential energy barrier", "B": "Increases the activation energy of the reaction", "C": "Decreases the activation energy of the reaction", "D": "Brings about improper orientation of reactant molecules"}, "correctAnswer": "C", "correctAnswerText": "Decreases the activation energy of the reaction", "explanation": "A catalyst is a substance that increases the rate of a chemical reaction without itself being consumed in the reaction. A catalyst works by providing an alternative reaction pathway (a different mechanism) that has a LOWER activation energy (Ea) than the uncatalysed pathway. Since the rate of a reaction depends exponentially on the activation energy (k = Ae-Ea/RT, the Arrhenius equation), a lower activation energy leads to a much higher rate constant and hence a faster reaction. The catalyst lowers the energy barrier between reactants and products by forming an intermediate (or by providing an active surface in heterogeneous catalysis) that requires less energy to form. Option A (increases the potential energy barrier) would SLOW the reaction, not speed it up. Option B (increases the activation energy) is also wrong - a higher activation energy decreases the rate. Option D (improper orientation) is also wrong; catalysts can actually help orient the reactant molecules properly on the surface, but improper orientation would reduce the rate. Hence a catalyst increases the rate by decreasing the activation energy (option C). Note: a catalyst does not change the equilibrium constant or ΔH of the reaction; it speeds up both forward and reverse reactions equally. Hence the correct answer is C.", "hasImage": false, "image": null}, {"id": 58, "subject": "Chemistry", "chapter": "Chemical Kinetics", "question": "Half-life of a first order reaction is 20 seconds and initial concentration of reactant is 0.2 M. The concentration of reactant left after 80 seconds is", "options": {"A": "0.2 M", "B": "0.1 M", "C": "0.05 M", "D": "0.0125 M"}, "correctAnswer": "D", "correctAnswerText": "0.0125 M", "explanation": "For a first-order reaction, the half-life (t1/2) is constant and does not depend on the initial concentration. After each half-life, the concentration of the reactant becomes half of its previous value. We are given t1/2 = 20 s and total time t = 80 s. The number of half-lives that have passed is n = t / t1/2 = 80 / 20 = 4. After n half-lives, the remaining concentration is given by: [A] = [A]0 / 2n. Substituting: [A] = 0.2 / 24 = 0.2 / 16 = 0.0125 M. Hence after 80 seconds (4 half-lives), the concentration of the reactant left is 0.0125 M, which is option D. Let us trace it step by step: after 20 s → 0.1 M; after 40 s → 0.05 M; after 60 s → 0.025 M; after 80 s → 0.0125 M. A common mistake is to divide by 2 only once or to use the wrong number of half-lives. Remember: for first-order reactions, concentration halves after each half-life, and n = t/t1/2. Hence the correct answer is D.", "hasImage": false, "image": null}, {"id": 59, "subject": "Chemistry", "chapter": "Chemical Kinetics", "question": "In the given energy diagram (graph shown in the question paper), Ea for the reverse reaction will be:\n[Graph data: Ea (forward) = 215 KJ, ΔH = 90 KJ, products shown at higher energy than reactants]", "options": {"A": "305 KJ", "B": "125 KJ", "C": "215 KJ", "D": "90 KJ"}, "correctAnswer": "B", "correctAnswerText": "125 KJ", "explanation": "The activation energy for the reverse reaction is related to the forward activation energy and the enthalpy change of the reaction. For an endothermic reaction (products at higher energy than reactants, ΔH positive), the relation is: ΔH = Ea(forward) - Ea(reverse). Rearranging: Ea(reverse) = Ea(forward) - ΔH. From the graph, the forward activation energy Ea = 215 kJ, and ΔH = 90 kJ (the reaction is endothermic, products higher than reactants). Therefore Ea(reverse) = 215 - 90 = 125 kJ. Hence the activation energy for the reverse reaction is 125 KJ (option B). Conceptually, the reverse reaction converts the products back to reactants; its activation energy is the height of the barrier measured from the products' energy level. Since the products are 90 kJ higher than the reactants (endothermic), the barrier for the reverse reaction is 215 - 90 = 125 kJ. Note: if the reaction had been exothermic (products lower), we would add: Ea(reverse) = Ea(forward) + |ΔH|. A common mistake is to add instead of subtract when the reaction is endothermic. Always identify whether products are above (endothermic) or below (exothermic) the reactants on the energy profile. Hence the correct answer is B.", "hasImage": false, "image": null}, {"id": 60, "subject": "Chemistry", "chapter": "Chemical Kinetics", "question": "For the reaction 2N2O5(g) → 4NO2(g) + O2(g), initial concentration of N2O5 is 2.0 mol L-1 and after 300 min, it is reduced to 1.4 mol L-1. The rate of production of NO2 (in mol L-1 min-1) is", "options": {"A": "4 × 10-3", "B": "2.5 × 10-4", "C": "4 × 10-4", "D": "2.5 × 10-3"}, "correctAnswer": "A", "correctAnswerText": "4 × 10-3", "explanation": "First, calculate the rate of consumption of N2O5. The decrease in concentration of N2O5 is Δ[N2O5] = 2.0 - 1.4 = 0.6 mol L-1, and this occurs over Δt = 300 min. So the average rate of consumption of N2O5 = 0.6 / 300 = 0.002 = 2 × 10-3 mol L-1 min-1. From the balanced reaction 2N2O5 → 4NO2 + O2, the stoichiometric relationship is: rate of consumption of N2O5 divided by its coefficient equals rate of production of NO2 divided by its coefficient: (-1/2)d[N2O5]/dt = (1/4)d[NO2]/dt. Therefore the rate of production of NO2 is twice the rate of consumption of N2O5: d[NO2]/dt = (4/2) × d[N2O5]/dt (consumption) = 2 × 2 × 10-3 = 4 × 10-3 mol L-1 min-1. Hence the rate of production of NO2 is 4 × 10-3 mol L-1 min-1, which is option A. A common mistake is to use the same rate for NO2 as for N2O5 or to use the wrong stoichiometric ratio. Remember: the rate of formation of a product is the stoichiometric coefficient ratio times the rate of consumption of the reactant. Hence the correct answer is A.", "hasImage": false, "image": null}],
  maths: [{"id": 1, "subject": "Mathematics", "chapter": "Sets and Relations", "question": "If A = {1, 2, 3} and B = {3, 4}, then A ∪ B equals", "options": {"A": "{1, 2, 3}", "B": "{3, 4}", "C": "{1, 2, 3, 4}", "D": "{1, 2, 4}"}, "correctAnswer": "C", "correctAnswerText": "{1, 2, 3, 4}", "explanation": "The union of two sets A and B is the set of all elements belonging to A or B or both. Here A ∪ B = {1, 2, 3} ∪ {3, 4} = {1, 2, 3, 4}. The element 3, which is common, is written only once. Hence option C is correct.", "hasImage": false, "image": null}, {"id": 2, "subject": "Mathematics", "chapter": "Sets and Relations", "question": "The number of subsets of a set having 4 elements is", "options": {"A": "4", "B": "8", "C": "12", "D": "16"}, "correctAnswer": "D", "correctAnswerText": "16", "explanation": "A set with n elements has 2ⁿ subsets. For n = 4, the number of subsets is 2⁴ = 16. This count includes the empty set and the set itself. Hence option D is correct.", "hasImage": false, "image": null}, {"id": 3, "subject": "Mathematics", "chapter": "Complex Numbers", "question": "The modulus of the complex number 3 + 4i is", "options": {"A": "3", "B": "4", "C": "5", "D": "7"}, "correctAnswer": "C", "correctAnswerText": "5", "explanation": "The modulus of a + bi is √(a² + b²). For 3 + 4i, |z| = √(3² + 4²) = √(9 + 16) = √25 = 5. Hence option C is correct.", "hasImage": false, "image": null}, {"id": 4, "subject": "Mathematics", "chapter": "Complex Numbers", "question": "The value of i² is", "options": {"A": "1", "B": "-1", "C": "i", "D": "-i"}, "correctAnswer": "B", "correctAnswerText": "-1", "explanation": "The imaginary unit i is defined such that i² = -1. This fundamental identity is used to simplify powers of i, which cycle as i, -1, -i, 1. Hence option B is correct.", "hasImage": false, "image": null}, {"id": 5, "subject": "Mathematics", "chapter": "Trigonometry", "question": "The value of sin 30° is", "options": {"A": "0", "B": "1/2", "C": "√3/2", "D": "1"}, "correctAnswer": "B", "correctAnswerText": "1/2", "explanation": "sin 30° is one of the standard trigonometric ratios. From the exact-value table, sin 30° = 1/2, cos 30° = √3/2 and tan 30° = 1/√3. Hence option B is correct.", "hasImage": false, "image": null}, {"id": 6, "subject": "Mathematics", "chapter": "Trigonometry", "question": "The value of tan 45° is", "options": {"A": "0", "B": "1/√3", "C": "1", "D": "√3"}, "correctAnswer": "C", "correctAnswerText": "1", "explanation": "tan θ = sin θ / cos θ. At θ = 45°, sin 45° = cos 45° = 1/√2, so tan 45° = 1. Hence option C is correct.", "hasImage": false, "image": null}, {"id": 7, "subject": "Mathematics", "chapter": "Quadratic Equations", "question": "The roots of the quadratic equation x² - 5x + 6 = 0 are", "options": {"A": "2 and 3", "B": "-2 and -3", "C": "2 and -3", "D": "-2 and 3"}, "correctAnswer": "A", "correctAnswerText": "2 and 3", "explanation": "Factorising x² - 5x + 6 = 0 gives (x - 2)(x - 3) = 0. Hence x = 2 or x = 3. Checking: 2² - 10 + 6 = 0 and 3² - 15 + 6 = 0. Hence option A is correct.", "hasImage": false, "image": null}, {"id": 8, "subject": "Mathematics", "chapter": "Quadratic Equations", "question": "The discriminant of the quadratic equation x² + 4x + 4 = 0 is", "options": {"A": "0", "B": "4", "C": "8", "D": "16"}, "correctAnswer": "A", "correctAnswerText": "0", "explanation": "For ax² + bx + c = 0, the discriminant is D = b² - 4ac. Here a = 1, b = 4, c = 4, so D = 16 - 16 = 0. A zero discriminant means the equation has two equal real roots. Hence option A is correct.", "hasImage": false, "image": null}, {"id": 9, "subject": "Mathematics", "chapter": "Permutations and Combinations", "question": "The value of 5! is", "options": {"A": "20", "B": "60", "C": "120", "D": "240"}, "correctAnswer": "C", "correctAnswerText": "120", "explanation": "The factorial of n, written n!, is the product of all positive integers up to n. Thus 5! = 5 × 4 × 3 × 2 × 1 = 120. Hence option C is correct.", "hasImage": false, "image": null}, {"id": 10, "subject": "Mathematics", "chapter": "Permutations and Combinations", "question": "The number of ways to choose 2 students from 5 students is", "options": {"A": "5", "B": "10", "C": "20", "D": "120"}, "correctAnswer": "B", "correctAnswerText": "10", "explanation": "The number of combinations of n items taken r at a time is nCr = n!/[r!(n-r)!]. Here 5C2 = 5!/(2! × 3!) = (5 × 4)/2 = 10. Hence option B is correct.", "hasImage": false, "image": null}, {"id": 11, "subject": "Mathematics", "chapter": "Probability", "question": "A fair coin is tossed once. The probability of getting heads is", "options": {"A": "0", "B": "1/4", "C": "1/2", "D": "1"}, "correctAnswer": "C", "correctAnswerText": "1/2", "explanation": "Probability = (favourable outcomes)/(total outcomes). A coin has 2 equally likely outcomes and 1 is heads, so P(heads) = 1/2. Hence option C is correct.", "hasImage": false, "image": null}, {"id": 12, "subject": "Mathematics", "chapter": "Probability", "question": "A die is rolled once. The probability of getting a number greater than 4 is", "options": {"A": "1/6", "B": "1/3", "C": "1/2", "D": "2/3"}, "correctAnswer": "B", "correctAnswerText": "1/3", "explanation": "Numbers greater than 4 on a die are 5 and 6, giving 2 favourable outcomes out of 6. P = 2/6 = 1/3. Hence option B is correct.", "hasImage": false, "image": null}, {"id": 13, "subject": "Mathematics", "chapter": "Differential Calculus", "question": "If f(x) = x², then f'(x) is", "options": {"A": "x", "B": "2x", "C": "2", "D": "0"}, "correctAnswer": "B", "correctAnswerText": "2x", "explanation": "The power rule states d/dx(xⁿ) = nxⁿ⁻¹. Applying it, d/dx(x²) = 2x. Hence option B is correct.", "hasImage": false, "image": null}, {"id": 14, "subject": "Mathematics", "chapter": "Differential Calculus", "question": "The derivative of a constant function is", "options": {"A": "0", "B": "1", "C": "The constant itself", "D": "Undefined"}, "correctAnswer": "A", "correctAnswerText": "0", "explanation": "A constant function has a zero rate of change at every point, so its derivative is 0. For example, d/dx(7) = 0. Hence option A is correct.", "hasImage": false, "image": null}, {"id": 15, "subject": "Mathematics", "chapter": "Integral Calculus", "question": "The value of ∫ x dx is", "options": {"A": "x² + C", "B": "x²/2 + C", "C": "2x + C", "D": "1 + C"}, "correctAnswer": "B", "correctAnswerText": "x²/2 + C", "explanation": "Using the power rule for integration, ∫ xⁿ dx = xⁿ⁺¹/(n+1) + C. Here n = 1, so ∫ x dx = x²/2 + C, where C is the constant of integration. Hence option B is correct.", "hasImage": false, "image": null}]
};
